-- Match Your Colors: reader for the game's slim data files, the runtime half of the research prototype
-- research/slim.py (byte-identical results, tests/test_slim.lua).
--
-- data/bundles.nxa is a DSAR file: a table of chunks (LZ4 blocks or stored bytes) whose concatenation is the
-- DSAA index (14.5 MB in build 25480438). The index starts with 24-byte item records sorted by name
-- ('<16 hex>', '<16 hex>.gpu_resources', '<16 hex>.stream'; size u64, name offset u32, entry count u32,
-- entry offset u64), the bundle name offsets and the names (about 460 KB in all), then each item's entries
-- {offset in the item u32, offset in a bundle's uncompressed space u32 at +8, bundle number u8 at +15}. Each
-- bundle data/bundles.NN.nxa is again a DSAR file. An archive's main item starts with its table of contents
-- (72-byte header, 32-byte type entries, 80-byte file entries) that locates each resource's main, stream and
-- GPU parts in the three items.
--
-- Nothing here runs per frame: the mod reads files only while a recolor job runs. Only the index's head is
-- kept (read once, binary-searched by name); entries and chunks are read on demand into reused buffers.
-- Every call raises on malformed data.
local ffi = require('ffi')
local bit = require('bit')
local band, rshift = bit.band, bit.rshift
local format, byte = string.format, string.byte

local Slim = {}

local HIGH = 4294967296
local CHUNK_RECORD = 32
local ITEM_RECORD = 24
local ENTRY_RECORD = 16
local TOC_HEADER, TOC_TYPE, TOC_FILE = 72, 32, 80
local STORED_DIRECT = 4194304 -- stored chunks above this size are read in place, never whole
-- Decoded chunks kept: reads alternating between two regions (an ID mask's layers) decode each chunk once, also
-- where a read crosses a chunk boundary.
local CHUNK_SLOTS = 3
-- Decoded small chunks (SMALL_CHUNK bytes or less) are kept apart, each in its own buffer, up to SMALL_BYTES in all
-- for the reader's life (then let go all at once): an analysis reads the same small chunks (materials, texture heads)
-- again and again, and the three slots had let them go between uses (2026-10-08, 17 Armory-like jobs on the game's
-- files: 436 of 483 repeated decodes were of chunks of 4 KB or less, about half of a new item's reads in all).
Slim.SMALL_CHUNK, Slim.SMALL_BYTES = 16384, 1048576
local ENTRY_CACHE = 16
Slim.TOC_MAGIC = 0xF0000011

-- Little-endian unsigned readers over a uint8_t pointer (numbers, exact below 2^53).
local function u32(p, o)
    return p[o] + p[o + 1] * 256 + p[o + 2] * 65536 + p[o + 3] * 16777216
end
local function u64(p, o)
    return u32(p, o) + u32(p, o + 4) * HIGH
end
Slim.u32, Slim.u64 = u32, u64

-- The 16 lowercase hex digits of a 64-bit name given as two 32-bit halves.
function Slim.hex(high, low)
    return format('%08x%08x', high, low)
end

-- The length of a run of bytes that LZ4 encodes as 15 plus extension bytes; returns the length and the next
-- input position.
local function extended(src, ip, src_size, length)
    local b
    repeat
        if ip >= src_size then error('lz4: truncated length', 0) end
        b = src[ip]
        ip = ip + 1
        length = length + b
    until b ~= 255
    return length, ip
end

-- Copies one sequence's literals (count from the token's high nibble); returns the next input and output
-- positions.
local function copy_literals(src, ip, src_size, dst, op, capacity, count)
    if count == 15 then count, ip = extended(src, ip, src_size, count) end
    if ip + count > src_size or op + count > capacity then error('lz4: literals overrun', 0) end
    ffi.copy(dst + op, src + ip, count)
    return ip + count, op + count
end

-- Copies one sequence's match (offset, then length from the token's low nibble plus 4). An overlapping match
-- (offset below its length) repeats its first `offset` bytes: a short one is copied byte by byte, a long one in
-- whole periods from its start, each copy as long as all written before it (memcpy calls that never overlap; the
-- result is the byte-by-byte one). The game's data holds such runs of up to a whole 256 KB chunk (370 over 16 KB in
-- 8,518 sampled chunks): byte by byte that is 0.36 ms compiled and 12 ms interpreted in the game's VM, in one piece.
-- Returns the next input and output positions.
local LONG_MATCH = 256
local function copy_match(src, ip, src_size, dst, op, capacity, token)
    if ip + 2 > src_size then error('lz4: truncated offset', 0) end
    local offset = src[ip] + src[ip + 1] * 256
    ip = ip + 2
    if offset == 0 or offset > op then error('lz4: bad offset', 0) end
    local length = band(token, 15)
    if length == 15 then length, ip = extended(src, ip, src_size, length) end
    length = length + 4
    if op + length > capacity then error('lz4: match overrun', 0) end
    local from = op - offset
    if offset >= length then
        ffi.copy(dst + op, dst + from, length)
    elseif length < LONG_MATCH then
        for k = 0, length - 1 do dst[op + k] = dst[from + k] end
    else
        local done = 0 -- a whole number of periods, so dst + from holds what comes next
        while done < length do
            local n = math.min(done + offset, length - done)
            ffi.copy(dst + op + done, dst + from, n)
            done = done + n
        end
    end
    return ip, op + length
end

-- LZ4 block decoder (the block format, no frame). src: uint8_t pointer, src_size bytes; dst: uint8_t
-- pointer with room for capacity bytes; pause (optional): called once at least LZ4_PAUSE bytes of output followed the
-- last call, after a sequence, so a job can pause inside a chunk (a 256 KB chunk is several ms of work in the game;
-- 16 KB about 0.2 ms outside it). A sequence's literals and a long match are memcpy calls (copy_match), so even one
-- that fills a whole chunk adds only copying time between two calls. Returns the decoded size, or raises on malformed
-- input.
local LZ4_PAUSE = 16384
function Slim.lz4(src, src_size, dst, capacity, pause)
    local ip, op = 0, 0
    local next_pause = pause and LZ4_PAUSE or math.huge
    while ip < src_size do
        local token = src[ip]
        ip, op = copy_literals(src, ip + 1, src_size, dst, op, capacity, rshift(token, 4))
        if ip >= src_size then break end
        ip, op = copy_match(src, ip, src_size, dst, op, capacity, token)
        if op >= next_pause then
            pause()
            next_pause = op + LZ4_PAUSE
        end
    end
    return op
end

-- A growable byte buffer: get(size) returns a uint8_t array of at least size bytes, reused between calls.
local function grower(initial)
    local size, data = initial, ffi.new('uint8_t[?]', initial)
    return function(wanted)
        if wanted > size then
            while size < wanted do size = size * 2 end
            data = ffi.new('uint8_t[?]', size)
        end
        return data
    end
end
Slim.grower = grower

-- One DSAR file: its chunk table (uncompressed offset u64, compressed offset u64, uncompressed size u32,
-- compressed size u32, compression u8; 32 bytes each) read once, and read(at, size, out, out_offset) copying
-- bytes of its uncompressed space. files: the file adapter (see Slim.open); scratch: shared buffers.
local function dsar(files, path, scratch)
    local handle = files.open(path)
    local head = scratch.head(32)
    files.read(handle, 0, 32, head)
    if u32(head, 0) ~= 0x52415344 then error('not a DSAR file: ' .. path, 0) end -- 'DSAR'
    local count = u32(head, 8)
    local chunks = ffi.new('uint8_t[?]', count * CHUNK_RECORD)
    files.read(handle, 32, count * CHUNK_RECORD, chunks)
    local self = {count = count, path = path}

    -- The chunk holding uncompressed offset `at` (binary search; chunks are sorted and contiguous).
    local function find(at)
        local lo, hi = 0, count - 1
        while lo <= hi do
            local mid = rshift(lo + hi, 1)
            local start = u64(chunks, mid * CHUNK_RECORD)
            if at < start then
                hi = mid - 1
            elseif at >= start + u32(chunks, mid * CHUNK_RECORD + 16) then
                lo = mid + 1
            else
                return mid
            end
        end
        error(format('offset %.0f outside %s', at, path), 0)
    end

    -- The decoded bytes of chunk k: a pointer into one of the shared chunk slots (every file's), valid until
    -- CHUNK_SLOTS other chunks were decoded. The least recently used slot takes a new chunk; a slot's buffer is
    -- made when first needed.
    -- Reads chunk k (size bytes decoded) into out.
    local function fill(k, out, size)
        local base = k * CHUNK_RECORD
        local packed_at, packed_size, compression = u64(chunks, base + 8), u32(chunks, base + 20), chunks[base + 24]
        if compression == 0 then
            files.read(handle, packed_at, size, out)
        elseif compression == 3 then
            local packed = scratch.packed(packed_size)
            files.read(handle, packed_at, packed_size, packed)
            if Slim.lz4(packed, packed_size, out, size, scratch.yield) ~= size then
                error('lz4: short chunk in ' .. path, 0)
            end
        else
            error(format('compression %d in %s', compression, path), 0)
        end
        scratch.decodes = scratch.decodes + 1
    end

    -- A small chunk, decoded into a buffer of its own and kept (Slim.SMALL_CHUNK); kept only once whole, so a decode
    -- the job abandons at a pause leaves nothing behind.
    local function decoded_small(k, size)
        local out = ffi.new('uint8_t[?]', math.max(1, size))
        fill(k, out, size)
        if scratch.small_bytes + size > Slim.SMALL_BYTES then scratch.small, scratch.small_bytes = {}, 0 end
        local mine = scratch.small[self]
        if not mine then
            mine = {}
            scratch.small[self] = mine
        end
        mine[k], scratch.small_bytes = out, scratch.small_bytes + size
        if scratch.yield then scratch.yield() end -- a job may pause between chunks (the chunk stays kept)
        return out
    end

    local function decoded(k)
        local mine = scratch.small[self]
        local kept = mine and mine[k]
        if kept then return kept end
        local size = u32(chunks, k * CHUNK_RECORD + 16)
        if size <= Slim.SMALL_CHUNK then return decoded_small(k, size) end
        local slots = scratch.slots
        scratch.tick = scratch.tick + 1
        local slot = slots[1]
        for i = 1, #slots do
            local s = slots[i]
            if s.owner == self and s.k == k then
                s.used = scratch.tick
                return s.data
            end
            if s.used < slot.used then slot = s end
        end
        if #slots < CHUNK_SLOTS and slots[1].owner then
            slot = {chunk = grower(262144), used = 0}
            slots[#slots + 1] = slot
        end
        slot.owner = nil -- a decode the job abandons at a pause leaves no slot that looks valid
        local out = slot.chunk(size)
        fill(k, out, size)
        slot.owner, slot.k, slot.data, slot.used = self, k, out, scratch.tick
        if scratch.yield then scratch.yield() end -- a job may pause between chunks (the chunk stays decoded)
        return out
    end

    function self.read(at, size, out, out_offset)
        out_offset = out_offset or 0
        while size > 0 do
            local k = find(at)
            local base = k * CHUNK_RECORD
            local start, length = u64(chunks, base), u32(chunks, base + 16)
            local skip = at - start
            local take = math.min(size, length - skip)
            if chunks[base + 24] == 0 and length > STORED_DIRECT then
                files.read(handle, u64(chunks, base + 8) + skip, take, out + out_offset)
            else
                local data = decoded(k) -- held while copied: a pointer into it keeps nothing alive
                ffi.copy(out + out_offset, data + skip, take)
            end
            at, size, out_offset = at + take, size - take, out_offset + take
        end
    end

    function self.close() files.close(handle) end
    return self
end

-- -1, 0 or 1: the NUL-terminated name at names[at] against the Lua string `name`, bytewise.
local function compare(names, at, limit, name)
    local length = #name
    for i = 1, length + 1 do
        local a = at + i - 1 < limit and names[at + i - 1] or 0
        local b = i <= length and byte(name, i) or 0
        if a ~= b then return a < b and -1 or 1 end
        if a == 0 then return 0 end
    end
    return 0
end

-- The slim data reader. files: {open(path) -> handle, read(handle, offset, size, uint8_t *), close(handle)},
-- raising on failure; data: the game's data folder with a trailing separator; yield (optional): called after
-- each chunk is decoded, so a job can pause there (about 1 ms of work per 256 KB chunk).
function Slim.open(files, data, yield)
    local scratch = {head = grower(128), slots = {{chunk = grower(262144), used = 0}}, packed = grower(262144), decodes = 0,
                     tick = 0, yield = yield, small = {}, small_bytes = 0}
    local index = dsar(files, data .. 'bundles.nxa', scratch)
    local head = scratch.head(24)
    index.read(0, 24, head)
    if u32(head, 0) ~= 0x41415344 then error('bundles.nxa holds no DSAA index', 0) end -- 'DSAA'
    local bundle_count, item_count = u32(head, 12), u32(head, 16)
    local self = {items = item_count, bundles = bundle_count, scratch = scratch}
    -- Item records and the bundle name offsets after them, then the names (item names, then bundle names).
    local records_size = item_count * ITEM_RECORD + bundle_count * 4
    local records = ffi.new('uint8_t[?]', records_size)
    index.read(24, records_size, records)
    local names_at = u32(records, 8)
    local names_end = names_at
    for b = 0, bundle_count - 1 do
        names_end = math.max(names_end, u32(records, item_count * ITEM_RECORD + 4 * b) + 64)
    end
    names_end = math.min(names_end, u64(records, 16))
    local names = ffi.new('uint8_t[?]', names_end - names_at)
    index.read(names_at, names_end - names_at, names)
    local names_size = names_end - names_at

    local function name_at(at)
        local o = at - names_at
        for n = o, names_size - 1 do
            if names[n] == 0 then return ffi.string(names + o, n - o) end
        end
        error('index name runs past the names', 0)
    end

    local bundle_files = {}
    local function bundle(number)
        local found = bundle_files[number]
        if found then return found end
        if number >= bundle_count then error('bundle number out of range', 0) end
        found = dsar(files, data .. name_at(u32(records, item_count * ITEM_RECORD + 4 * number)), scratch)
        bundle_files[number] = found
        return found
    end

    -- The item number of `name` (binary search over the sorted records), or nil.
    function self.item(name)
        local lo, hi = 0, item_count - 1
        while lo <= hi do
            local mid = rshift(lo + hi, 1)
            local order = compare(names, u32(records, mid * ITEM_RECORD + 8) - names_at, names_size, name)
            if order == 0 then return mid end
            if order < 0 then lo = mid + 1 else hi = mid - 1 end
        end
        return nil
    end

    -- Entry tables of recently read items (item number -> uint8_t array), at most ENTRY_CACHE.
    local entry_tables, entry_order = {}, {}
    local function entries_of(k)
        local found = entry_tables[k]
        if found then return found end
        local base = k * ITEM_RECORD
        local count = u32(records, base + 12)
        found = ffi.new('uint8_t[?]', math.max(1, count * ENTRY_RECORD))
        index.read(u64(records, base + 16), count * ENTRY_RECORD, found)
        if #entry_order >= ENTRY_CACHE then entry_tables[table.remove(entry_order, 1)] = nil end
        entry_tables[k] = found
        entry_order[#entry_order + 1] = k
        return found
    end

    -- The last entry whose item offset is at or below `at` (binary search).
    local function entry_for(table_bytes, count, at)
        local lo, hi, best = 0, count - 1, 0
        while lo <= hi do
            local mid = rshift(lo + hi, 1)
            if u32(table_bytes, mid * ENTRY_RECORD) <= at then best, lo = mid, mid + 1 else hi = mid - 1 end
        end
        return best
    end

    -- Copies bytes [at, at + size) of item `name`'s virtual file into out (uint8_t *) at out_offset.
    function self.read(name, at, size, out, out_offset)
        local k = self.item(name)
        if not k then error('archive item missing: ' .. name, 0) end
        local base = k * ITEM_RECORD
        local total, count = u64(records, base), u32(records, base + 12)
        if at < 0 or at + size > total then error('read outside archive item ' .. name, 0) end
        local table_bytes = entries_of(k)
        out_offset = out_offset or 0
        local e = entry_for(table_bytes, count, at)
        while size > 0 do
            if e >= count then error('archive item entries end early: ' .. name, 0) end
            local o = e * ENTRY_RECORD
            local start, bundle_at, number = u32(table_bytes, o), u32(table_bytes, o + 8), table_bytes[o + 15]
            local stop = e + 1 < count and u32(table_bytes, (e + 1) * ENTRY_RECORD) or total
            local take = math.min(size, stop - at)
            bundle(number).read(bundle_at + (at - start), take, out, out_offset)
            at, size, out_offset, e = at + take, size - take, out_offset + take, e + 1
        end
    end

    -- An archive's table of contents, kept raw: {raw, base, count, heads = {[name low half] = first entry},
    -- nexts (the next entry with the same low half, -1 at the end)}, or nil when the archive is not in the index.
    -- Building it touches each entry once and makes no strings (the shared archive lists 4,241 files), with a
    -- pause point every 512 entries.
    local tocs, found_records = {}, {}
    local function toc(archive)
        local found = tocs[archive]
        if found ~= nil then return found or nil end
        if not self.item(archive) then
            tocs[archive] = false
            return nil
        end
        local head72 = scratch.head(TOC_HEADER)
        self.read(archive, 0, TOC_HEADER, head72)
        if u32(head72, 0) ~= Slim.TOC_MAGIC then error('bad archive header: ' .. archive, 0) end
        local types, count = u32(head72, 4), u32(head72, 8)
        local base = TOC_HEADER + TOC_TYPE * types
        local raw = ffi.new('uint8_t[?]', base + TOC_FILE * count)
        self.read(archive, 0, base + TOC_FILE * count, raw)
        local heads, nexts = {}, ffi.new('int32_t[?]', math.max(1, count))
        for i = count - 1, 0, -1 do -- backwards, so each chain lists entries in file order
            local low = u32(raw, base + TOC_FILE * i)
            nexts[i] = heads[low] or -1
            heads[low] = i
            if i % 512 == 0 and scratch.yield then scratch.yield() end
        end
        found = {raw = raw, base = base, count = count, heads = heads, nexts = nexts}
        tocs[archive] = found
        return found
    end
    self.toc = toc

    -- A resource's TOC record {main_at, main_size, stream_at, stream_size, gpu_at, gpu_size} in one archive
    -- (file entry: name u64, type u64, part offsets u64 at +16/+24/+32, part sizes u32 at +56/+60/+64), or nil.
    -- name_hex, type_hex: 16 hex digits. Records found are kept.
    function self.locate(archive, name_hex, type_hex)
        local t = toc(archive)
        if not t then return nil end
        local key = archive .. name_hex .. type_hex
        local record = found_records[key]
        if record ~= nil then return record or nil end
        local name_high, name_low = tonumber(name_hex:sub(1, 8), 16), tonumber(name_hex:sub(9, 16), 16)
        local type_high, type_low = tonumber(type_hex:sub(1, 8), 16), tonumber(type_hex:sub(9, 16), 16)
        local raw, i = t.raw, t.heads[name_low]
        while i and i >= 0 do
            local o = t.base + TOC_FILE * i
            if u32(raw, o + 4) == name_high and u32(raw, o + 8) == type_low and u32(raw, o + 12) == type_high then
                record = {u64(raw, o + 16), u32(raw, o + 56), u64(raw, o + 24), u32(raw, o + 60),
                          u64(raw, o + 32), u32(raw, o + 64)}
                break
            end
            i = t.nexts[i]
        end
        found_records[key] = record or false
        return record
    end

    local PARTS = {main = {1, ''}, stream = {3, '.stream'}, gpu = {5, '.gpu_resources'}}
    -- The size of a resource part ('main', 'stream' or 'gpu'); record from locate().
    function self.part_size(record, part)
        return record[PARTS[part][1] + 1]
    end

    -- Copies bytes [at, at + size) of a resource part into out at out_offset; raises when the part is shorter.
    function self.part(archive, record, part, at, size, out, out_offset)
        local p = PARTS[part]
        if at < 0 or at + size > record[p[1] + 1] then error('read outside a resource part', 0) end
        self.read(archive .. p[2], record[p[1]] + at, size, out, out_offset)
    end

    function self.close()
        index.close()
        for _, found in pairs(bundle_files) do found.close() end
    end
    return self
end

-- Code that runs once or rarely (jobs, startup, events) stays interpreted, sub-functions included: it must not
-- add traces to the LuaJIT code cache the game and every mod share. Only the hot loops stay compiled.
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({Slim.hex, grower, dsar, compare, Slim.open}) do
        jit.off(fn, true)
    end
end

return Slim
end)()
local Patches = (function()
-- Match Your Colors: mods' loose patch files, read with the priority the game gives them, over the slim data
-- (src/slim.lua).
--
-- Mod managers install every mod as patches of the boot archive 9ba626afa44a3aa3: data/9ba626afa44a3aa3.patch_0,
-- _1, ..., each a classic archive file (at offset 0 the table of contents src/slim.lua reads from an archive item:
-- 72-byte header, 32-byte type entries, 80-byte file entries) with its stream and GPU parts in .stream and
-- .gpu_resources files beside it. The game loads that archive's patches at boot, before any helmet, armor or cape
-- archive, so a texture, material or unit a patch holds replaces the archived one of the same name and type for the
-- whole session, and between patches the higher number wins (KB arsenal-hd2mm-deploy-internals; Bingus Shared
-- Loader ranks them the same way). Patches of another archive (<archive>.patch_N) count when that archive is
-- searched. Up to v1.3 the mod read only the archived resources and replaced modded helmets' and armors' LUTs with
-- recolored vanilla ones (user report 2026-10-06, KB match-your-colors-modded-luts).
--
-- Patches.index runs once per session inside the first recolor job (never per frame): the data folder's patch files
-- are listed, their tables of contents read (two reads a patch), and the entries of the resource types the mod reads
-- indexed. Its signature is a checksum of every indexed entry (name, type, part offsets and sizes), so the analysis
-- cache is discarded when the installed mods change what they hold. Two variants of one mod can hold the same entries
-- and differ only in their bytes (managers zero the files' dates; a black and a blue visor: same name, same sizes), so
-- each analysis also carries a content hash of every byte range it read from patched resources (Patches.content_hash,
-- src/recolor.lua): a cached analysis is checked against the patches when first used and made again when one differs.
-- Until v1.3 the signature also read the bytes of every indexed part up to 64 KB (2,121 entries, about 4,000 reads, in
-- a user's first job with 176 patch files) and each analysis hashed the whole of every patched resource it touched
-- (a mod's meshes and 4K masks: 2.6 GB read in one Armory session, user report 2026-10-08). Patches.over(slim, index,
-- files) is the job's reader: slim's locate, part and part_size, with patch resources first, noting what it reads of
-- them (ranges); Patches.record looks a resource up in the patches alone.
local ffi = require('ffi')

local Patches = {}

Patches.BOOT = '9ba626afa44a3aa3'
Patches.MAX_ENTRIES = 262144 -- a table of contents above this is not indexed (no mod comes near)
local TOC_HEADER, TOC_TYPE, TOC_FILE, TOC_MAGIC = 72, 32, 80, 0xF0000011
local PARTS = {main = {1, ''}, stream = {3, '.stream'}, gpu = {5, '.gpu_resources'}}
local PART_ORDER = {'main', 'stream', 'gpu'}
local UNINDEXED = -2 -- an entry of another type (chains end with -1)

local function u32(p, o) return p[o] + p[o + 1] * 256 + p[o + 2] * 65536 + p[o + 3] * 16777216 end
local function u64(p, o) return u32(p, o) + u32(p, o + 4) * 4294967296 end

-- The patch files among names, in priority order: the boot archive's first, then every other archive's (by
-- name); within an archive the highest number first. {{file, archive, number}, ...}.
function Patches.order(names)
    local out = {}
    for _, name in ipairs(names) do
        local archive, number = name:match('^(%x+)%.patch_(%d+)$')
        if archive and #archive == 16 and #number <= 6 then
            out[#out + 1] = {file = name, archive = archive:lower(), number = tonumber(number)}
        end
    end
    table.sort(out, function(a, b)
        if a.archive ~= b.archive then
            if a.archive == Patches.BOOT or b.archive == Patches.BOOT then return a.archive == Patches.BOOT end
            return a.archive < b.archive
        end
        return a.number > b.number
    end)
    return out
end

-- Adler-32 over p[0 .. size - 1] from (a, b), reduced every 4,096 bytes (the sums stay exact): the hot loop of the
-- index's signature and of a content hash, left to compile (about 1 ms per MB outside the game). Until v1.3 the
-- signature summed bytes in an interpreted loop with two modulo steps per byte: about 3.2 ms per 64 KB part in the
-- game's VM, in one piece.
local function adler(p, size, a, b)
    local i = 0
    while i < size do
        local stop = math.min(i + 4096, size)
        for k = i, stop - 1 do
            a = a + p[k]
            b = b + a
        end
        a, b = a % 65521, b % 65521
        i = stop
    end
    return a, b
end

-- A running Adler-32 over byte arrays (adler) and strings.
local function checksum()
    local a, b = 1, 0
    local self = {}
    function self.bytes(p, size) a, b = adler(p, size, a, b) end
    function self.text(s)
        for i = 1, #s do
            a = (a + s:byte(i)) % 65521
            b = (b + a) % 65521
        end
    end
    function self.value() return b * 65536 + a end
    return self
end

-- One patch file's table of contents with its entries of the wanted types ({['low:high'] = true}) chained by
-- their name's low half (as src/slim.lua's archive tables); nil when it holds none of them.
local function read_toc(files, patch, wanted, scratch, yield)
    local handle = files.open(patch.file)
    local ok, toc = pcall(function()
        local head = scratch(TOC_HEADER)
        files.read(handle, 0, TOC_HEADER, head)
        if u32(head, 0) ~= TOC_MAGIC then error('bad patch header: ' .. patch.file, 0) end
        local type_count, count = u32(head, 4), u32(head, 8)
        if count == 0 or count > Patches.MAX_ENTRIES or type_count > 4096 then return nil end
        local base = TOC_HEADER + TOC_TYPE * type_count
        local raw = ffi.new('uint8_t[?]', base + TOC_FILE * count)
        files.read(handle, 0, base + TOC_FILE * count, raw)
        local heads, nexts, indexed = {}, ffi.new('int32_t[?]', count), 0
        for i = count - 1, 0, -1 do -- backwards, so each chain lists entries in file order
            local o = base + TOC_FILE * i
            nexts[i] = UNINDEXED
            if wanted[u32(raw, o + 8) .. ':' .. u32(raw, o + 12)] then
                local low = u32(raw, o)
                nexts[i] = heads[low] or -1
                heads[low] = i
                indexed = indexed + 1
            end
            if i % 512 == 0 then yield() end
        end
        if indexed == 0 then return nil end
        return {raw = raw, base = base, count = count, heads = heads, nexts = nexts, indexed = indexed}
    end)
    files.close(handle)
    if not ok then error(toc, 0) end
    return toc
end

-- Adds an indexed patch's entries to sum: its file name and each entry's 80 bytes (name, type, part offsets and
-- sizes), in file order, with a pause point every 64 entries (an entry is a few microseconds, interpreted).
local function sum_entries(patch, sum, yield)
    local t = patch.toc
    for i = 0, t.count - 1 do
        if t.nexts[i] ~= UNINDEXED then
            sum.text(patch.file)
            sum.bytes(t.raw + (t.base + TOC_FILE * i), TOC_FILE)
        end
        if i % 64 == 63 then yield() end
    end
end

-- The session's patch index. files: a file adapter (src/files.lua: open, read, close, list) on the folder holding
-- the patches; types: {type hex, ...} of the resources the mod reads; scratch: a grower (src/slim.lua); yield: the
-- job's pause. {patches (priority order, each {file, archive, number, toc}), signature, entries, skipped}. A patch
-- that cannot be read is left out and counted in skipped.
function Patches.index(files, types, scratch, yield)
    local wanted = {}
    for _, hex in ipairs(types) do
        wanted[tonumber(hex:sub(9, 16), 16) .. ':' .. tonumber(hex:sub(1, 8), 16)] = true
    end
    local sum = checksum()
    local out = {patches = {}, entries = 0, skipped = 0}
    for _, patch in ipairs(Patches.order(files.list('*.patch_*'))) do
        local ok, toc = pcall(read_toc, files, patch, wanted, scratch, yield)
        if ok and toc then
            patch.toc = toc
            sum_entries(patch, sum, yield)
            out.patches[#out.patches + 1] = patch
            out.entries = out.entries + toc.indexed
        end
        if not ok then out.skipped = out.skipped + 1 end
    end
    out.signature = string.format('%d:%d:%d:%08x', #out.patches, out.entries, out.skipped, sum.value())
    return out
end

-- The record of name and type in one patch ({main at, main size, stream at, stream size, GPU at, GPU size, file =
-- the patch file}), or nil.
local function record_in(patch, name_high, name_low, type_high, type_low)
    local t = patch.toc
    local raw, i = t.raw, t.heads[name_low]
    while i and i >= 0 do
        local o = t.base + TOC_FILE * i
        if u32(raw, o + 4) == name_high and u32(raw, o + 8) == type_low and u32(raw, o + 12) == type_high then
            return {u64(raw, o + 16), u32(raw, o + 56), u64(raw, o + 24), u32(raw, o + 60), u64(raw, o + 32),
                    u32(raw, o + 64), file = patch.file}
        end
        i = t.nexts[i]
    end
    return nil
end

-- The record the patches give for name and type when `archive` is searched (the boot archive's patches, then the
-- archive's own), or nil (the archive's own resource then counts).
function Patches.record(index, archive, name_hex, type_hex)
    local name_high, name_low = tonumber(name_hex:sub(1, 8), 16), tonumber(name_hex:sub(9, 16), 16)
    local type_high, type_low = tonumber(type_hex:sub(1, 8), 16), tonumber(type_hex:sub(9, 16), 16)
    for _, patch in ipairs(index.patches) do
        if patch.archive == Patches.BOOT or patch.archive == archive then
            local record = record_in(patch, name_high, name_low, type_high, type_low)
            if record then return record end
        end
    end
    return nil
end

Patches.CHUNK = 262144 -- bytes a content hash reads at a time (v1.3: 64 KB, four times the reads)

-- Byte ranges read of one patched resource: {main = {from, to, from, to, ...}, stream = ..., gpu = ...} (offsets in
-- the part, half-open), as Patches.over notes them; merged: sorted, overlapping and adjacent ones joined.
local function merged(list)
    local pairs_ = {}
    for i = 1, #list, 2 do pairs_[#pairs_ + 1] = {list[i], list[i + 1]} end
    table.sort(pairs_, function(x, y) return x[1] < y[1] end)
    local out = {}
    for _, r in ipairs(pairs_) do
        if out[#out] and r[1] <= out[#out] then
            out[#out] = math.max(out[#out], r[2])
        else
            out[#out + 1], out[#out + 2] = r[1], r[2]
        end
    end
    return out
end

-- Ranges as text (the disk cache keeps them): 'main:0+116,4096+200|gpu:0+1472' (offset + length per range, parts in
-- order), '-' for none; and back (nil when malformed).
function Patches.ranges_text(ranges)
    local parts = {}
    for _, part in ipairs(PART_ORDER) do
        local list = ranges and ranges[part] and merged(ranges[part]) or {}
        if #list > 0 then
            local items = {}
            for i = 1, #list, 2 do items[#items + 1] = string.format('%.0f+%.0f', list[i], list[i + 1] - list[i]) end
            parts[#parts + 1] = part .. ':' .. table.concat(items, ',')
        end
    end
    return #parts > 0 and table.concat(parts, '|') or '-'
end
function Patches.parse_ranges(text)
    if text == '-' then return {} end
    local out = {}
    for piece in text:gmatch('[^|]+') do
        local part, items = piece:match('^(%a+):(.+)$')
        if not part or not PARTS[part] or out[part] then return nil end
        local list = {}
        for from, length in items:gmatch('(%d+)%+(%d+)') do
            list[#list + 1], list[#list + 2] = tonumber(from), tonumber(from) + tonumber(length)
        end
        if #list == 0 then return nil end
        out[part] = list
    end
    return out
end

-- A patch record's content hash over the byte ranges an analysis read of it (Patches.over's ranges; none: only its
-- presence counted), 'bytes:adler32' over the ranges, parts in order and ranges in offset order, read in CHUNK pieces
-- from the patch's files with yield() after each. files: the adapter on the patch folder; scratch: a grower
-- (src/slim.lua). v1.3 hashed every byte of the resource: the whole mesh of a mod's unit, every mip of its masks.
function Patches.content_hash(files, record, scratch, yield, ranges)
    local a, b, total = 1, 0, 0
    for _, part in ipairs(PART_ORDER) do
        local list = ranges and ranges[part] and merged(ranges[part]) or {}
        local p = PARTS[part]
        if #list > 0 then
            if list[#list] > record[p[1] + 1] then error('content range outside ' .. record.file .. ' ' .. part, 0) end
            local handle = files.open(record.file .. p[2])
            local ok, why = pcall(function()
                for i = 1, #list, 2 do
                    for done = list[i], list[i + 1] - 1, Patches.CHUNK do
                        local n = math.min(Patches.CHUNK, list[i + 1] - done)
                        local buffer = scratch(n)
                        files.read(handle, record[p[1]] + done, n, buffer)
                        a, b = adler(buffer, n, a, b)
                        total = total + n
                        if yield then yield() end
                    end
                end
            end)
            files.close(handle)
            if not ok then error(why, 0) end
        end
    end
    return string.format('%d:%08x', total, b * 65536 + a)
end

-- The job's reader: slim (src/slim.lua's reader) with the patches of index first; files: the adapter on the folder
-- holding them. locate(archive, name, type) -> a record (a patch's carries its file), part_size, part, close; base:
-- slim itself (the archived resources, for comparing a patched LUT with its original); slim's other fields as they are.
-- ranges: while the caller sets it to a table, every read of a patched resource is noted there ({[record] = ranges},
-- Patches.content_hash's).
function Patches.over(slim, index, files)
    local handles, found = {}, {}
    local self = {base = slim}
    for k, v in pairs(slim) do self[k] = v end

    -- The boot archive's patches, then the searched archive's, then the archive itself.
    function self.locate(archive, name_hex, type_hex)
        local key = archive .. name_hex .. type_hex
        local record = found[key]
        if record ~= nil then return record or nil end
        record = Patches.record(index, archive, name_hex, type_hex) or slim.locate(archive, name_hex, type_hex)
        found[key] = record or false
        return record
    end

    function self.part(archive, record, part, at, size, out, out_offset)
        if not record.file then return slim.part(archive, record, part, at, size, out, out_offset) end
        local p = PARTS[part]
        if at < 0 or at + size > record[p[1] + 1] then error('read outside a resource part', 0) end
        local name = record.file .. p[2]
        handles[name] = handles[name] or files.open(name)
        files.read(handles[name], record[p[1]] + at, size, out + (out_offset or 0))
        local ranges = self.ranges
        if ranges and size > 0 then
            local r = ranges[record] or {}
            ranges[record] = r
            local list = r[part] or {}
            r[part] = list
            list[#list + 1], list[#list + 2] = at, at + size
        end
    end

    function self.close()
        for name, handle in pairs(handles) do
            files.close(handle)
            handles[name] = nil
        end
        slim.close()
    end
    return self
end

-- Runs inside recolor jobs only: interpreted (no traces in the LuaJIT code cache every mod shares).
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({u32, u64, Patches.order, checksum, read_toc, sum_entries, Patches.index, record_in,
                         Patches.record, merged, Patches.ranges_text, Patches.parse_ranges, Patches.content_hash,
                         Patches.over}) do
        jit.off(fn, true)
    end
end

return Patches
end)()
local Texture = (function()
-- Match Your Colors: the texture data the color model needs, decoded from the game's own files.
--
-- A texture resource's main part holds a 0xC0-byte resource header and the DDS header (DX10, 148 bytes);
-- its pixels are in the GPU part, or in the stream part when that one holds the whole mip chain (9 of the
-- 570 ID masks of build 25480438), else in the two parts end to end. Layers are stored one after another,
-- each with its full mip chain (DDS order).
--
-- Decoded here: material LUTs (23 x N, R16G16B16A16_FLOAT, mip 0; mods' may be R32G32B32A32_FLOAT) and pattern
-- textures (3 x 1, the same formats), ID-mask coverage (R8G8B8A8, 1-2 layers = 4-8 soft slot weights, mip 0),
-- pattern-mask coverage (R8 or R8G8B8A8, red channel, one layer and mip, research/patterns.py), the first 512 texels
-- of the detail tiler's mip 4 per layer (BC7) and of the camo tiler's mip 2 per layer (R8G8B8A8), as
-- research/effective.py samples them. Nothing here runs per frame.
local ffi = require('ffi')
local bit = require('bit')
local band, bor, lshift, rshift = bit.band, bit.bor, bit.lshift, bit.rshift

local Texture = {}

local HEADER = 0xC0
local DDS_HEADER, DX10_HEADER = 128, 20
local u32 = function(p, o) return p[o] + p[o + 1] * 256 + p[o + 2] * 65536 + p[o + 3] * 16777216 end
Texture.FORMAT_RGBA16F, Texture.FORMAT_RGBA8, Texture.FORMAT_RGBA8_SRGB, Texture.FORMAT_BC7 = 10, 28, 29, 98
Texture.FORMAT_R8 = 61
Texture.FORMAT_BC3 = 77 -- capes' scalar fields (src/capes.lua decodes its blocks)
Texture.FORMAT_BC4 = 80 -- capes' gradients (src/capes.lua)
-- Mods' albedos of gear without a color table (src/albedo.lua, v1.5): BC1 (UNORM, sRGB) and BC3 sRGB.
Texture.FORMAT_BC1, Texture.FORMAT_BC1_SRGB, Texture.FORMAT_BC3_SRGB = 71, 72, 78
local BLOCK_BYTES = {[Texture.FORMAT_BC7] = 16, [Texture.FORMAT_BC3] = 16, [Texture.FORMAT_BC4] = 8,
                     [Texture.FORMAT_BC1] = 8, [Texture.FORMAT_BC1_SRGB] = 8, [Texture.FORMAT_BC3_SRGB] = 16}
-- Mods' LUTs: every texture the game ships the mod reads is in the formats above (the 11 paint schemes' LUTs too), but
-- some mods write LUTs as R32G32B32A32_FLOAT; v1.3 rejected them ("unsupported texture format 2", user report
-- 2026-10-08: every paint scheme a mod had replaced failed).
Texture.FORMAT_RGBA32F = 2
local TEXEL_BYTES = {[Texture.FORMAT_RGBA32F] = 16, [Texture.FORMAT_RGBA16F] = 8, [Texture.FORMAT_R8] = 1}

-- Bytes of mip `m` of a w x h layer in `format`.
local function mip_bytes(format, w, h, m)
    local mw, mh = math.max(1, rshift(w, m)), math.max(1, rshift(h, m))
    local block = BLOCK_BYTES[format]
    if block then return math.max(1, rshift(mw + 3, 2)) * math.max(1, rshift(mh + 3, 2)) * block end
    return mw * mh * (TEXEL_BYTES[format] or 4)
end

-- The DDS description in a texture's main part (uint8_t pointer, size): {width, height, mips, format, layers,
-- layer_bytes, mip_offsets (0-based mip -> offset in a layer)}; raises when it is not a DX10 DDS this file
-- decodes.
function Texture.describe(main, size)
    if size < HEADER + DDS_HEADER + DX10_HEADER or u32(main, HEADER) ~= 0x20534444 then -- 'DDS '
        error('texture main part holds no DDS header', 0)
    end
    local d = HEADER
    local info = {height = u32(main, d + 12), width = u32(main, d + 16), mips = math.max(1, u32(main, d + 28))}
    if u32(main, d + 84) ~= 0x30315844 then error('texture is not DX10', 0) end -- 'DX10'
    info.format, info.layers = u32(main, d + 128), math.max(1, u32(main, d + 140))
    local f = info.format
    if f ~= Texture.FORMAT_RGBA16F and f ~= Texture.FORMAT_RGBA8 and f ~= Texture.FORMAT_RGBA8_SRGB
        and f ~= Texture.FORMAT_R8 and f ~= Texture.FORMAT_RGBA32F and not BLOCK_BYTES[f] then
        error('unsupported texture format ' .. f, 0)
    end
    info.mip_offsets, info.layer_bytes = {}, 0
    for m = 0, info.mips - 1 do
        info.mip_offsets[m] = info.layer_bytes
        info.layer_bytes = info.layer_bytes + mip_bytes(f, info.width, info.height, m)
    end
    info.total = info.layer_bytes * info.layers
    return info
end

-- A reader of a texture's pixel bytes: read(at, size, out, out_offset) over the DDS pixel data (offset 0 =
-- layer 0 mip 0). slim: the reader (src/slim.lua); record: the resource's TOC record; info: describe().
function Texture.pixels(slim, archive, record, info)
    local stream, gpu = slim.part_size(record, 'stream'), slim.part_size(record, 'gpu')
    if gpu >= info.total then
        return function(at, size, out, out_offset) slim.part(archive, record, 'gpu', at, size, out, out_offset) end
    end
    if stream >= info.total then
        return function(at, size, out, out_offset) slim.part(archive, record, 'stream', at, size, out, out_offset) end
    end
    if stream + gpu < info.total then error('texture data shorter than its mip chain', 0) end
    return function(at, size, out, out_offset)
        out_offset = out_offset or 0
        if at < stream then
            local take = math.min(size, stream - at)
            slim.part(archive, record, 'stream', at, take, out, out_offset)
            at, size, out_offset = at + take, size - take, out_offset + take
        end
        if size > 0 then slim.part(archive, record, 'gpu', at - stream, size, out, out_offset) end
    end
end

-- IEEE half to number.
local function half(lo, hi)
    local h = lo + hi * 256
    local sign = h >= 32768 and -1 or 1
    local exponent = band(rshift(h, 10), 31)
    local mantissa = band(h, 1023)
    if exponent == 0 then return sign * mantissa * 2 ^ -24 end
    if exponent == 31 then return mantissa == 0 and sign * math.huge or 0 / 0 end
    return sign * (1 + mantissa / 1024) * 2 ^ (exponent - 15)
end
Texture.half = half

-- IEEE single to number, from its four little-endian bytes at p[o] (exact). Decoded from the bytes, never loaded
-- through a float pointer: a NaN with a payload loaded that way can come out as no number at all in this LuaJIT
-- (its values are NaN-tagged); every NaN here is 0 / 0.
local function single(p, o)
    local b2, b3 = p[o + 2], p[o + 3]
    local sign = b3 >= 128 and -1 or 1
    local exponent = band(b3, 127) * 2 + rshift(b2, 7)
    local mantissa = band(b2, 127) * 65536 + p[o + 1] * 256 + p[o]
    if exponent == 0 then return sign * math.ldexp(mantissa, -149) end
    if exponent == 255 then return mantissa == 0 and sign * math.huge or 0 / 0 end
    return sign * math.ldexp(8388608 + mantissa, exponent - 150)
end
Texture.single = single

-- The 23 x N material LUT (mip 0) as a float array: value(row, column, channel) at ((row * width + column) *
-- 4 + channel), from R16G16B16A16_FLOAT (the game's) or R32G32B32A32_FLOAT (some mods'). Returns the array, width
-- and rows.
function Texture.lut(pixels, info, scratch)
    local count = info.width * info.height * 4
    local values = ffi.new('float[?]', count)
    if info.format == Texture.FORMAT_RGBA16F then
        local raw = scratch(count * 2)
        pixels(0, count * 2, raw, 0)
        for i = 0, count - 1 do values[i] = half(raw[2 * i], raw[2 * i + 1]) end
    elseif info.format == Texture.FORMAT_RGBA32F then
        local raw = scratch(count * 4)
        pixels(0, count * 4, raw, 0)
        for i = 0, count - 1 do values[i] = single(raw, 4 * i) end
    else
        error('material LUT format ' .. info.format .. ' (neither RGBA16F nor RGBA32F)', 0)
    end
    return values, info.width, info.height
end

-- Adds the normalized weights of texels [first, first + count) of mip 0 (all layers, `plane` bytes apart in
-- data) to sums (double array); returns how many texels counted (weight sum above 0.05).
local function accumulate(data, plane, layers, first, count, sums, weights)
    local channels, valid = 4 * layers, 0
    for t = first, first + count - 1 do
        local total = 0
        for k = 0, channels - 1 do
            local v = data[(k - k % 4) / 4 * plane + t * 4 + k % 4] / 255
            weights[k] = v
            total = total + v
        end
        if total > 0.05 then
            valid = valid + 1
            for k = 0, channels - 1 do sums[k] = sums[k] + weights[k] / total end
        end
    end
    return valid
end

-- ID-mask coverage: per slot (4 per layer) the mean of each texel's weight divided by the texel's weight sum, over
-- texels whose sum exceeds 0.05 (research/palettes.py), at mip 0, or for a mask larger than the game's at the first
-- mip no larger than COVERAGE_SIZE on either side: the game's 180 ID masks are at most 512 x 512, and a mod's 4096 x
-- 4096 two-layer mask is 128 MB to read at mip 0 (a user's Armory session read 2.6 GB, 2026-10-08; its mips average
-- the same weights). Returns a 1-based Lua array, or nil and why. The mask is read in blocks of rows (every layer's
-- rows, at most COVERAGE_BLOCK bytes: no buffer the size of the mask, 2 MB for a 512 x 512 two-layer mask); texels are
-- summed in the same order as a whole read. yield() is called between rows so a job can pause.
local COVERAGE_BLOCK = 131072
Texture.COVERAGE_BLOCK = COVERAGE_BLOCK
Texture.COVERAGE_SIZE = 512
function Texture.coverage(pixels, info, scratch, yield)
    if info.format ~= Texture.FORMAT_RGBA8 and info.format ~= Texture.FORMAT_RGBA8_SRGB then
        return nil, 'id mask format ' .. info.format
    end
    local m = 0
    while m + 1 < info.mips and (rshift(info.width, m) > Texture.COVERAGE_SIZE
        or rshift(info.height, m) > Texture.COVERAGE_SIZE) do
        m = m + 1
    end
    local w, h, layers = math.max(1, rshift(info.width, m)), math.max(1, rshift(info.height, m)), info.layers
    local base = info.mip_offsets[m]
    local row_bytes = w * 4
    local rows_per_block = math.max(1, math.floor(COVERAGE_BLOCK / (row_bytes * layers)))
    local data = scratch(rows_per_block * row_bytes * layers)
    local channels = 4 * layers
    local sums, weights = ffi.new('double[?]', channels), ffi.new('double[?]', channels)
    local valid = 0
    for first = 0, h - 1, rows_per_block do
        local rows = math.min(rows_per_block, h - first)
        local plane = rows * row_bytes
        for l = 0, layers - 1 do pixels(l * info.layer_bytes + base + first * row_bytes, plane, data, l * plane) end
        for y = 0, rows - 1 do
            valid = valid + accumulate(data, plane, layers, y * w, w, sums, weights)
            if yield then yield() end
        end
    end
    local out = {}
    for k = 1, channels do out[k] = sums[k - 1] / math.max(1, valid) end
    return out
end

-- A pattern mask's coverage: the mean of the shader's mask strength clamp(100 x (red - 0.5), 0, 1) over mip `mip`
-- (the last when the texture has fewer) of layer `layer` (modulo the layers), summed in texel order; nil when the
-- mask is neither R8 nor R8G8B8A8. The mip is read and summed in blocks of whole rows of at most MASK_BLOCK texels with
-- yield() (optional) after each, the sum in the same order: the game's masks are 256 x 256 with mips (mip 2: 4,096
-- texels, one block), but a mod's mask without mips was read and summed whole (2048 x 2048: 143 ms in one piece in the
-- game's VM; a block of 16,384 texels about 0.6 ms).
Texture.MASK_BLOCK = 16384
function Texture.mask_coverage(pixels, info, layer, mip, scratch, yield)
    local f = info.format
    local per = f == Texture.FORMAT_R8 and 1
        or ((f == Texture.FORMAT_RGBA8 or f == Texture.FORMAT_RGBA8_SRGB) and 4 or nil)
    if not per then return nil end
    mip = math.min(mip, info.mips - 1)
    local w, h = math.max(1, rshift(info.width, mip)), math.max(1, rshift(info.height, mip))
    local rows = math.max(1, math.floor(Texture.MASK_BLOCK / w))
    local data = scratch(math.min(rows, h) * w * per)
    local base = (layer % info.layers) * info.layer_bytes + info.mip_offsets[mip]
    local sum = 0
    for first = 0, h - 1, rows do
        local count = math.min(rows, h - first) * w
        pixels(base + first * w * per, count * per, data, 0)
        for i = 0, count - 1 do
            local v = 100 * (data[i * per] / 255 - 0.5)
            if v > 1 then v = 1 elseif v < 0 then v = 0 end
            sum = sum + v
        end
        if yield then yield() end
    end
    return sum / (w * h)
end

