local ANCHOR3_2 = {
    15, 8, 8, 3, 15, 15, 3, 8, 15, 15, 15, 15, 15, 15, 15, 8, 15, 8, 15, 3, 15, 8, 15, 8, 3, 15, 6, 10, 15, 15, 10, 8,
    15, 3, 15, 10, 10, 8, 9, 10, 6, 15, 8, 15, 3, 6, 6, 8, 15, 3, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 3, 15, 15, 8,
}
local WEIGHTS = {
    [2] = {0, 21, 43, 64},
    [3] = {0, 9, 18, 27, 37, 46, 55, 64},
    [4] = {0, 4, 9, 13, 17, 21, 26, 30, 34, 38, 43, 47, 51, 55, 60, 64},
}

-- The block being decoded (its 16 bytes from bits_block[bits_offset]) and the next bit, read LSB first. The decoder
-- keeps its state here and in the tables below, refilled per block: it allocates nothing per block (a cape's fields
-- are up to 1,024 blocks, decoded inside a recolor job).
local bits_block, bits_offset, bits_position = nil, 0, 0
-- count is at most 8, so the bits lie in two bytes; the second is read only when they reach it (never past the
-- block's 16 bytes: a block's fields end at bit 128).
local function read_bits(count)
    local p = bits_position
    local at, shift = bits_offset + rshift(p, 3), band(p, 7)
    local value = bits_block[at]
    if shift + count > 8 then value = value + bits_block[at + 1] * 256 end
    bits_position = p + count
    return band(rshift(value, shift), lshift(1, count) - 1)
end
-- Endpoints [channel][endpoint], p-bits, the primary and secondary index lists and the parsed block.
local ENDPOINTS, PBITS, PRIMARY, SECONDARY, BLOCK = {{}, {}, {}, {}}, {}, {}, {}, {}

-- The subset of texel t (0-based) and whether it is its subset's anchor.
local function subset_of(subsets, partition, t)
    if subsets == 1 then return 0, t == 0 end
    local row = subsets == 2 and PARTITIONS2[partition + 1] or PARTITIONS3[partition + 1]
    local s = row:byte(t + 1) - 48
    if s == 0 then return 0, t == 0 end
    if subsets == 2 then return 1, ANCHOR2[partition + 1] == t end
    return s, (s == 1 and ANCHOR3_1 or ANCHOR3_2)[partition + 1] == t
end

-- An endpoint component of `bits` bits (p-bit included) widened to 8 bits.
local function widen(value, bits)
    value = lshift(value, 8 - bits)
    return bor(value, rshift(value, bits))
end

-- Raw endpoint values into ENDPOINTS: e[channel][endpoint] (channels 1-4 = R, G, B, A; endpoints 1..count); alpha
-- 255 when the mode has none.
local function raw_endpoints(count, color_bits, alpha_bits)
    local e = ENDPOINTS
    for c = 1, 3 do
        local channel = e[c]
        for i = 1, count do channel[i] = read_bits(color_bits) end
    end
    for i = 1, count do e[4][i] = alpha_bits > 0 and read_bits(alpha_bits) or 255 end
    return e
end

-- The p-bits into PBITS: one per endpoint, or one per subset shared by its two endpoints.
local function read_pbits(count, subsets, per_endpoint)
    local p = PBITS
    if per_endpoint then
        for i = 1, count do p[i] = read_bits(1) end
    else
        for s = 1, subsets do
            local v = read_bits(1)
            p[2 * s - 1], p[2 * s] = v, v
        end
    end
    return p
end

-- Appends the p-bits below each component, then widens every component to 8 bits.
local function finish_endpoints(e, p, count, color_bits, alpha_bits)
    for i = 1, count do
        for c = 1, 3 do
            local v = p and bor(lshift(e[c][i], 1), p[i]) or e[c][i]
            e[c][i] = widen(v, color_bits)
        end
        if alpha_bits > 0 then
            local v = p and bor(lshift(e[4][i], 1), p[i]) or e[4][i]
            e[4][i] = widen(v, alpha_bits)
        end
    end
end

-- Endpoints: e[channel][endpoint] (channels 1-4 = R, G, B, A; endpoints 1..2*subsets), widened to 8 bits.
local function read_endpoints(m)
    local subsets, color_bits, alpha_bits = m[2], m[3], m[4]
    local count = subsets * 2
    local e = raw_endpoints(count, color_bits, alpha_bits)
    local p = nil
    if m[5] or m[6] then
        p = read_pbits(count, subsets, m[5])
        color_bits, alpha_bits = color_bits + 1, alpha_bits > 0 and alpha_bits + 1 or 0
    end
    finish_endpoints(e, p, count, color_bits, alpha_bits)
    return e
end

-- An index list (16 entries) into out: the primary one and, for modes 4 and 5, the secondary one.
local function read_indices(subsets, partition, bits, out)
    for t = 0, 15 do
        local _, anchor = subset_of(subsets, partition, t)
        out[t + 1] = read_bits(anchor and bits - 1 or bits)
    end
    return out
end

local function interpolate(a, b, weight)
    return rshift((64 - weight) * a + weight * b + 32, 6)
end

-- Decodes texel t of a parsed block b into out (RGBA at 4 * t).
local function decode_texel(b, t, out)
    local s = subset_of(b.subsets, b.partition, t)
    local e, e0, e1 = b.e, 2 * s + 1, 2 * s + 2
    local wc = WEIGHTS[b.color_bits][b.color_index[t + 1] + 1]
    local r = interpolate(e[1][e0], e[1][e1], wc)
    local g = interpolate(e[2][e0], e[2][e1], wc)
    local bl = interpolate(e[3][e0], e[3][e1], wc)
    local wa = b.alpha_index and WEIGHTS[b.alpha_bits][b.alpha_index[t + 1] + 1] or wc
    local a = interpolate(e[4][e0], e[4][e1], wa)
    local rotation = b.rotation
    if rotation == 1 then r, a = a, r elseif rotation == 2 then g, a = a, g elseif rotation == 3 then bl, a = a, bl end
    out[4 * t], out[4 * t + 1], out[4 * t + 2], out[4 * t + 3] = r, g, bl, a
end

-- The block's fields after its mode bits, parsed into BLOCK: partition, rotation, endpoints, index lists.
local function parse_block(mode)
    local m = MODES[mode]
    local b = BLOCK
    b.subsets = m[2]
    b.partition = m[1] > 0 and read_bits(m[1]) or 0
    b.rotation = (mode == 4 or mode == 5) and read_bits(2) or 0
    local selector = mode == 4 and read_bits(1) or 0
    b.e = read_endpoints(m)
    local primary = read_indices(b.subsets, b.partition, m[7], PRIMARY)
    local secondary = m[8] > 0 and read_indices(1, 0, m[8], SECONDARY) or nil
    b.color_index, b.alpha_index, b.color_bits, b.alpha_bits = primary, secondary, m[7], m[8]
    if selector == 1 then b.color_index, b.alpha_index, b.color_bits, b.alpha_bits = secondary, primary, m[8], m[7] end
    return b
end

-- Decodes one BC7 block (the 16 bytes from block[offset], offset 0 by default: no pointer made per block) into out
-- (64 bytes, RGBA per texel, row-major 4 x 4). An invalid mode gives zeros, as the format defines.
function Texture.bc7_block(block, out, offset)
    offset = offset or 0
    local first = block[offset]
    if first == 0 then
        for i = 0, 63 do out[i] = 0 end
        return
    end
    local mode = 0
    while band(rshift(first, mode), 1) == 0 do mode = mode + 1 end
    bits_block, bits_offset, bits_position = block, offset, mode + 1
    local b = parse_block(mode)
    for t = 0, 15 do decode_texel(b, t, out) end
    bits_block = nil
end

-- Stores the 16 texels of one decoded 4 x 4 block (texel: 64 bytes RGBA) at block position (bx, by) into
-- values (double array, row-major w texels per row), keeping only texels with index below count.
local function place_block(texel, bx, by, w, count, values)
    for t = 0, 15 do
        local x, y = bx * 4 + t % 4, by * 4 + rshift(t, 2)
        local i = y * w + x
        if x < w and i < count then
            for c = 0, 3 do values[i * 4 + c] = texel[t * 4 + c] / 255 end
        end
    end
end

-- The first `count` texels (row-major) of a BC7 mip `w` texels wide starting at `base`, into values.
local function bc7_texels(pixels, base, w, count, scratch, values, yield)
    local texel = ffi.new('uint8_t[64]')
    local blocks_wide = math.max(1, rshift(w + 3, 2))
    local block_rows = math.ceil(math.ceil(count / w) / 4)
    local raw = scratch(blocks_wide * block_rows * 16)
    pixels(base, blocks_wide * block_rows * 16, raw, 0)
    for by = 0, block_rows - 1 do
        for bx = 0, blocks_wide - 1 do
            Texture.bc7_block(raw, texel, (by * blocks_wide + bx) * 16)
            place_block(texel, bx, by, w, count, values)
        end
        if yield then yield() end
    end
end

-- The first `count` texels (row-major) of a float mip at `base` (RGBA16F or RGBA32F: a mod's tiler) into values as the
-- 8-bit channels the game's tilers have, /255 (clamped to 0-1, rounded: what the disk cache keeps of the samples).
local function float_texels(pixels, info, base, count, scratch, values)
    local per = TEXEL_BYTES[info.format] / 4
    local raw = scratch(count * 4 * per)
    pixels(base, count * 4 * per, raw, 0)
    for i = 0, count * 4 - 1 do
        local v = per == 2 and half(raw[2 * i], raw[2 * i + 1]) or single(raw, 4 * i)
        if not (v > 0) then v = 0 elseif v > 1 then v = 1 end -- NaN too
        values[i] = math.floor(v * 255 + 0.5) / 255
    end
end

-- The first `count` texels (row-major) of mip `mip` of every layer, channels/255 as {layer -> double array of
-- count * 4}. For BC7 the block rows those texels need are decoded; RGBA8 is read as is; a float format as
-- float_texels. Another format raises (v1.3 read any of them as RGBA8).
function Texture.samples(pixels, info, mip, count, scratch, yield)
    local f = info.format
    local float = f == Texture.FORMAT_RGBA16F or f == Texture.FORMAT_RGBA32F
    if f ~= Texture.FORMAT_BC7 and f ~= Texture.FORMAT_RGBA8 and f ~= Texture.FORMAT_RGBA8_SRGB and not float then
        error('tiler format ' .. f, 0)
    end
    local w = math.max(1, rshift(info.width, mip))
    local out = {}
    for l = 0, info.layers - 1 do
        local base = l * info.layer_bytes + info.mip_offsets[mip]
        local values = ffi.new('double[?]', count * 4)
        if f == Texture.FORMAT_BC7 then
            bc7_texels(pixels, base, w, count, scratch, values, yield)
        elseif float then
            float_texels(pixels, info, base, count, scratch, values)
        else
            local raw = scratch(count * 4)
            pixels(base, count * 4, raw, 0)
            for i = 0, count * 4 - 1 do values[i] = raw[i] / 255 end
        end
        out[l] = values
        if yield then yield() end
    end
    return out
end

-- Code that runs once or rarely (jobs, startup, events) stays interpreted, sub-functions included: it must not
-- add traces to the LuaJIT code cache the game and every mod share. Only the hot loops stay compiled.
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({mip_bytes, Texture.describe, Texture.pixels, half, single, Texture.lut, read_bits, subset_of,
        widen, raw_endpoints,
        read_pbits, finish_endpoints, read_endpoints, read_indices, interpolate, decode_texel, parse_block,
        Texture.bc7_block,
        place_block, bc7_texels, float_texels, Texture.samples, Texture.mask_coverage}) do
        jit.off(fn, true)
    end
end

return Texture
end)()
local Albedo = (function()
-- Match Your Colors: modded gear without a color table (v1.5, end-user report 2026-10-14: the Cowboy Hat mod). A mod
-- can give a helmet or armor a material that paints its colors into its albedo texture instead of the game's color
-- table (material LUT) and ID mask: the (third-party) Cowboy Hat replaces the GS-11 Democracy's Deputy's unit with a
-- hat whose material, of the character shader (content/art_shared/base_shaders/character), holds a 2048 x 2048 BC1
-- albedo, a BC3 mra (metallic, roughness, ambient occlusion) and a BC5 normal map. v1.4 found no color table there: the
-- hat gave no colors and was never recolored.
--
-- Read (src/kits.lua): the first mip of the albedo no larger than READ_SIDE (the hat's mip 3, 256 x 256) is decoded with
-- its mra at the same size; its opaque texels are binned (4-4-4 sRGB and a metal bit, linear sums) and clustered
-- (farthest-point seeds at least SEED_DE apart, at most LLOYD_STEPS steps, at most CLUSTERS, a cluster under
-- MERGE_SHARE merged into its nearest): each cluster is a color row of the analysis, a share of its piece like a LUT
-- row's, its color the cluster's mean albedo.
-- Recolor (src/recolor.lua): each planned cluster's goal moves the texture's block endpoints. Every distinct RGB565
-- endpoint is mapped once (memo), by its closeness to the clusters (WEIGHT_DE), each cluster's lightness change as a
-- part's in the matcher (a ratio when it darkens, a difference when it lightens) and its tint; every block of every mip
-- then takes the mapped endpoints with its indices kept, swapped where a BC1 block's endpoint order flips so it keeps its
-- 4-color mode, or its 3-color mode and transparency. BC3 color blocks are always 4-color: endpoints only. The normal
-- and mra maps stay, so grain, shading and metal stay. Endpoints are mapped by their color alone: two clusters of one
-- color (a metal part painted like the leather beside it) move together, by the mean of their moves. Nothing here
-- runs per frame: analyses and recolors run in jobs, with a pause every BLOCKS_PER_PAUSE blocks, POINTS_PER_PAUSE
-- points and MISSES_PER_PAUSE new endpoints. Outside the game a hat-like 2048 x 2048 albedo takes about 2.3 ms to read
-- and 1.4 ms to recolor, a worst case of random colors 19 ms and 77 ms; stretches between pauses mostly under 0.45 ms,
-- the longest 0.9 ms (the first slices: the block loops compile; research/scratch/v15/albedo_timing*.lua).
local ffi = require('ffi')
local bit = require('bit')
local band, bor, bxor, bnot, lshift, rshift = bit.band, bit.bor, bit.bxor, bit.bnot, bit.lshift, bit.rshift

local Albedo = {}

Albedo.TEMPLATES = {['7712ee7808e0ec50'] = true} -- content/art_shared/base_shaders/character
Albedo.SLOT_ALBEDO, Albedo.SLOT_MRA = 0xac652e43, 0x756f6fa6 -- the material's texture slots 'albedo' and 'mra'
Albedo.BC1 = {[71] = true, [72] = true} -- DXGI BC1 (UNORM, sRGB)
Albedo.BC3 = {[77] = true, [78] = true} -- DXGI BC3 (UNORM, sRGB)
Albedo.READ_SIDE, Albedo.CLUSTERS, Albedo.SEED_DE, Albedo.LLOYD_STEPS = 256, 8, 6.0, 8
Albedo.MERGE_SHARE, Albedo.METAL_AXIS, Albedo.WEIGHT_DE = 0.005, 30.0, 4.0
Albedo.NEUTRAL_C = 5.0 -- a goal under this chroma passes no hue offsets (src/matcher.lua NEUTRAL_TINT_C)
-- How a mod's albedo looks: the study's typical response (gain r, g, b and gloss r, g, b: the medians of its 6,216
-- measured LUT rows, src/appearance_data.lua; research/scratch/v15/typical_response.lua), as an unmeasured LUT row
-- looks through its study row. The Cowboy Hat's crown (albedo L 36.7) shows L 30.2 in the Armory; through this, L 31.9.
-- Matched by its albedo, the B-01 Tactical's jacket took L 49 on screen (review renders 2026-10-14).
Albedo.RESPONSE = {0.7140, 0.6710, 0.6400, 0.00600, 0.00670, 0.00730}

-- A cluster's look (CIELAB) from its mean linear albedo; and the albedo (CIELAB) that looks like a goal.
function Albedo.look(Colour, r, g, b)
    return Colour.linear_to_lab(Colour.seen(Albedo.RESPONSE, r, g, b, true))
end
function Albedo.unlook(Colour, L, a, b)
    local R, k = Albedo.RESPONSE, {Colour.lab_to_linear(L, a, b)}
    return Colour.linear_to_lab(math.max((k[1] - R[4]) / R[1], 0), math.max((k[2] - R[5]) / R[2], 0),
                                math.max((k[3] - R[6]) / R[3], 0))
end
Albedo.BLOCKS_PER_PAUSE, Albedo.POINTS_PER_PAUSE, Albedo.MISSES_PER_PAUSE = 1024, 256, 256

local u32 = function(p, o) return p[o] + p[o + 1] * 256 + p[o + 2] * 65536 + p[o + 3] * 16777216 end

-- Session buffers, made once: the bins (4,096 colors x metal: count, linear r, g, b sums, metallic sum), the decoded
-- blocks, the endpoint memo.
local BINS = 8192
local bins, texels, mra_texels, memo, seen
local function buffers()
    if bins then return end
    bins = ffi.new('double[?]', BINS * 5)
    texels, mra_texels = ffi.new('uint8_t[64]'), ffi.new('uint8_t[64]')
    memo, seen = ffi.new('uint16_t[65536]'), ffi.new('uint8_t[65536]')
end

-- sRGB byte -> linear, once.
local TO_LINEAR = {}
for i = 0, 255 do
    local c = i / 255
    TO_LINEAR[i] = c <= 0.04045 and c / 12.92 or ((c + 0.055) / 1.055) ^ 2.4
end
local function to_byte(linear)
    local c = math.min(math.max(linear, 0), 1)
    c = c <= 0.0031308 and c * 12.92 or 1.055 * c ^ (1 / 2.4) - 0.055
    return math.floor(c * 255 + 0.5)
end

-- An RGB565 color's 8-bit channels.
local function rgb565(e)
    local r, g, b = rshift(e, 11), band(rshift(e, 5), 63), band(e, 31)
    return bor(lshift(r, 3), rshift(r, 2)), bor(lshift(g, 2), rshift(g, 4)), bor(lshift(b, 3), rshift(b, 2))
end
local function pack565(r, g, b)
    local r5 = math.floor(r * 31 / 255 + 0.5)
    local g6 = math.floor(g * 63 / 255 + 0.5)
    local b5 = math.floor(b * 31 / 255 + 0.5)
    return r5 * 2048 + g6 * 32 + b5
end

-- A BC1 color block at p[o] (8 bytes; three_color: its c0 <= c1 mode counts, a BC3 color block's never does) into out
-- (16 texels x RGBA, bytes); a transparent texel has alpha 0.
function Albedo.color_block(p, o, out, three_color)
    local c0, c1 = p[o] + p[o + 1] * 256, p[o + 2] + p[o + 3] * 256
    local r0, g0, b0 = rgb565(c0)
    local r1, g1, b1 = rgb565(c1)
    local four = c0 > c1 or not three_color
    local idx = u32(p, o + 4)
    for t = 0, 15 do
        local i = band(rshift(idx, 2 * t), 3)
        local r, g, b, a = r0, g0, b0, 255
        if i == 1 then
            r, g, b = r1, g1, b1
        elseif i == 2 then
            if four then
                r, g, b = math.floor((2 * r0 + r1) / 3), math.floor((2 * g0 + g1) / 3), math.floor((2 * b0 + b1) / 3)
            else
                r, g, b = math.floor((r0 + r1) / 2), math.floor((g0 + g1) / 2), math.floor((b0 + b1) / 2)
            end
        elseif i == 3 then
            if four then
                r, g, b = math.floor((r0 + 2 * r1) / 3), math.floor((g0 + 2 * g1) / 3), math.floor((b0 + 2 * b1) / 3)
            else
                r, g, b, a = 0, 0, 0, 0
            end
        end
        out[4 * t], out[4 * t + 1], out[4 * t + 2], out[4 * t + 3] = r, g, b, a
    end
end

-- The bytes of a block format's mip chain (one layer) and its block size.
local function block_bytes(format) return Albedo.BC1[format] and 8 or 16 end
local function mip_size(info, m)
    return math.max(1, rshift(info.width, m)), math.max(1, rshift(info.height, m))
end

-- Whether a material with no color table can be read and recolored here: a mod's (record.file), of a template in
-- TEMPLATES (parent), with an albedo of a power-of-two size in BC1 or BC3. describe(name) -> info or nil (the
-- texture's Texture.describe). Returns {albedo, mra} or nil and why.
function Albedo.eligible(record, parent, textures, describe)
    if not (record and record.file) then return nil, 'not a mod\'s material' end
    if not Albedo.TEMPLATES[parent] then return nil, 'shader template ' .. tostring(parent) end
    local albedo = textures[Albedo.SLOT_ALBEDO]
    if not albedo then return nil, 'no albedo' end
    local ok, info = pcall(describe, albedo)
    if not ok or not info then return nil, 'albedo ' .. albedo .. ': ' .. tostring(ok and 'not found' or info) end
    local f, w, h = info.format, info.width, info.height
    if not (Albedo.BC1[f] or Albedo.BC3[f]) then return nil, 'albedo format ' .. f end
    if band(w, w - 1) ~= 0 or band(h, h - 1) ~= 0 then return nil, 'albedo size ' .. w .. ' x ' .. h end
    return {albedo = albedo, mra = textures[Albedo.SLOT_MRA]}
end

-- The mip to read: the first no larger than READ_SIDE on either side.
local function read_mip(info)
    for m = 0, info.mips - 1 do
        local w, h = mip_size(info, m)
        if w <= Albedo.READ_SIDE and h <= Albedo.READ_SIDE then return m end
    end
    return info.mips - 1
end

-- One block of the read mip into the bins: its opaque texels, metal where the mra's red reads over half.
local function bin_block(p, o, three_color, mra, mo)
    Albedo.color_block(p, o, texels, three_color)
    if mra then Albedo.color_block(mra, mo + 8, mra_texels, false) end
    for t = 0, 15 do
        if texels[4 * t + 3] >= 128 then
            local r, g, b = texels[4 * t], texels[4 * t + 1], texels[4 * t + 2]
            local metal = mra and mra_texels[4 * t] >= 128
            local k = (rshift(r, 4) * 256 + rshift(g, 4) * 16 + rshift(b, 4) + (metal and 4096 or 0)) * 5
            bins[k] = bins[k] + 1
            bins[k + 1], bins[k + 2], bins[k + 3] = bins[k + 1] + TO_LINEAR[r], bins[k + 2] + TO_LINEAR[g],
                bins[k + 3] + TO_LINEAR[b]
            if metal then bins[k + 4] = bins[k + 4] + 1 end
        end
    end
end

-- The non-empty bins as points {count, lin = {r, g, b}, lab = {L, a, b}, metal (0-1)}, in bin order.
local function points(Colour, yield)
    local out = {}
    for k = 0, BINS - 1 do
        local n = bins[5 * k]
        if n > 0 then
            local r, g, b = bins[5 * k + 1] / n, bins[5 * k + 2] / n, bins[5 * k + 3] / n
            local L, A, B = Colour.linear_to_lab(r, g, b)
            out[#out + 1] = {count = n, lin = {r, g, b}, lab = {L, A, B}, metal = bins[5 * k + 4] / n}
            if #out % Albedo.POINTS_PER_PAUSE == 0 then yield() end
        end
    end
    return out
end

-- Squared distance of a point to a cluster: CIELAB, metal on an axis of its own (METAL_AXIS per unit).
local function d2(p, c)
    local dL, da, db = p.lab[1] - c.lab[1], p.lab[2] - c.lab[2], p.lab[3] - c.lab[3]
    local dm = (p.metal - c.metal) * Albedo.METAL_AXIS
    return dL * dL + da * da + db * db + dm * dm
end

-- The point of the largest count x squared distance to its nearest seed, that distance at least SEED_DE (ties: the
-- earlier point), or nil; near[i]: point i's squared distance to its nearest seed before `last`, updated with it.
local function farthest(pts, near, last, yield)
    local pick, score = nil, -1
    for i, p in ipairs(pts) do
        local d = math.min(near[i], d2(p, last))
        near[i] = d
        if d >= Albedo.SEED_DE * Albedo.SEED_DE and p.count * d > score then pick, score = p, p.count * d end
        if i % Albedo.POINTS_PER_PAUSE == 0 then yield() end
    end
    return pick
end

-- Farthest-point seeds: the heaviest point, then the farthest (above) while there is one, at most CLUSTERS.
local function seeds(pts, yield)
    local best
    for _, p in ipairs(pts) do if not best or p.count > best.count then best = p end end
    local out, near = {{lab = best.lab, metal = best.metal}}, {}
    for i = 1, #pts do near[i] = math.huge end
    while #out < Albedo.CLUSTERS do
        local pick = farthest(pts, near, out[#out], yield)
        if not pick then break end
        out[#out + 1] = {lab = pick.lab, metal = pick.metal}
    end
    return out
end

-- Index of the cluster nearest point p (ties: the earlier).
local function nearest(p, clusters)
    local best, bd = 1, math.huge
    for i, c in ipairs(clusters) do
        local d = d2(p, c)
        if d < bd then best, bd = i, d end
    end
    return best
end

-- Clusters from the points' assignment: mean linear color and metal by count; empty ones dropped.
local function means(pts, assign, k, Colour)
    local acc = {}
    for i = 1, k do acc[i] = {count = 0, r = 0, g = 0, b = 0, m = 0} end
    for i, p in ipairs(pts) do
        local a = acc[assign[i]]
        a.count, a.r, a.g, a.b = a.count + p.count, a.r + p.count * p.lin[1], a.g + p.count * p.lin[2],
            a.b + p.count * p.lin[3]
        a.m = a.m + p.count * p.metal
    end
    local out = {}
    for _, a in ipairs(acc) do
        if a.count > 0 then
            local lin = {a.r / a.count, a.g / a.count, a.b / a.count}
            out[#out + 1] = {count = a.count, lin = lin, lab = {Colour.linear_to_lab(lin[1], lin[2], lin[3])},
                             metal = a.m / a.count}
        end
    end
    return out
end

-- Each point's nearest cluster into assign; whether any changed. A pause every POINTS_PER_PAUSE points.
local function assigned(pts, clusters, assign, yield)
    local moved = false
    for i, p in ipairs(pts) do
        local n = nearest(p, clusters)
        if assign[i] ~= n then assign[i], moved = n, true end
        if i % Albedo.POINTS_PER_PAUSE == 0 then yield() end
    end
    return moved
end

-- Lloyd steps from the seeds, then the small clusters merged into their nearest; largest first.
local function cluster(pts, Colour, yield)
    local clusters, assign = seeds(pts, yield), {}
    for _ = 1, Albedo.LLOYD_STEPS do
        local moved = assigned(pts, clusters, assign, yield)
        clusters = means(pts, assign, #clusters, Colour)
        yield()
        if not moved then break end
    end
    local total = 0
    for _, c in ipairs(clusters) do total = total + c.count end
    local kept = {}
    for _, c in ipairs(clusters) do if c.count >= Albedo.MERGE_SHARE * total then kept[#kept + 1] = c end end
    assigned(pts, kept, assign, yield)
    clusters = means(pts, assign, #kept, Colour)
    table.sort(clusters, function(x, y)
        if x.count ~= y.count then return x.count > y.count end
        return x.lab[1] < y.lab[1]
    end)
    for _, c in ipairs(clusters) do
        c.share = c.count / total
        c.seen = {Albedo.look(Colour, c.lin[1], c.lin[2], c.lin[3])}
    end
    return clusters
end

-- The mra's mip of w x h (BC3 blocks), or nil (no mra, another format, no mip of that size).
local function read_mra(entry, texture, w, h)
    local info, read
    if entry.mra then info, read = texture(entry.mra) end
    if not (info and Albedo.BC3[info.format]) then return nil end
    for m = 0, info.mips - 1 do
        local mw, mh = mip_size(info, m)
        if mw == w and mh == h then
            local size = rshift(w + 3, 2) * rshift(h + 3, 2) * 16
            local mra = ffi.new('uint8_t[?]', size)
            read(info.mip_offsets[m], size, mra, 0)
            return mra
        end
    end
    return nil
end

-- Every block of the read mip (data, w x h) into the emptied bins, with a pause every BLOCKS_PER_PAUSE.
local function bin_mip(data, format, w, h, mra, yield)
    ffi.fill(bins, BINS * 5 * 8)
    local three, step = Albedo.BC1[format] == true, block_bytes(format)
    for i = 0, rshift(w + 3, 2) * rshift(h + 3, 2) - 1 do
        bin_block(data, i * step + (step == 16 and 8 or 0), three, mra, i * 16)
        if i % Albedo.BLOCKS_PER_PAUSE == Albedo.BLOCKS_PER_PAUSE - 1 then yield() end
    end
end

-- An albedo's clusters (above): {format, width, height, mips, total (one layer's bytes), clusters = {{share, lin, lab,
-- metal}, ...}}, or nil and why. texture(name) -> info, read(at, size, out, out_offset) or nil (the analysis's reader);
-- entry: Albedo.eligible's. Colour: src/colour.lua.
function Albedo.read(entry, texture, Colour, yield)
    buffers()
    local info, read = texture(entry.albedo)
    if not info then return nil, 'albedo not found' end
    local m = read_mip(info)
    local w, h = mip_size(info, m)
    local size = rshift(w + 3, 2) * rshift(h + 3, 2) * block_bytes(info.format)
    local data = ffi.new('uint8_t[?]', size)
    read(info.mip_offsets[m], size, data, 0)
    bin_mip(data, info.format, w, h, read_mra(entry, texture, w, h), yield)
    local pts = points(Colour, yield)
    if #pts == 0 then return nil, 'no opaque texel' end
    return {format = info.format, width = info.width, height = info.height, mips = info.mips, total = info.layer_bytes,
            clusters = cluster(pts, Colour, yield)}
end

-- A part's lightness when its cluster, of lightness t_L, takes base (src/matcher.lua row_lightness): a luminance ratio
-- when it darkens, a difference when it lightens.
local function lightness(Colour, base, x_L, t_L)
    if base >= t_L then return base + (x_L - t_L) end
    local y = Colour.lab_to_linear(base, 0, 0) * Colour.lab_to_linear(x_L, 0, 0)
        / math.max(Colour.lab_to_linear(t_L, 0, 0), 1e-9)
    return (Colour.linear_to_lab(y, y, y))
end

-- The cluster moves of a plan: {[cluster] = {lab = its albedo Lab, goal = {L, a, b} or nil, scale}}: a planned
-- cluster's goal (a look) as the albedo that looks like it (Albedo.unlook), its hue offsets kept by the chroma change
-- (none toward a neutral goal).
function Albedo.moves(albedo, goals, Colour)
    local out = {}
    for k, c in ipairs(albedo.clusters) do
        local g = goals[k]
        local move = {lab = c.lab}
        if g then
            local L, a, b = Albedo.unlook(Colour, g.L, g.a, g.b)
            local gc, cc = math.sqrt(a * a + b * b), math.sqrt(c.lab[2] ^ 2 + c.lab[3] ^ 2)
            move.goal = {L, a, b}
            move.scale = math.sqrt(g.a * g.a + g.b * g.b) < Albedo.NEUTRAL_C and 0
                or (cc > 1 and math.min(1, gc / cc) or 1)
        end
        out[k] = move
    end
    return out
end

-- An endpoint's new RGB565: its color moved by every cluster's move weighed by closeness (exp(-d^2 / 2 WEIGHT_DE^2);
-- the nearest alone when all weigh nothing).
local function move_endpoint(e, moves, Colour)
    local r, g, b = rgb565(e)
    local L, A, B = Colour.linear_to_lab(TO_LINEAR[r], TO_LINEAR[g], TO_LINEAR[b])
    local sw, sL, sa, sb, best, bd = 0, 0, 0, 0, nil, math.huge
    for _, mv in ipairs(moves) do
        local dL, da, db = L - mv.lab[1], A - mv.lab[2], B - mv.lab[3]
        local d = dL * dL + da * da + db * db
        local w = math.exp(-d / (2 * Albedo.WEIGHT_DE * Albedo.WEIGHT_DE))
        local tL, ta, tb = L, A, B
        if mv.goal then
            tL = lightness(Colour, mv.goal[1], L, mv.lab[1])
            ta, tb = mv.goal[2] + (A - mv.lab[2]) * mv.scale, mv.goal[3] + (B - mv.lab[3]) * mv.scale
        end
        sw, sL, sa, sb = sw + w, sL + w * tL, sa + w * ta, sb + w * tb
        if d < bd then best, bd = {tL, ta, tb}, d end
    end
    if sw < 1e-12 then sL, sa, sb, sw = best[1], best[2], best[3], 1 end
    local lr, lg, lb = Colour.lab_to_linear(sL / sw, sa / sw, sb / sw)
    return pack565(to_byte(lr), to_byte(lg), to_byte(lb))
end

-- The endpoint memo emptied (before each recolored albedo: a memo holds one albedo's moves).
function Albedo.forget()
    buffers()
    ffi.fill(seen, 65536)
end

-- An endpoint's new RGB565 from the memo, map(e) the first time (Albedo.forget empties the memo).
local function mapped(e, map)
    if seen[e] == 0 then memo[e], seen[e] = map(e), 1 end
    return memo[e]
end

-- A BC1 block's new endpoints n0, n1 (of c0, c1) in the order that keeps its mode, its indices at u32p[x] remapped
-- when they swap: 4-color indices flip 0<->1 and 2<->3 (xor 0x55555555), 3-color ones 0<->1 only (2, the middle, and
-- 3, transparent, stay); two equal endpoints of a 4-color block give index 0 (the same color, never the 3-color mode's
-- transparency).
local function bc1_order(u32p, x, c0, c1, n0, n1)
    if c0 > c1 then
        if n0 < n1 then
            u32p[x] = bxor(u32p[x], 0x55555555)
            return n1, n0
        end
        if n0 == n1 then u32p[x] = 0 end
        return n0, n1
    end
    if n0 > n1 then
        local idx = u32p[x]
        u32p[x] = bxor(idx, band(bnot(rshift(idx, 1)), 0x55555555))
        return n1, n0
    end
    return n0, n1
end

-- Blocks [first, last) of a BC1 (step 8) or BC3 (step 16, color at +8) mip chain rewritten with the memo's endpoints
-- (map(e): an endpoint not in the memo yet), a BC1 block's in the order that keeps its mode (bc1_order).
function Albedo.rewrite(data, first, last, step, map)
    local u16 = ffi.cast('uint16_t *', data)
    local u32p = ffi.cast('int32_t *', data) -- signed: bit operations' results store as they are
    local co = step == 16 and 4 or 0
    for i = first, last - 1 do
        local w = (i * step) / 2 + co -- uint16 index of c0
        local c0, c1 = u16[w], u16[w + 1]
        local n0, n1 = mapped(c0, map), mapped(c1, map)
        if step == 8 then n0, n1 = bc1_order(u32p, i * 2 + 1, c0, c1, n0, n1) end -- its indices: uint32 2i + 1
        u16[w], u16[w + 1] = n0, n1
    end
end

-- The recolored albedo for plan goals {[cluster] = goal}: {albedo = true, bc1, name, width, height, mips, size,
-- format (DXGI), data}; data: its whole mip chain (src/recolor.lua pipeline chain: a fresh copy), rewritten in place.
function Albedo.spec(name, albedo, goals, data, Colour, yield)
    Albedo.forget()
    local moves = Albedo.moves(albedo, goals, Colour)
    local step = block_bytes(albedo.format)
    local blocks = albedo.total / step
    local misses = 0
    local function map(e)
        misses = misses + 1
        if misses % Albedo.MISSES_PER_PAUSE == 0 then yield() end
        return move_endpoint(e, moves, Colour)
    end
    for first = 0, blocks - 1, Albedo.BLOCKS_PER_PAUSE do
        Albedo.rewrite(data, first, math.min(first + Albedo.BLOCKS_PER_PAUSE, blocks), step, map)
        yield()
    end
    return {albedo = true, bc1 = Albedo.BC1[albedo.format] == true, name = name, width = albedo.width,
            height = albedo.height, mips = albedo.mips, size = albedo.total, format = albedo.format, data = data}
end

-- A target's recolored albedos for plan into out (a plan's luts, beside its LUTs: src/recolor.lua binds them on the
-- albedo slot): each albedo with a planned cluster; chain(name, archive) -> data, info (src/recolor.lua). Returns the
-- log line ("Mod texture <name>: <n> colors read (shares); <m> recolored"), one per albedo, and one per mod's material
-- left unread (target.unread, src/kits.lua), or nil.
-- An albedo's plan goals ({[cluster] = goal}), how many, and its clusters' shares as the log gives them.
local function goals_of(name, albedo, plan)
    local goals, count, shares = {}, 0, {}
    for k, c in ipairs(albedo.clusters) do
        goals[k] = plan[name .. ':' .. (k - 1)]
        count = count + (goals[k] and 1 or 0)
        shares[k] = string.format('%.0f%%%s', 100 * c.share, c.metal > 0.5 and ' metal' or '')
    end
    return goals, count, shares
end

-- The albedo recolored for goals (Albedo.spec) in a fresh copy of its chain (ctx: chain, archive, Colour, yield);
-- raises when the texture is not the one analysed.
local function recolored(name, albedo, goals, ctx)
    local data, info = ctx.chain(name, ctx.archive)
    if not data or info.format ~= albedo.format or info.layer_bytes ~= albedo.total then
        error('mod texture ' .. name .. ' is not the texture analysed', 0)
    end
    return Albedo.spec(name, albedo, goals, data, ctx.Colour, ctx.yield)
end

function Albedo.plan_specs(target, plan, out, chain, Colour, yield)
    local lines = {}
    for _, u in pairs(target.unread or {}) do
        lines[#lines + 1] = string.format('Mod material %s (from %s) has no color table and is left as it is: %s.',
                                          u.material, tostring(u.file), u.why)
    end
    local ctx = {chain = chain, archive = target.kit.archive, Colour = Colour, yield = yield}
    for name, albedo in pairs(target.albedos or {}) do
        if albedo then -- false: its read failed (src/kits.lua add_albedo)
            local goals, count, shares = goals_of(name, albedo, plan)
            if count > 0 then out[name] = recolored(name, albedo, goals, ctx) end
            lines[#lines + 1] = string.format('Mod texture %s (a material without a color table): %d colors read (%s); '
                .. '%d recolored.', name, #albedo.clusters, table.concat(shares, ', '), count)
        end
    end
    table.sort(lines)
    return #lines > 0 and table.concat(lines, ' ') or nil
end

-- Interpreted (jobs only), but the block loops: Albedo.rewrite (with mapped and bc1_order) and bin_block (with
-- Albedo.color_block) run a few hundred thousand times per recolor and stay compiled (src/patches.lua's adler
-- likewise).
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({buffers, to_byte, pack565, block_bytes, mip_size, Albedo.eligible, read_mip, points, d2,
        farthest, seeds, nearest, means, assigned, cluster, read_mra, bin_mip, Albedo.read, lightness, Albedo.moves,
        move_endpoint, Albedo.forget, Albedo.spec, goals_of, recolored, Albedo.plan_specs, Albedo.look, Albedo.unlook}) do
        jit.off(fn, true)
    end
end

return Albedo
end)()
local Colour = (function()
-- Match Your Colors: the perceived color of a material-LUT row, as research/effective.py and match.py
-- compute it (a port of filediver's lut.frag albedo path).
--
-- For one LUT row the shader blends the base color (column 0, or the camo colors 16-19 through the camo
-- tiler) towards column 2 by detail intensity, towards column 6 by detail roughness x camo mix and towards
-- column 5 by roughness squared x camo mix, in sRGB, then converts to linear. Detail intensity and roughness
-- come from the global detail tiler layer (column 1 x) and the row's controls (columns 1, 3, 4). The mesh's
-- base data is taken as neutral (roughness 0.5, no occlusion), so the result is per row. The mean linear
-- albedo over 512 detail texels, darkened by 0.55 x metallic (column 6 w), in CIELAB, is the row's perceived
-- color. A row at least METAL_FULL metallic is bare metal (the matcher's paint reflection, src/matcher.lua).
-- Nothing here runs per frame.
local Colour = {}

local SAMPLES = 512
local METAL_DARKEN = 0.55
local METAL_FULL = 0.9
local WHITE_X, WHITE_Z = 0.95047, 1.08883
local EPSILON = (6 / 29) ^ 3
local KAPPA = 3 * (6 / 29) ^ 2

-- Clamped to [0, 1] without branches (min and max compile to single instructions: fewer side traces).
local min, max = math.min, math.max
local function clip(x)
    return min(max(x, 0), 1)
end

local function srgb_to_linear(c)
    if c < 0.000061 then c = 0.000061 end
    if c > 0.04045 then return (c * 0.947867 + 0.052133) ^ 2.4 end
    return c * 0.0774
end
Colour.srgb_to_linear = srgb_to_linear

-- Python's int() then % n for a float layer index.
local function layer_index(x, n)
    local i = x >= 0 and math.floor(x) or math.ceil(x)
    return i % n
end

local function lab_f(t)
    if t > EPSILON then return t ^ (1 / 3) end
    return t / KAPPA + 4 / 29
end

-- CIELAB of a linear RGB triple (clipped to [0, 1]), D65.
function Colour.linear_to_lab(r, g, b)
    r, g, b = clip(r), clip(g), clip(b)
    local fx = lab_f((0.4124564 * r + 0.3575761 * g + 0.1804375 * b) / WHITE_X)
    local fy = lab_f(0.2126729 * r + 0.7151522 * g + 0.0721750 * b)
    local fz = lab_f((0.0193339 * r + 0.1191920 * g + 0.9503041 * b) / WHITE_Z)
    return 116 * fy - 16, 500 * (fx - fy), 200 * (fy - fz)
end

-- CIELAB of an sRGB color as the shader decodes it (LUT values).
function Colour.srgb_to_lab(r, g, b)
    return Colour.linear_to_lab(srgb_to_linear(r), srgb_to_linear(g), srgb_to_linear(b))
end

local function lab_finv(t)
    if t > 6 / 29 then return t * t * t end
    return 3 * (6 / 29) ^ 2 * (t - 4 / 29)
end

local function linear_to_srgb(x)
    x = clip(x)
    if x > 0.0031308 then return 1.055 * x ^ (1 / 2.4) - 0.055 end
    return 12.92 * x
end
Colour.linear_to_srgb = linear_to_srgb

-- The linear RGB of a CIELAB color (D65), not clipped.
function Colour.lab_to_linear(L, a, b)
    local fy = (L + 16) / 116
    local fx, fz = fy + a / 500, fy - b / 200
    local x, y, z = lab_finv(fx) * WHITE_X, lab_finv(fy), lab_finv(fz) * WHITE_Z
    return 3.2404542 * x - 1.5371385 * y - 0.4985314 * z,
        -0.9692660 * x + 1.8760108 * y + 0.0415560 * z,
        0.0556434 * x - 0.2040259 * y + 1.0572252 * z
end

-- The sRGB color of a CIELAB color (D65), clipped to the displayable range.
function Colour.lab_to_srgb(L, a, b)
    local r, g, bl = Colour.lab_to_linear(L, a, b)
    return linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(bl)
end

-- The mean hue angle of CIEDE2000.
local function mean_hue(h1p, h2p, zero)
    local hsum = h1p + h2p
    if zero then return hsum end
    if math.abs(h1p - h2p) > 180 then return hsum < 360 and (hsum + 360) / 2 or (hsum - 360) / 2 end
    return hsum / 2
end

-- CIEDE2000 difference of two Lab colors (match.py's de2000, scalar).
function Colour.de2000(L1, a1, b1, L2, a2, b2)
    local C1, C2 = math.sqrt(a1 * a1 + b1 * b1), math.sqrt(a2 * a2 + b2 * b2)
    local Cm7 = ((C1 + C2) / 2) ^ 7
    local G = 0.5 * (1 - math.sqrt(Cm7 / (Cm7 + 25 ^ 7)))
    local a1p, a2p = (1 + G) * a1, (1 + G) * a2
    local C1p, C2p = math.sqrt(a1p * a1p + b1 * b1), math.sqrt(a2p * a2p + b2 * b2)
    local h1p = math.deg(math.atan2(b1, a1p)) % 360
    local h2p = math.deg(math.atan2(b2, a2p)) % 360
    local zero = C1p * C2p == 0
    local dhp = h2p - h1p
    if dhp > 180 then dhp = dhp - 360 elseif dhp < -180 then dhp = dhp + 360 end
    if zero then dhp = 0 end
    local dHp = 2 * math.sqrt(C1p * C2p) * math.sin(math.rad(dhp / 2))
    local Lpm, Cpm = (L1 + L2) / 2, (C1p + C2p) / 2
    local hpm = mean_hue(h1p, h2p, zero)
    local T = 1 - 0.17 * math.cos(math.rad(hpm - 30)) + 0.24 * math.cos(math.rad(2 * hpm))
        + 0.32 * math.cos(math.rad(3 * hpm + 6)) - 0.20 * math.cos(math.rad(4 * hpm - 63))
    local dtheta = 30 * math.exp(-(((hpm - 275) / 25) ^ 2))
    local Cpm7 = Cpm ^ 7
    local Rc = 2 * math.sqrt(Cpm7 / (Cpm7 + 25 ^ 7))
    local Sl = 1 + 0.015 * (Lpm - 50) ^ 2 / math.sqrt(20 + (Lpm - 50) ^ 2)
    local Sc, Sh = 1 + 0.045 * Cpm, 1 + 0.015 * Cpm * T
    local Rt = -math.sin(math.rad(2 * dtheta)) * Rc
    local l, c, h = (L2 - L1) / Sl, (C2p - C1p) / Sc, dHp / Sh
    return math.sqrt(l * l + c * c + h * h + Rt * c * h)
end

-- A row's columns as a flat Lua array: row_values(values, width, row)[column * 4 + channel + 1].
local function row_values(values, width, row)
    local out = {}
    local base = row * width * 4
    for k = 0, width * 4 - 1 do out[k + 1] = values[base + k] end
    return out
end
Colour.row_values = row_values

-- The model over the shared samples: detail = {layer -> double array of 512 x RGBA}, camo likewise, and
-- their layer counts. row_info(values, width, row) -> L, a, b, metal (bool), camo (bool), mode, full (bool:
-- bare metal, metallic >= METAL_FULL), and the mean linear albedo r, g, b (the measured response's input).
function Colour.new(detail, detail_layers, camo, camo_layers)
    local self = {}

    -- Sums the camo-blended sample colors into the caller's accumulators: returns the camo mix and the
    -- blended sRGB color of sample i. c: the row (row_values).
    local function camo_sample(c, s, i, md0, md1)
        local m0 = clip((s[i * 4] - 0.5) * c[85] + c[86])
        local m1 = clip((s[i * 4 + 1] - 0.5) * c[85] + c[86])
        local m2 = clip((s[i * 4 + 2] - 0.5) * c[85] + c[86])
        local r = ((c[65] * (1 - m0) + c[69] * m0) * (1 - m1) + c[73] * m1) * (1 - m2) + c[77] * m2
        local g = ((c[66] * (1 - m0) + c[70] * m0) * (1 - m1) + c[74] * m1) * (1 - m2) + c[78] * m2
        local b = ((c[67] * (1 - m0) + c[71] * m0) * (1 - m1) + c[75] * m1) * (1 - m2) + c[79] * m2
        if c[4] ~= 1.0 then
            local mix = clip(md0 * c[72] + md1 * c[76] - c[84])
            return mix, r * (1 - mix) + c[1] * mix, g * (1 - mix) + c[2] * mix, b * (1 - mix) + c[3] * mix
        end
        return 1, r, g, b
    end

    -- A sample's sRGB color: the row's color r, g, b (its base, or its camo blend of mix) through the detail's
    -- intensity and roughness at the detail sample's controls less 0.5 (md0, md1).
    local function shade(c, md0, md1, mix, r, g, b)
        local rough = clip(md0 * c[17] + md1 * c[18] + c[8])
        local intensity = clip(md0 * c[13] + md1 * c[14] + c[7])
        local cr = rough * mix
        local cr2 = cr * rough
        r, g, b = r + intensity * (c[9] - r), g + intensity * (c[10] - g), b + intensity * (c[11] - b)
        r, g, b = r + cr * (c[25] - r), g + cr * (c[26] - g), b + cr * (c[27] - b)
        return r + cr2 * (c[21] - r), g + cr2 * (c[22] - g), b + cr2 * (c[23] - b)
    end

    -- A detail layer's distinct samples (made on its first use): first[i + 1], the first sample whose controls (z, w)
    -- are sample i's, and those first samples, in order. A row without camo shows one color per distinct pair: the 26
    -- layers have 44-325 of 512 (fits' albedos: 52% of their samples, research/profiling/albedo_census.lua; srgb_to_linear
    -- was 14% of the mod's time in game, harness profile 2026-10-11, KB match-your-colors-stress-test).
    local distinct = {}
    local function distinct_of(layer, d)
        local found = distinct[layer]
        if found then return found end
        local first, firsts, seen = {}, {}, {}
        for i = 0, SAMPLES - 1 do
            local z, w = d[i * 4 + 2], d[i * 4 + 3]
            local j
            if z == z and w == w then -- a NaN (never in the game's textures) is no key: its sample stands alone
                local by_w = seen[z]
                if not by_w then
                    by_w = {}
                    seen[z] = by_w
                end
                j = by_w[w]
                if not j then by_w[w] = i + 1 end
            end
            if not j then
                j = i + 1
                firsts[#firsts + 1] = i
            end
            first[i + 1] = j
        end
        found = {first = first, firsts = firsts}
        distinct[layer] = found
        return found
    end
    local lin_r, lin_g, lin_b = {}, {}, {} -- linear colors of a layer's distinct samples, by sample index + 1

    -- Every sample shaded and linearized (camo: its own color at nearly every sample).
    local function albedo_each(c, d, s)
        local sum_r, sum_g, sum_b = 0, 0, 0
        for i = 0, SAMPLES - 1 do
            local md0, md1 = 0, 0
            if d then md0, md1 = d[i * 4 + 2] - 0.5, d[i * 4 + 3] - 0.5 end
            local r, g, b = shade(c, md0, md1, camo_sample(c, s, i, md0, md1))
            sum_r, sum_g, sum_b = sum_r + srgb_to_linear(r), sum_g + srgb_to_linear(g), sum_b + srgb_to_linear(b)
        end
        return sum_r / SAMPLES, sum_g / SAMPLES, sum_b / SAMPLES
    end

    -- Mean linear albedo of a row over the samples. c[column * 4 + channel + 1]; columns 0 base, 1 detail
    -- controls, 2 detail color, 3 intensity controls, 4 roughness controls, 5/6 wear colors, 16-19 camo
    -- colors, 20 camo extra (w), 21 camo controls. Without camo each distinct sample color is linearized once and
    -- the sums still run over all samples in order: the same bits as shading every sample (v1.3).
    local function albedo(c)
        local layer = c[4] <= 3.0 and layer_index(c[5], detail_layers)
        local d = layer and detail[layer] or nil
        local s = c[88] >= 0.0 and camo[layer_index(c[88], camo_layers)] or nil
        if s then return albedo_each(c, d, s) end
        local sum_r, sum_g, sum_b = 0, 0, 0
        if not d then -- every sample alike
            local r, g, b = shade(c, 0, 0, 1, c[1], c[2], c[3])
            r, g, b = srgb_to_linear(r), srgb_to_linear(g), srgb_to_linear(b)
            for _ = 1, SAMPLES do sum_r, sum_g, sum_b = sum_r + r, sum_g + g, sum_b + b end
            return sum_r / SAMPLES, sum_g / SAMPLES, sum_b / SAMPLES
        end
        local found = distinct_of(layer, d)
        local firsts, first = found.firsts, found.first
        for k = 1, #firsts do
            local i = firsts[k]
            local r, g, b = shade(c, d[i * 4 + 2] - 0.5, d[i * 4 + 3] - 0.5, 1, c[1], c[2], c[3])
            lin_r[i + 1], lin_g[i + 1], lin_b[i + 1] = srgb_to_linear(r), srgb_to_linear(g), srgb_to_linear(b)
        end
        for i = 1, SAMPLES do
            local j = first[i]
            sum_r, sum_g, sum_b = sum_r + lin_r[j], sum_g + lin_g[j], sum_b + lin_b[j]
        end
        return sum_r / SAMPLES, sum_g / SAMPLES, sum_b / SAMPLES
    end

    -- The mean linear albedo of a row (row_values): r, g, b. perceived_of and look_of take it, so a caller that needs
    -- both the paint's color and the look of one row computes its 512 samples once (src/transfer.lua fit).
    self.albedo = albedo

    -- The CIELAB of a row's mean albedo (no metal darkening): its paint's own color (the transfer's reference).
    function self.albedo_lab(c)
        local r, g, b = albedo(c)
        return Colour.linear_to_lab(r, g, b)
    end

    -- The perceived color of a row given as row_values, from its albedo r, g, b: L, a, b and its metallic (column 6 w,
    -- clipped).
    function self.perceived_of(c, r, g, b)
        local metallic = clip(c[28])
        local dark = 1 - METAL_DARKEN * metallic
        local L, A, B = Colour.linear_to_lab(r * dark, g * dark, b * dark)
        return L, A, B, metallic
    end
    function self.perceived(c)
        local r, g, b = albedo(c)
        return self.perceived_of(c, r, g, b)
    end

    -- The look of a row through its measured response cal = {gr, gg, gb, sr, sg, sb} (src/appearance.lua): the
    -- CIELAB of Colour.seen(g x mean albedo, s); look_of from the albedo r, g, b.
    function self.look_of(r, g, b, cal, soft)
        return Colour.linear_to_lab(Colour.seen(cal, r, g, b, soft))
    end
    function self.look(c, cal, soft)
        local r, g, b = albedo(c)
        return self.look_of(r, g, b, cal, soft)
    end

    function self.row_info(values, width, row)
        local c = row_values(values, width, row)
        local r, g, b = albedo(c)
        local metallic = clip(c[28])
        local dark = 1 - METAL_DARKEN * metallic
        local L, A, B = Colour.linear_to_lab(r * dark, g * dark, b * dark)
        return L, A, B, metallic > 0.5, c[88] >= 0, c[4], metallic >= METAL_FULL, r, g, b
    end
    -- once per layer and session: interpreted (the hot loops above stay compiled)
    if type(jit) == 'table' and type(jit.off) == 'function' then jit.off(distinct_of, true) end
    return self
end

-- The color the eye takes for a paint through its measured response cal = {gr, gg, gb, sr, sg, sb} at mean albedo
-- (r, g, b): its diffuse color g x albedo plus its gloss floor s, the floor weighed 1 - chroma / GLOSS_C (clipped to
-- 0-1): on neutral paint gloss reads as lightness, on colored paint as highlights over the paint (match12.seen).
-- soft: a matte soft row (Colour.is_soft: cloth) counts its whole floor, a broad sheen the eye takes for lightness on
-- any paint; the fit passes it (src/transfer.lua), the items' own looks keep the hard rule (match12.perceived_key).
-- Display-linear r, g, b, clipped at 0.
Colour.GLOSS_C = 20.0
function Colour.seen(cal, r, g, b, soft)
    local dr, dg, db = max(cal[1] * r, 0), max(cal[2] * g, 0), max(cal[3] * b, 0)
    local w = 1
    if not soft then
        local _, A, B = Colour.linear_to_lab(dr, dg, db)
        w = min(max(1 - math.sqrt(A * A + B * B) / Colour.GLOSS_C, 0), 1)
    end
    return max(dr + w * cal[4], 0), max(dg + w * cal[5], 0), max(db + w * cal[6], 0)
end

-- Whether a LUT row (row_values) is matte soft: mode 1 (c[4], column 0 w: cloth, leather, rubber) with no specular
-- (c[33], column 8 x, at 0: the cloth rows; glossy leather has 0.3, the UF-84 Doubt Killer's red trim among them).
function Colour.is_soft(c) return math.abs(c[4] - 1) < 0.5 and math.abs(c[33]) < 0.05 end

-- numpy's pairwise sum of a[1..n] (float64, contiguous), as np.add.reduce computes it for n <= 128.
function Colour.npsum(a, n)
    if n < 8 then
        local s = 0
        for i = 1, n do s = s + a[i] end
        return s
    end
    local r0, r1, r2, r3, r4, r5, r6, r7 = a[1], a[2], a[3], a[4], a[5], a[6], a[7], a[8]
    local i = 9
    local full = n - n % 8
    while i <= full do
        r0, r1, r2, r3 = r0 + a[i], r1 + a[i + 1], r2 + a[i + 2], r3 + a[i + 3]
        r4, r5, r6, r7 = r4 + a[i + 4], r5 + a[i + 5], r6 + a[i + 6], r7 + a[i + 7]
        i = i + 8
    end
    local s = ((r0 + r1) + (r2 + r3)) + ((r4 + r5) + (r6 + r7))
    for k = i, n do s = s + a[k] end
    return s
end

-- Python's sum() of floats a[1..n] (Python 3.12+: Neumaier's compensated sum, as CPython's builtin_sum computes it):
-- the first value, then each next one with the rounding error carried apart, the carried error added at the end when
-- finite. A plain loop can differ in the last bit: the Cover of Darkness's paint summed to 0.9999999999999999 instead
-- of 1.0, which put its 0.35 lining above ACCENT_MAX_SHARE (2026-10-07).
function Colour.pysum(a, n)
    if n == 0 then return 0 end
    local f, c = a[1], 0
    for i = 2, n do
        local x = a[i]
        local t = f + x
        if math.abs(f) >= math.abs(x) then c = c + ((f - t) + x) else c = c + ((x - t) + f) end
        f = t
    end
    if c ~= 0 and c - c == 0 then f = f + c end -- c - c is 0 only when c is finite
    return f
end

-- A group's perceived color: its rows' perceived linear colors, mean by screen pixels (by texture area when none
-- shows; each row alike when neither does: rows 0 of no coverage, src/kits.lua add_rows), summed in row order
-- (match12.group_look).
-- A group's perceived color (src/matcher.lua): its rows' perceived linear colors, mean by screen pixels (by texture
-- area when none shows; each row alike when neither does: rows 0 of no coverage, src/kits.lua add_rows), summed in row
-- order (match12.group_look).
function Colour.weight_field(rows)
    local pixels, texels = 0, 0
    for _, row in ipairs(rows) do pixels, texels = pixels + row.area, texels + row.tex_area end
    if pixels > 0 then return 'area' end
    return texels > 0 and 'tex_area' or nil
end
function Colour.group_look(rows)
    local field = Colour.weight_field(rows)
    local r, g, b, weight = 0, 0, 0, 0
    for _, row in ipairs(rows) do
        local w = field and row[field] or 1.0
        r, g, b, weight = r + w * row.lin[1], g + w * row.lin[2], b + w * row.lin[3], weight + w
    end
    weight = math.max(weight, 1e-12)
    return Colour.linear_to_lab(math.max(r / weight, 0), math.max(g / weight, 0), math.max(b / weight, 0))
end

-- Paint as seen, its highlights apart, as the eye takes them (src/matcher.lua map_group; research/match12.py
-- diffuse_colors): a target row aims at the source's look less its gloss, keeps its own offset from its group as
-- diffuse colors, and shows its own gloss over it. A look counts a glossy paint's highlights as color: the AF-50 Noxious Ranger's glossy olive mask (paint L 43.6
-- chroma 11, gloss floor 0.10) looks L 44.8 chroma 6, and the SC-30 Trailblazer Scout's matte coat fitted to that look
-- turned a pale grey (user 2026-10-10: "The armor was much lighter tint than the helmet's green"); a white glossy B-01
-- Tactical helmet fitted to the CM-14 Physician's matte grey look got paint L 15 under its own highlights and read
-- black ("some helmets' gray is rendering as slightly darker than their respective armors"). On the game's one-helmet
-- one-armor sets the plans come nearer their own colors (median dE helmets from paint 4.35 -> 3.35, armors from paint
-- 5.55 -> 5.01, helmets from metal 4.65 -> 4.55; armors from metal 6.07 -> 6.45).
-- A measured row's diffuse color (its response's g x its mean albedo; a cape's borrowed response has no look of its
-- own: its look is its model color), or nil.
function Colour.row_diffuse(row)
    local c = row.cal
    if c and row.lin then return c[1] * row.ar, c[2] * row.ag, c[3] * row.ab end
end

-- A source group's look its goals aim at: a cape source's (src/matcher.lua borrow_rows: gL, ga, gb), else its look.
local function goal_look(g) return g.gL or g.L, g.ga or g.a, g.gb or g.b end

-- The source group's diffuse color and target group t's (Lab, for map_group): each look less its rows' gloss, weighed
-- as group_look weighs them; a look as it is where none of its rows shows gloss.
function Colour.diffuse_colors(t, src)
    local field = Colour.weight_field(src.rows)
    local fr, fg, fb, weight = 0, 0, 0, 0
    for _, row in ipairs(src.rows) do
        local w, r, g, b = field and row[field] or 1.0, Colour.row_diffuse(row)
        if r then fr, fg, fb = fr + w * (row.lin[1] - r), fg + w * (row.lin[2] - g), fb + w * (row.lin[3] - b) end
        weight = weight + w
    end
    local sL, sa, sb = goal_look(src)
    if fr ~= 0 or fg ~= 0 or fb ~= 0 then
        local r, g, b = Colour.lab_to_linear(sL, sa, sb)
        weight = math.max(weight, 1e-12)
        sL, sa, sb = Colour.linear_to_lab(math.max(r - fr / weight, 0), math.max(g - fg / weight, 0), math.max(b - fb / weight, 0))
    end
    field = Colour.weight_field(t.rows)
    local tr, tg, tb, any = 0, 0, 0, false
    weight = 0
    for _, row in ipairs(t.rows) do
        local w, r, g, b = field and row[field] or 1.0, Colour.row_diffuse(row)
        if r then any = true elseif row.lin then r, g, b = row.lin[1], row.lin[2], row.lin[3] else r, g, b = 0, 0, 0 end
        tr, tg, tb, weight = tr + w * r, tg + w * g, tb + w * b, weight + w
    end
    if not any then return sL, sa, sb, t.L, t.a, t.b end
    weight = math.max(weight, 1e-12)
    local tL, ta, tb2 = Colour.linear_to_lab(math.max(tr / weight, 0), math.max(tg / weight, 0), math.max(tb / weight, 0))
    return sL, sa, sb, tL, ta, tb2, true
end

-- A diffuse color (Lab) with row c's gloss floor over it, weighed as Colour.seen weighs it on hard paint. A neutral
-- diffuse color (chroma under GLOSS_TINT_C: src/matcher.lua NEUTRAL_TINT_C) takes at most that much of the floor's
-- tint: the FS-05 Marksman's red dome, its floor a strong cyan (R 0.002, G and B 0.05), aimed at L 27 a -14.5 b -4.4
-- for the pure black cape Honored Heirloom and was painted teal (independent review 2026-10-11, fresh gallery case
-- 103); a slight cast stays in the goal (the B-24 Enforcer's coat cancels its warm floor through it, chroma 3.9).
Colour.GLOSS_TINT_C = 5.0
function Colour.with_gloss(L, a, b, c)
    local neutral = math.sqrt(a * a + b * b) < Colour.GLOSS_TINT_C
    local w = math.min(math.max(1 - math.sqrt(a * a + b * b) / Colour.GLOSS_C, 0), 1)
    local r, g, bl = Colour.lab_to_linear(L, a, b)
    local gL, ga, gb = Colour.linear_to_lab(math.max(r + w * c[4], 0), math.max(g + w * c[5], 0),
                                            math.max(bl + w * c[6], 0))
    local gc = math.sqrt(ga * ga + gb * gb)
    if neutral and gc > Colour.GLOSS_TINT_C then
        ga, gb = ga * (Colour.GLOSS_TINT_C / gc), gb * (Colour.GLOSS_TINT_C / gc)
    end
    return gL, ga, gb
end

-- A cape's colors (src/matcher.lua identity_of; pool: largest first) with the outside first: when its largest color
-- shows mostly on its lining (under half its area on the outside: src/capes.lua source_rows, row.outside), by their
-- area on the outside, most first, then by share; else as they are. Its lining (row 4, weighed 7 to the outside's 13)
-- outweighed the outside on some capes and the armor took it, a grey under the black Vision of Freedom, a tan under the
-- charcoal Standard of Safe Distance (independent review 2026-10-11; the user chose "outside first"); a largest color
-- mostly outside stays (da9ebb65's navy, 59% outside: by outside area alone its red, a little larger there, took the
-- helmet and the plates and the navy left the outfit, round 30).
function Colour.outside_first(pool)
    local area, outside, sorted = {}, {}, {}
    for i, g in ipairs(pool) do
        area[g], outside[g], sorted[i] = 0, 0, g
        for _, row in ipairs(g.rows) do area[g], outside[g] = area[g] + row.area, outside[g] + (row.outside or 0) end
    end
    local top = pool[1]
    if not top or outside[top] >= 0.5 * area[top] then return pool end
    table.sort(sorted, function(x, y) return outside[x] > outside[y] or (outside[x] == outside[y] and x.share > y.share) end)
    return sorted
end

-- Whether every color of palette s besides s[j_main] that is a main color (share min_share or more) is vivid (model
-- chroma vivid_c or more): a cape of one color and vivid ones (src/matcher.lua guard_part, two-tone).
function Colour.two_tone(s, j_main, min_share, vivid_c)
    for j = 1, #s do
        if j ~= j_main and s[j].share >= min_share and math.sqrt(s[j].ma ^ 2 + s[j].mb ^ 2) < vivid_c then return false end
    end
    return true
end

-- The group of `list` nearest to g by lightness (the first of equal gaps; src/matcher.lua).
function Colour.nearest_lightness(list, g)
    local pick, gap = nil, math.huge
    for _, n in ipairs(list) do
        local d = math.abs(n.L - g.L)
        if d < gap then pick, gap = n, d end
    end
    return pick
end

-- A cape of no dark neutral (src/matcher.lua structure_pairs): each structure group of `groups` (undersuit cloth) takes
-- the nearest by lightness of the palette's main colors (share lim.main or more) the cape's part guard allows it
-- (src/capes.lua dark_parts_guard: no light color on a dark part, no tinted lining color on a large one), appended to
-- pairs ({group, color}) and counted in used ({[color] = share}); with none it keeps its colors. The IE-3 Martyr's olive
-- and brown undersuit stayed as they were under Federation's Embrace's blue and gold (independent review 2026-10-11,
-- fresh gallery case 80; the user chose "undersuits"); by lightness alone the Drape of Glory's 7% red took an undersuit
-- over its 28% blue-grey, and 2bcc4463's taupe lining or cream an undersuit its review passed.
function Colour.cape_structure(groups, palette, guard, lim, pairs, used)
    local allowed, keep = {}, {}
    for i, g in ipairs(groups) do
        allowed[i], keep[i] = {}, {}
        for j, p in ipairs(palette) do -- every color first: a guard's fallback then gives none it blocked
            allowed[i][j], keep[i][j] = true, Colour.de2000(g.L, g.a, g.b, p.L, p.a, p.b) < lim.keep
        end
    end
    guard(allowed, groups, palette, keep, lim.accent_c)
    for i, g in ipairs(groups) do
        local list = {}
        for j, p in ipairs(palette) do if allowed[i][j] and p.share >= lim.main then list[#list + 1] = p end end
        local n = Colour.nearest_lightness(list, g)
        if n then pairs[#pairs + 1], used[n] = {g, n}, (used[n] or 0) + g.share end
    end
end

-- Whether group g shows mostly on a cape's outside (half its rows' area or more, as outside_first counts it).
local function mostly_outside(g)
    local area, outside = 0, 0
    for _, row in ipairs(g.rows) do area, outside = area + row.area, outside + (row.outside or 0) end
    return outside >= 0.5 * area
end

-- A cape's second main color: the largest of palette s besides s[j_main] with share lim.second or more, CIEDE2000
-- lim.keep or more from s[j_main] and mostly on the outside, or nil. A lining color stays out (outside first): Vision
-- of Freedom's grey lining (49%) took main parts of armors its black outside makes dark (case 57).
local function second_main(s, j_main, lim)
    local j2
    for j = 1, #s do
        local apart = Colour.de2000(s[j].L, s[j].a, s[j].b, s[j_main].L, s[j_main].a, s[j_main].b) >= lim.keep
        if j ~= j_main and apart and s[j].share >= lim.second and mostly_outside(s[j])
            and (j2 == nil or s[j].share > s[j2].share) then
            j2 = j
        end
    end
    return j2
end

-- A cape's second main color (second_main; lim: src/matcher.lua CAPE_LIMITS) shows on a main part of the target (share
-- lim.main or more): when the pairing search gave it none (assign[i]: the palette color of target group i), the
-- largest near-neutral one that may take it (model chroma under lim.own_c, c.allowed, not the anchor) does. c: the
-- search's {t, s, allowed}. The search keeps the target's light and dark order, so a light color went to specks only on
-- an all-dark item: the BP-32 Jackboot under 1264718e's yellow (37%) stayed all black (independent review 2026-10-11,
-- fresh gallery case 36; the user chose "cape's light color"). A colored part takes the cape's accent as a band
-- (src/matcher.lua tint_bands): Standard of Safe Distance's yellow on an armor's navy plates, which the sage took.
function Colour.cape_second(c, assign, anchor, j_main, lim)
    local t, j2, pick = c.t, second_main(c.s, j_main, lim), nil
    for i = 1, j2 and #t or 0 do
        local main = t[i].share >= lim.main
        if main and assign[i] == j2 then return end
        local muted = math.sqrt(t[i].ma ^ 2 + t[i].mb ^ 2) < lim.own_c
        if main and muted and i ~= anchor and c.allowed[i][j2] and (pick == nil or t[i].share > t[pick].share) then
            pick = i
        end
    end
    if pick then assign[pick] = j2 end
end

Colour.SAMPLES = SAMPLES
-- Code that runs once or rarely (jobs, startup, events) stays interpreted, sub-functions included: it must not
-- add traces to the LuaJIT code cache the game and every mod share. Only the hot loops stay compiled.
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({mean_hue, Colour.de2000, Colour.srgb_to_lab, lab_finv, linear_to_srgb, Colour.lab_to_linear,
        Colour.lab_to_srgb, Colour.npsum, Colour.pysum, Colour.weight_field, Colour.group_look, Colour.row_diffuse,
        goal_look, Colour.diffuse_colors, Colour.with_gloss, Colour.outside_first, Colour.two_tone, mostly_outside, second_main,
        Colour.cape_second, Colour.nearest_lightness, Colour.cape_structure}) do
        jit.off(fn, true)
    end
end

return Colour
end)()
local Transfer = (function()
-- Match Your Colors: the color transfer of matcher v11.1 (research/match11.py recolor_row): a target LUT row takes
-- a desired perceived color and keeps its own material.
--
-- Only colors change: the base color (column 0), the detail and wear colors (2, 5, 6) and, on camo rows, the camo
-- colors (16-19). They follow the row's paint (the CIELAB of its mean albedo) to a new paint color:
--   * tint: on a saturated paint, the colors of its hue family rotate with its hue and scale with its chroma;
--   * shade: on a saturated paint, the neutral colors near it shift their lightness and stay neutral;
--   * shift: on a neutral paint, the colors near it take its CIELAB change;
--   * tone: toward a neutral target, every following color takes the target's tone;
--   * flat: an accent band's row (goal.band: the accent's paint, src/matcher.lua) is one coat of it, every following
--     color the new paint color (apply); so is a row Match Materials turns into metal (goal.coat: the metal's paint,
--     its finish already the metal's, src/recolor.lua apply_finish), without the paint floors;
--   * the rest stay (bare metal, dirt, painted details of another hue), except under a flat role color (a paint
--     scheme's material roles: all_rule), where every colored color takes the target's hue ('hue'; 'own' off a
--     neutral paint: its own lightness).
-- The new paint color is fitted in at most FIT_STEPS steps so the row's perceived color (src/colour.lua) reaches
-- the desired one (toward a neutral target only its lightness is fitted); the best step is kept. Mode, detail
-- layer and controls, metallic, specular, roughness, camo controls, tiling and every w channel stay the target's.
-- (v1.0 copied whole rows, material included; v11.0 moved every color by one CIELAB offset, which turned a neutral
-- detail color teal when a red paint went neutral.) Nothing here runs per frame.
local Transfer = {}

Transfer.CLOSE_DE = 20.0
Transfer.FIT_STEPS = 8
Transfer.FIT_DONE = 0.5
Transfer.TINT_C = 8.0          -- a paint at least this saturated is re-tinted by hue rotation and chroma scaling
Transfer.TINT_HUE = 60.0       -- degrees: colors of the paint's hue family follow its tint
Transfer.NEUTRAL_C = 8.0       -- colors below this chroma (and half the paint's) are neutral
Transfer.CHROMA_HEADROOM = 10.0 -- the fitted paint's chroma stays within 1.5 x the desired chroma + this
-- Color columns: base, detail, wear (2), camo (4); index into row_values = column * 4 + channel + 1.
local COLUMNS = {0, 2, 5, 6, 16, 17, 18, 19}
local CAMO_FIRST = 5 -- COLUMNS index of column 16
local sqrt, atan2, deg, cos, sin = math.sqrt, math.atan2, math.deg, math.cos, math.sin

local function chroma(a, b) return sqrt(a * a + b * b) end

-- The angle between two hues in degrees (0-180).
local function hue_gap(a1, b1, a2, b2)
    local d = math.abs(deg(atan2(b1, a1) - atan2(b2, a2))) % 360.0
    return d > 180.0 and 360.0 - d or d
end

-- The rule of one color (lab = {L, a, b}) for paint P: 'tint', 'hue' (a camo color of another hue), 'shade',
-- 'shift' or nil (it stays).
local function rule_of(i, lab, P, chromatic, neutral_below, de2000)
    local near = i >= CAMO_FIRST or de2000(lab[1], lab[2], lab[3], P[1], P[2], P[3]) < Transfer.CLOSE_DE
    local neutral = chroma(lab[2], lab[3]) < neutral_below
    if chromatic and not neutral then
        if hue_gap(lab[2], lab[3], P[2], P[3]) <= Transfer.TINT_HUE then return 'tint' end
        -- a camo color of another hue takes the new hue (a rigid turn sent the TG-8 Sharpshooter's brown camo, 55
        -- degrees, to purple when its olive turned the UF-50 Bloodhound's maroon; user 2026-10-07)
        return i >= CAMO_FIRST and 'hue' or nil
    end
    if not near then return nil end
    if neutral and chromatic then return 'shade' end
    return 'shift'
end

-- Camo colors (COLUMNS CAMO_FIRST to count) take the target's hue (their chroma scaled with the paint's; on a neutral
-- paint the target's tone), their lightness offsets kept: shades of the new color. Turned rigidly or shifted, a green
-- camo became lime and lavender with a yellow-green cape and cyan and lilac with the SEAF blue (image review
-- 2026-10-09; research match11.py CAMO_FAMILY). Under a flat role color (all) they are shades at CAMO_FLAT of their
-- lightness offsets in the target's color ('camo'), and so is the camo row's base, which shows between them (a neutral
-- base scaled by chroma stayed grey): SEAF plates are plain, and the
-- SA-12 Twigsnapper's plates kept their light grey base (0.77) as white splashes on blue (independent image reviews
-- 2026-10-09, rounds 8 and 9).
Transfer.CAMO_FLAT = 0.25
local function camo_rules(rules, count, chromatic, all)
    for i = CAMO_FIRST, count do rules[i] = all and 'camo' or chromatic and 'hue' or 'tone' end
    if all and count >= CAMO_FIRST then rules[1] = 'camo' end
end

-- A flat role color (goal.all: a paint scheme's material roles, src/schemes.lua): every colored color of the row
-- follows the goal's hue, none stays and none turns rigidly ('tint' of a color off the paint's hue sent the PH-9
-- Predator's olive wear to magenta under the SEAF blue; kept detail and wear colors left rust flecks and brown straps,
-- image review 2026-10-09). The base keeps its rule; a neutral color stays as it would.
local function all_rule(i, rule, lab, chromatic, neutral_below)
    if i == 1 or chroma(lab[2], lab[3]) < neutral_below then return rule end
    if rule == 'tint' or rule == 'hue' or not rule then return chromatic and 'hue' or 'own' end
    return rule
end

-- The rule of COLUMNS index i (lab: its CIELAB) for paint P; ctx: {chromatic, neutral_below, de2000, all}.
local function column_rule(i, lab, P, ctx)
    local rule = rule_of(i, lab, P, ctx.chromatic, ctx.neutral_below, ctx.de2000)
    if not rule and ctx.darken and chroma(lab[2], lab[3]) < ctx.neutral_below then
        rule = ctx.chromatic and 'shade' or 'shift'
    end
    if i == 1 and not rule then rule = ctx.chromatic and 'tint' or 'shift' end -- the base always follows its paint
    if ctx.all then rule = all_rule(i, rule, lab, ctx.chromatic, ctx.neutral_below) end
    return rule
end

-- A paint that darkens by DARKEN_FOLLOW_L or more (the desired L under the paint's albedo L by that much) takes its
-- neutral detail and wear colors along ('shift', or the target's tone), not only those near it: a cream helmet shell
-- matched to a black armor kept its grey detail color (L 45) while the fit drove its base to black (the IX-VOIDWALKER
-- on the B-01 Tactical; independent image review 2026-10-09; research/match11.py DARKEN_FOLLOW_L).
Transfer.DARKEN_FOLLOW_L = 30.0

-- A light glossy paint turned dark takes the finish of the dark paint it matches (dark_finish): a hard paint row (not
-- cloth, not metal) whose paint darkens by DARKEN_FOLLOW_L or more to a desired L under DARK_L takes the roughness
-- (column 10 x) of its pair's source row when that row is a hard paint too and rougher. The game finishes its dark
-- paints matte (hard rows of at least 0.15 of an item: roughness median 0.67 under L 25, 0.20 over L 50; the B-01
-- Tactical's black 0.70), and a white enamel shell turned black kept its gloss (0.20): its scuffed roughness texture
-- then reflects the light as a grey-white marbled grime (the IX-VOIDWALKER on the B-01; independent image reviews
-- 2026-10-09, rounds 12 to 15). No color removes it (black wear, detail, sheen: no change in the game); the shell at
-- roughness 0.6 showed none (research/scratch/dark-band/live_row_variants.py). 3,102 of 42,660 plans have such a row
-- (8,423 rows; dark_rough_scan.lua). Flat role colors (paint schemes) keep their finish. Such a row is fitted through
-- its response's gain without its gloss floor, at the goal less that gloss (Transfer.diffuse_goal): the floor was
-- taken at the row's own gloss, whose reflections alone showed a black shell at about L 32 (the IX-VOIDWALKER's floor
-- 0.072), so the fit drove its color to black and, matte, it read pitch black (user 2026-10-09: the CW-36 Winter
-- Warrior and CM-21 Trench Paramedic helmets on the B-01 Tactical "way too dark relative to the armor"). Through the
-- model instead (2026-10-09 to 10) the paint took the diffuse color itself, darker than its source's paint by the
-- source's gain: a white glossy B-01 Tactical helmet got L 28 for the CM-14 Physician's grey plates' L 37.
Transfer.DARK_L = 30.0

-- A row whose fit through its measured response misses the goal by RESPONSE_MISS (CIEDE2000) or more is fitted through
-- the model instead (apply): the response was measured at the row's own colors, and a goal it cannot reach lies where it
-- no longer holds. The I-44 Salamander's bare-metal plates (response 0.19) under the Light of Eternal Liberty cape's
-- yellow went to a base of L 98 at chroma 43 (misses of 12 to 16) and read a pale cream beside the cape (gallery
-- 2026-10-10; on screen chroma 35 against 60); through the model they take L 72 to 82 at chroma 51, the cape's hue.
-- Live variants (research/scratch/dark-band/live_cape13_variants.py) of such a saturated yellow read as the cape
-- (dE 9 against 27). 49 of the 1,697 sampled rows fitted through a response (tests/fixtures/transfers.lua) miss by 6
-- or more; under the model 0 of 177 do.
Transfer.RESPONSE_MISS = 6.0

-- A fit through the response toward a colored goal (chroma NEUTRAL_GOAL_C or more) under the response's floor (the look
-- of black paint through it, its gloss and sheen, lighter than the goal) whose paint (of chroma NEUTRAL_GOAL_C or more:
-- a black paint's hue is noise) turns FLOOR_TURN degrees or more from the goal's hue is done again through the model
-- too (apply, refit): the response reaches such a goal only by cancelling
-- its floor's cast, with a paint of another hue, and the detail colors that follow the paint show that hue. The UF-16
-- Inspector's red sleeve under cape 92762946's navy (goal L 17.4 a -3.8 b -10.4, floor L 19.2) took a near-black paint
-- of hue 296 (L 0.8 a 4.2 b -8.6) and read purple beside the navy gloves (gallery 2026-10-11, case 33); through the model
-- it read the gloves' navy (paint L 10 a 0.7 b -12.5), and at the goal itself, its sheen kept, a lighter teal
-- (research/scratch/dark-band/live_under_floor_variants.py). 33 of the 7,157 under-floor (row, goal) pairs of every
-- helmet, armor and cape match are refitted so (research/scratch/dark-band/gate_scan.lua).
Transfer.FLOOR_TURN = 30.0

-- The goal a fit through the model aims at (apply: the dark finish, a missed response): the plan's goal less the gloss
-- the row's measured response shows at it, weighed as Colour.seen weighs it on hard paint, else the goal. The plan's
-- goal counts the target's own highlights (src/matcher.lua floor_goal); through the model they would turn into paint.
-- An accent band's goal is a paint already (goal.band).
function Transfer.diffuse_goal(Colour, goal)
    local cal = goal.cal
    if not cal or goal.band or goal.coat then return goal.L, goal.a, goal.b end
    local w = math.min(math.max(1 - chroma(goal.a, goal.b) / Colour.GLOSS_C, 0), 1)
    local r, g, b = Colour.lab_to_linear(goal.L, goal.a, goal.b)
    return Colour.linear_to_lab(math.max(r - w * cal[4], 0), math.max(g - w * cal[5], 0), math.max(b - w * cal[6], 0))
end
local ROUGHNESS, METALLIC = 40, 27 -- offsets in a row's values: column 10 x, column 6 w

-- Whether the row at offset o of v is cloth or metal (src/colour.lua: cloth is mode 1 with column 8 x near 0). A
-- row_values table is v with o = 1.
local function not_paint(v, o)
    return (math.abs(v[o + 3] - 1) < 0.5 and math.abs(v[o + 32]) < 0.05) or v[o + METALLIC] > 0.5
end

-- A cape's cloth as the source (Helmet and Armor Match Cape: source.cloth, src/recolor.lua source_item) has no paint
-- finish to take: a light hard paint it turns dark takes DARK_ROUGH, the game's median dark paint's roughness, when
-- rougher than its own. Glossy light parts under a black cape kept their shine and read grey (user report 2026-10-14).
Transfer.DARK_ROUGH = 0.67
local function cloth_dark_finish(c, paint_L, dL)
    if not_paint(c, 1) or c[1 + ROUGHNESS] >= Transfer.DARK_ROUGH then return nil end
    if paint_L(c) - dL < Transfer.DARKEN_FOLLOW_L then return nil end
    return Transfer.DARK_ROUGH
end

-- The roughness row c (row_values) takes when fitted to goal (the dark finish above), or nil. source: the source
-- analysis (its luts) the goal's source row is in, or nil; paint_L(c): the lightness of c's paint (its mean albedo),
-- asked only of a candidate; dL: the goal's lightness less the row's own gloss (Transfer.diffuse_goal).
local function dark_finish(c, goal, source, paint_L, dL)
    if goal.kind ~= 'pair' or not (source and goal.source) or dL >= Transfer.DARK_L then return nil end
    if source.cloth then return cloth_dark_finish(c, paint_L, dL) end
    if goal.all then return nil end
    local lut, r = goal.source:match('^(%x+):(%d+)$')
    local spec = lut and source.luts[lut]
    if not spec or spec.width <= 10 then return nil end -- a cape's tint LUT has no finish columns
    local v, s = spec.values, tonumber(r) * spec.width * 4
    if not_paint(c, 1) or not_paint(v, s) or v[s + ROUGHNESS] <= c[1 + ROUGHNESS] then return nil end
    if paint_L(c) - dL < Transfer.DARKEN_FOLLOW_L then return nil end
    return v[s + ROUGHNESS]
end

-- rules (rules_of) toward the desired color D: a coat's every following color takes the paint ('flat'), a neutral
-- target's its tone.
local function whole_rules(rules, D, coat)
    if coat then
        for i in pairs(rules) do rules[i] = 'flat' end
    elseif chroma(D[2], D[3]) < Transfer.TINT_C then -- a neutral target: every following color takes its tone
        for i, rule in pairs(rules) do rules[i] = (rule == 'own' or rule == 'camo') and rule or 'tone' end
    end
    return rules
end

-- {COLUMNS index -> rule} for row c (row_values) with paint P and the desired color D; labs[i] gets each
-- following color's CIELAB. flat: true (a flat role color: all_rule) or 'coat' (an accent band: every following color
-- takes the paint, 'flat').
local function rules_of(c, P, D, labs, de2000, srgb_to_lab, flat)
    local all = flat == true
    local paint_c = chroma(P[2], P[3])
    local chromatic = paint_c >= Transfer.TINT_C
    local ctx = {chromatic = chromatic, de2000 = de2000, all = all,
                 neutral_below = chromatic and math.min(Transfer.NEUTRAL_C, 0.5 * paint_c) or Transfer.NEUTRAL_C,
                 darken = P[1] - D[1] >= Transfer.DARKEN_FOLLOW_L}
    local rules, count = {}, c[88] >= 0 and #COLUMNS or CAMO_FIRST - 1
    for i = 1, count do
        local o = COLUMNS[i] * 4
        local lab = {srgb_to_lab(c[o + 1], c[o + 2], c[o + 3])}
        local rule = column_rule(i, lab, P, ctx)
        if rule then rules[i], labs[i] = rule, lab end
    end
    camo_rules(rules, count, chromatic, all)
    return whole_rules(rules, D, flat == 'coat' or flat == 'metal')
end

-- A color's new CIELAB when the paint goes from P to T.
local function follow(lab, rule, P, T)
    if rule == 'shift' then return lab[1] + (T[1] - P[1]), lab[2] + (T[2] - P[2]), lab[3] + (T[3] - P[3]) end
    local L = lab[1] + (T[1] - P[1])
    if rule == 'tone' then return L, T[2], T[3] end
    if rule == 'flat' then return T[1], T[2], T[3] end
    if rule == 'tint' then
        local scale = chroma(T[2], T[3]) / chroma(P[2], P[3])
        local turn = atan2(T[3], T[2]) - atan2(P[3], P[2])
        local cc, h = chroma(lab[2], lab[3]) * scale, atan2(lab[3], lab[2]) + turn
        return L, cc * cos(h), cc * sin(h)
    end
    if rule == 'hue' then -- the target's hue, its own chroma scaled with the paint's
        local cc, h = chroma(lab[2], lab[3]) * chroma(T[2], T[3]) / chroma(P[2], P[3]), atan2(T[3], T[2])
        return L, cc * cos(h), cc * sin(h)
    end
    if rule == 'own' then -- off a neutral paint: its own lightness, the target's hue at no more than its own chroma
        local tc = chroma(T[2], T[3])
        local k = tc > 0 and math.min(1, chroma(lab[2], lab[3]) / tc) or 0
        return lab[1], T[2] * k, T[3] * k
    end
    if rule == 'camo' then -- a flat camo color: the target's color, CAMO_FLAT of its lightness offset
        return T[1] + Transfer.CAMO_FLAT * (lab[1] - P[1]), T[2], T[3]
    end
    return L, lab[2], lab[3] -- shade
end

-- A cloth row's sheen color (column 12 RGB of a soft row: the SEAF uniform's is a neutral 0.15, the DS-191 Scorpion's
-- vest a brown 0.148 0.098 0.062 at 0.76) under a flat role color fitted without a response: the goal's hue at its own
-- lightness and no more than its own chroma, as 'own'. The model leaves the sheen out, so a fit to it keeps a brown
-- sheen on a black albedo: the Scorpion's vest, scarf and straps read brown as SEAF gear (round 8 renders, 2026-10-09).
-- A fit through a measured response already counts the row's sheen in it. c: row_values, written in place.
local SHEEN = 12
local function flat_sheen(c, a, b, srgb_to_lab, lab_to_srgb)
    if math.abs(c[4] - 1) >= 0.5 then return end
    local o = SHEEN * 4
    local lab = {srgb_to_lab(c[o + 1], c[o + 2], c[o + 3])}
    c[o + 1], c[o + 2], c[o + 3] = lab_to_srgb(follow(lab, 'own', lab, {lab[1], a, b}))
end

-- T with its chroma at most 1.5 x the desired chroma + CHROMA_HEADROOM (no runaway compensation for colors
-- that stay); on bare metal (metallic > 0.5) at most the desired chroma. A metal's reflections take its paint's color
-- at full strength, so the eye reads the paint's chroma where its mean look is diluted by its dark parts: the CPR-80
-- Bulwark from the DP-8 Mountain-Scaled's dull navy (look chroma 9) got a paint of chroma 17 and turned deep blue on
-- screen (user 2026-10-06).
-- A goal of little color (under TINT_C) caps it the same way: its tint is fitted (Transfer.NEUTRAL_GOAL_C), never more
-- color than it asks (the B-24 Enforcer's leather from the GS-66 Lawmaker's silver, chroma 5.3, turned navy-purple).
local function cap_chroma(T, D, metal)
    local dc = chroma(D[2], D[3])
    local limit = (metal or dc < Transfer.TINT_C) and dc or dc * 1.5 + Transfer.CHROMA_HEADROOM
    local cc = chroma(T[2], T[3])
    if cc > limit then T[2], T[3] = T[2] * (limit / cc), T[3] * (limit / cc) end
    return T
end

-- Transfer.new(Colour, colour model, yield) -> {fit, fit_base, apply}. fit(c, L, a, b, cal, base_only, flat): c
-- (row_values) gets the fitted colors; returns the perceived color reached and its CIEDE2000 error. cal: the row's
-- measured response (matcher v12, src/appearance.lua): the fit then reaches the color the row shows in the game, else
-- the model color.
-- base_only: only the base color (column 0) moves (a cape's tint: the shader blends column 0 alone toward it). flat:
-- true, a flat role color (all_rule), or 'coat', every following color the new paint color (an accent band, apply).
-- yield (optional, a job's): called after every perceived-color evaluation (up to FIT_STEPS + 1 per row, each about
-- 0.07 ms outside the game), so a job can pause inside a row.
local function no_pause() end

-- Whether the fit toward goal (a, b) adjusts lightness only: a neutral goal (under NEUTRAL_GOAL_C, the matcher's own
-- neutral: src/matcher.lua NEUTRAL_TINT_C) fitted through the model. A goal of chroma 5 to 8 is a color the matcher
-- kept: at 8 the SC-30 Trailblazer Scout's coat took the AF-50 Noxious Ranger's olive (chroma 7.9) as its paint's tint
-- and its warm response turned it khaki on screen (hue 92 against the mask's 114; user 2026-10-10: "much lighter tint
-- than the helmet's green"); fitted, its paint compensates (hue 122, its look the goal's). A fit through a measured
-- response cancels the row's own cast toward a neutral goal too, its paint no more saturated than the goal
-- (cap_chroma): the B-24 Enforcer's coat (response R 1.08, B 0.87, a warm floor) took the black cape d79370cb's dark
-- as a paint of that dark's tint and read rust brown, L 40 a 6.7 b 10.4, beside its L 26 plates (gallery 2026-10-11);
-- a cape's cloth through its borrowed response already did (Drape of Glory's sheen cloth looked brown, image review
-- 2026-10-07).
Transfer.NEUTRAL_GOAL_C = 5.0
-- A bare-metal row (metallic > 0.5) the fit darkens keeps a paint of at least METAL_PAINT_MIN_L (its own when darker):
-- a darker metal shows its color only in its highlights and reads black. The CPR-80 Bulwark's steel under Red Planet's
-- Memory took paint L 31 for the cape's black: its mean look reached the goal (L 28 on screen against 27) but its median
-- pixel was L 8, "the helmet went pure black" beside the SR-18 Roadblock's grey plates (user 2026-10-11, gallery case 48).
-- The game's own kits paint 95% of their bare metal at L 47 or lighter (1,099 rows; the darkest, the PH-202
-- Twigsnapper's steel, L 34.6: research/scratch/dark-band/metal_paint_survey.lua); the B-22 Model Citizen's chrome
-- guards read as dark chrome at L 44-50 (2026-10-10).
Transfer.METAL_PAINT_MIN_L = 45.0
-- A glossy hard paint (not metal, roughness under GLOSSY_ROUGH) the fit darkens keeps a paint of at least
-- GLOSSY_PAINT_MIN_L, a cloth CLOTH_PAINT_MIN_L (its own when darker): under a goal below its gloss or sheen floor the
-- fit ran the paint to L 0 (a B-01 Tactical cloth row with a sheen under Foesmasher's black, v1.5, and helmets' glossy
-- parts matched to near-black armors), where the game paints 99% of its glossy hard paint at L 19.8 or lighter (1,409
-- rows) and of its cloth at L 12.4 or lighter (2,192 rows; research/scratch/v15/paint_survey.lua, cloth_survey.lua).
-- Its highlights or sheen alone keep it from looking darker. A matte hard paint has no floor (the game's go to L 4.9).
Transfer.GLOSSY_PAINT_MIN_L, Transfer.CLOTH_PAINT_MIN_L, Transfer.GLOSSY_ROUGH = 20.0, 12.0, 0.5
local function paint_floor(paint_L, metal, glossy, cloth)
    if metal then return math.min(paint_L, Transfer.METAL_PAINT_MIN_L) end
    if cloth then return math.min(paint_L, Transfer.CLOTH_PAINT_MIN_L) end
    if glossy then return math.min(paint_L, Transfer.GLOSSY_PAINT_MIN_L) end
    return -math.huge
end

local function neutral_goal(a, b, cal)
    return not cal and chroma(a, b) < Transfer.NEUTRAL_GOAL_C
end

-- The colors of row c (row_values) that rules move: {COLUMNS index -> {r, g, b}}.
local function colors_of(c, rules)
    local out = {}
    for i in pairs(rules) do
        local o = COLUMNS[i] * 4
        out[i] = {c[o + 1], c[o + 2], c[o + 3]}
    end
    return out
end

-- The row's own error against the goal: where a fit starts (a NaN goal is never reached: infinity).
local function own_error(de2000, pL, pa, pb, L, a, b)
    local err = de2000(pL, pa, pb, L, a, b)
    return err == err and err or math.huge
end

function Transfer.new(Colour, model, yield)
    local de2000, srgb_to_lab, lab_to_srgb = Colour.de2000, Colour.srgb_to_lab, Colour.lab_to_srgb
    local pause = yield or no_pause
    local self = {}

    -- The row's colors for paint color T (written into c).
    local function paint_with(c, rules, labs, P, T)
        for i, rule in pairs(rules) do
            local o = COLUMNS[i] * 4
            c[o + 1], c[o + 2], c[o + 3] = lab_to_srgb(follow(labs[i], rule, P, T))
        end
    end

    -- The look the fit reaches for row c: through its measured response cal, else the model. A matte soft row (cloth:
    -- mode 1, column 8 x at 0) counts its whole gloss floor (Colour.seen): the TG-8 Sharpshooter's cloth fitted to the
    -- UF-50 Bloodhound's red at L 22 looked salmon, its look L 29 (rendered check 2026-10-07). Also the same look from
    -- an albedo already computed for c.
    local function look_of(c, cal)
        if not cal then return model.perceived, model.perceived_of end
        local soft = math.abs(c[4] - 1) < 0.5 and math.abs(c[33]) < 0.05
        return function(x) return model.look(x, cal, soft) end,
            function(_, r, g, b) return model.look_of(r, g, b, cal, soft) end
    end

    -- Row c's own albedo r, g, b: c.own ({r, g, b}, set by apply from starts while c is the row as copied) or computed.
    local function own_albedo(c)
        local own = c.own
        if own then return own[1], own[2], own[3] end
        return model.albedo(c)
    end

    -- The lightest paint a fit may darken row c to (paint_floor); a metal coat (Match Materials, v1.5) is the source
    -- metal's own paint: none.
    local function floor_of(c, paint_L, metal, flat)
        if flat == 'metal' then return -math.huge end
        return paint_floor(paint_L, metal, c[1 + ROUGHNESS] < Transfer.GLOSSY_ROUGH, Colour.is_soft(c))
    end

    function self.fit(c, L, a, b, cal, base_only, flat)
        local all = flat == true
        local look, look_from = look_of(c, cal)
        local D = {L, a, b}
        -- the row's albedo, once for its paint's color and its first look (v1.3 computed its 512 samples twice)
        local r, g, bl = own_albedo(c)
        c.own = nil -- painted from here on
        local P = {Colour.linear_to_lab(r, g, bl)}
        local labs = {}
        local rules = rules_of(c, P, D, labs, de2000, srgb_to_lab, flat)
        if base_only then rules = {[1] = rules[1]} end
        local neutral = neutral_goal(a, b, cal)
        local metal = c[28] > 0.5 -- column 6 w: metallic (src/colour.lua)
        local floor = floor_of(c, P[1], metal, flat)
        local pL, pa, pb = look_from(c, r, g, bl)
        pause()
        local T = cap_chroma({math.max(P[1] + (L - pL), floor), P[2] + (a - pa), P[3] + (b - pb)}, D, metal)
        if neutral then T[2], T[3] = a, b end
        -- The row's own colors stand until a step is better: a fit never ends farther from the goal than the row
        -- started (v1.3: 126 of 1,865 sampled rows did, one from dE 0.44 to 2.38). A NaN goal is never reached: the
        -- row stays unchanged.
        local best, best_err, best_L, best_a, best_b = colors_of(c, rules), own_error(de2000, pL, pa, pb, L, a, b),
            pL, pa, pb
        for _ = 1, Transfer.FIT_STEPS do
            paint_with(c, rules, labs, P, T)
            local gL, ga, gb = look(c)
            local err = de2000(gL, ga, gb, L, a, b)
            if err < best_err then
                best_err, best_L, best_a, best_b, best = err, gL, ga, gb, colors_of(c, rules)
            end
            if err < Transfer.FIT_DONE then break end
            if neutral then
                T[1] = math.max(T[1] + (L - gL), floor)
            else
                T = cap_chroma({math.max(T[1] + (L - gL), floor), T[2] + (a - ga), T[3] + (b - gb)}, D, metal)
            end
            pause()
        end
        for i, color in pairs(best) do
            local o = COLUMNS[i] * 4
            c[o + 1], c[o + 2], c[o + 3] = color[1], color[2], color[3]
        end
        if all and not (cal or base_only) then flat_sheen(c, a, b, srgb_to_lab, lab_to_srgb) end
        return best_L, best_a, best_b, best_err
    end

    -- The base color (column 0 RGB) that brings LUT row `row` of values (width columns), with base `tint` ({r, g, b})
    -- instead of its own, to goal ({L, a, b, cal}: a plan's) when only the base moves: a cape's tint (src/capes.lua),
    -- which the shader blends into column 0 alone. Returns R, G, B and the error; values stay as they are.
    function self.fit_base(values, width, row, tint, goal)
        local c = Colour.row_values(values, width, row)
        c[1], c[2], c[3] = tint[1], tint[2], tint[3]
        local _, _, _, err = self.fit(c, goal.L, goal.a, goal.b, goal.cal, true)
        return c[1], c[2], c[3], err
    end

    local function paint_L(c) return (Colour.linear_to_lab(own_albedo(c))) end

    -- Rows' own albedos {r, g, b} per origin (the analysis LUT a row was copied from, Recolor.build_lut) and row, made
    -- from the row's unchanged values c: a plan fits the same target rows for every source it pairs (browsing armors
    -- refits the helmet's), and of a fit's 5.7 albedo evaluations the first is the row's own (2,524 of 2,658 rows
    -- fitted before, research/profiling/fit_census.lua; 2026-10-11). Weak keys: an analysis let go takes them along.
    local starts = setmetatable({}, {__mode = 'k'})
    local function start_of(origin, row, c)
        local rows = starts[origin]
        if not rows then
            rows = {}
            starts[origin] = rows
        end
        local s = rows[row]
        if not s then
            s = {model.albedo(c)}
            rows[row] = s
        end
        return s
    end

    -- Whether row c, fitted through response cal toward (L, a, b) with error err, is fitted again through the model: it
    -- missed by RESPONSE_MISS or more, or its paint (mean albedo) turned off a colored goal under the response's floor
    -- (Transfer.FLOOR_TURN).
    local function refit(c, cal, err, L, a, b)
        if err >= Transfer.RESPONSE_MISS then return true end
        if chroma(a, b) < Transfer.NEUTRAL_GOAL_C or Colour.linear_to_lab(cal[4], cal[5], cal[6]) <= L then return false end
        local _, pa, pb = Colour.linear_to_lab(model.albedo(c))
        return chroma(pa, pb) >= Transfer.NEUTRAL_GOAL_C and hue_gap(pa, pb, a, b) >= Transfer.FLOOR_TURN
    end

    -- Writes the fitted colors of LUT row `row` into values (float array, width columns); returns the error. goal: a
    -- plan's {L, a, b, cal, all (a flat role color: all_rule), band, kind, source}; source (optional): the source
    -- analysis (dark_finish: a light paint turned dark takes its source row's roughness and is fitted through the
    -- model). An accent band's row (goal.band: L, a, b the accent's paint, src/matcher.lua tint_bands) becomes one coat
    -- of that paint, fitted through the model: through its response, measured on its own color, the IX-VOIDWALKER's
    -- band (0.52, on navy) asked a base of L 96 for the B-01 Tactical's yellow and its detail colors followed the hue
    -- turn to lime and light grey; it read a pale butter yellow beside the armor's lemon (user 2026-10-10). Of seven
    -- live variants (research/scratch/dark-band/live_band_variants.py) the armor's paint on every color column matched
    -- it best; its own detail colors read dull and mottled, shades of the paint amber.
    -- A fit through the response that misses its goal by RESPONSE_MISS or more, or turns its paint off a colored goal
    -- under the response's floor (FLOOR_TURN), is done again through the model; a fit through the model aims at the goal
    -- less the row's own gloss (Transfer.diffuse_goal).
    -- What row c is fitted through and toward: cal, L, a, b. Through its response at the goal, else through the model
    -- at the goal less its gloss (dL, da, db); a row dark_finish made rough (a matte paint now) through its gain
    -- without its gloss floor, at the goal less that gloss.
    local function aim(goal, flat, rough, dL, da, db)
        local cal = flat ~= 'coat' and flat ~= 'metal' and goal.cal or nil
        if not cal then return nil, dL, da, db end
        if rough then return {cal[1], cal[2], cal[3], 0, 0, 0}, dL, da, db end
        return cal, goal.L, goal.a, goal.b
    end

    -- Row c's fitted colors into values from `base` (its sheen too for a flat role color, and the roughness rough).
    local function write_row(values, base, c, goal, rough)
        for _, column in ipairs(COLUMNS) do
            local o = column * 4
            values[base + o], values[base + o + 1], values[base + o + 2] = c[o + 1], c[o + 2], c[o + 3]
        end
        if goal.all then
            local o = SHEEN * 4
            values[base + o], values[base + o + 1], values[base + o + 2] = c[o + 1], c[o + 2], c[o + 3]
        end
        if rough then values[base + ROUGHNESS] = rough end
    end

    -- origin (optional): the analysis LUT the row's values were copied from, unchanged (Recolor.build_lut): its own
    -- albedo is then kept per origin and row (starts) and given to the fit as c.own.
    function self.apply(values, width, row, goal, source, origin)
        local c = Colour.row_values(values, width, row)
        local start = origin and start_of(origin, row, c)
        c.own = start
        local flat = goal.all or (goal.band and 'coat') or (goal.coat and 'metal') or nil
        local dL, da, db = Transfer.diffuse_goal(Colour, goal)
        local rough = flat ~= 'coat' and flat ~= 'metal' and dark_finish(c, goal, source, paint_L, dL)
        -- no longer the row as copied: its albedo computed (the same today: the albedo reads no roughness)
        if rough then c[1 + ROUGHNESS], c.own = rough, nil end
        local cal, L, a, b = aim(goal, flat, rough, dL, da, db)
        local _, _, _, err = self.fit(c, L, a, b, cal, nil, flat)
        if cal and refit(c, cal, err, L, a, b) then
            c = Colour.row_values(values, width, row)
            c.own = start
            _, _, _, err = self.fit(c, dL, da, db, nil, nil, flat)
        end
        write_row(values, row * width * 4, c, goal, rough)
        return err
    end

    return self
end

Transfer.COLUMNS = COLUMNS
-- Runs inside a job, a few dozen rows per plan: interpreted (the albedo loop it calls stays compiled).
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({chroma, hue_gap, rule_of, camo_rules, all_rule, column_rule, rules_of, not_paint, dark_finish,
                         cloth_dark_finish,
                         follow, flat_sheen, cap_chroma, no_pause, paint_floor, neutral_goal, colors_of, own_error,
                         Transfer.new}) do
        jit.off(fn, true)
    end
end

return Transfer
end)()
local Matcher = (function()
-- Match Your Colors: matcher v12 (research/match12.py), the plan of which color each target LUT row takes.
-- v10's quality was proven on all 21,330 helmet x armor pairs per direction; v11 fixed what the 2026-10-05
-- playtest showed; v12 judges by what the Armory shows (the measured appearance, src/appearance.lua).
--
-- An item is one kit's rows: every LUT row of every piece material. A measured kit (src/appearance.lua: every LUT of
-- its rows measured on the Armory front view) weighs each row by its screen pixels and sees it as it looks there:
-- perceived = s + g x mean albedo per channel (its measured response). Any other kit (new since the measurement, or
-- another body's pieces) weighs rows by ID-mask area (piece weight x coverage / materials of the piece) and sees
-- them as the model color (mean albedo, metal darkened; v11.5). Lens/light rows (mode >= 2.5, and glowing paint:
-- Matcher.light) never change.
-- Rows are grouped by model color (CIEDE2000 < 6, same metal and camo class): one paint stays one design color even
-- where it looks lighter or darker; a group's color is its rows' perceived color, mean by pixels.
-- Classes go by the model color (the design's categories and the thresholds the user's reports validated): dark
-- neutrals mostly from undergarments are structure, they keep their color or take the source's nearest dark neutral;
-- saturated groups are accents. Every color value (identity, matches, lightness relations, offsets, the fit) is
-- perceived.
-- Anchor: a target paint group that already matches the source's identity color keeps it, else the largest paint
-- group of the identity's class (dark neutral or not) takes it, else the largest (an armor's identity color is its
-- most salient paint: undersuit area weighs 0.5 and dark neutrals DARK_SALIENCE, so the CM-09 Bonesnapper's cream
-- plates outweigh its green undersuit and the I-92 Fire Fighter's grey plates its tan padding).
-- The other groups are placed by a local search over the source colors (lightness and saturation relative
-- to the anchor, colors already matched, source proportions, light/dark contrast); a large target area
-- (share >= LARGE_AREA) takes only the source's main colors (share >= MAIN_COLOR) or one it already matches,
-- never a trim. A source's structure color (its undersuit) goes only to a small dark neutral target group or one
-- that already matches it, so no light, colored or large part turns undersuit black. Accents (saturated groups up to
-- ACCENT_MAX_SHARE, not the anchor, or any size below the pairing minimum) take the source's accent color (its most
-- salient visible saturated color, from 0.5% of its paint, among its color groups and its pattern colors), or keep
-- their own when they are dark, already match a source color or the source has none. A target pattern whose color
-- is an accent takes the source's accent the same way (Matcher.pattern_plan).
-- Each recolored row's desired color is its source color plus the row's own offset from its group;
-- src/transfer.lua then fits the row's colors to it (through its measured response when it has one) and keeps its
-- material. An unmeasured bare-metal row taking paint aims PAINT_REFLECTION more linear light in every channel
-- (v11.2: a paint reflects about 4% white light that bare metal does not); a measured row's perceived color already
-- shows how its metal looks.
-- Options (v1.3): Recolor Hoods off (Matcher.item's keep_hoods) groups a hooded helmet's hood rows apart and never
-- recolors them; they still count in the item's paint, so the other parts keep their shares and roles. Match
-- Materials (Matcher.plan's materials) turns a big hard metal part taking paint into that paint (painted).
--
-- Sums follow numpy's order (pairwise above 8 terms) or Python's (sequential) as match12.py, and sorts are stable,
-- so plans equal match12.py's. Nothing here runs per frame.
local Matcher = {}

-- The color functions (Colour.de2000, lab_to_linear, linear_to_lab, srgb_to_lab, srgb_to_linear, seen); set once by
-- Matcher.use before the first item.
local de2000, lab_to_linear, linear_to_lab, srgb_to_lab, srgb_to_linear, seen, npsum, pysum, GLOSS_C
local weight_field, group_look, row_diffuse, diffuse_colors, with_gloss, outside_first, two_tone_of, cape_second
local nearest_lightness, cape_structure
function Matcher.use(colour)
    de2000, lab_to_linear, linear_to_lab = colour.de2000, colour.lab_to_linear, colour.linear_to_lab
    srgb_to_lab, srgb_to_linear, seen = colour.srgb_to_lab, colour.srgb_to_linear, colour.seen
    npsum, pysum, GLOSS_C = colour.npsum, colour.pysum, colour.GLOSS_C -- numpy's and Python's sums (src/colour.lua)
    weight_field, group_look = colour.weight_field, colour.group_look -- a group's look of its rows (src/colour.lua)
    row_diffuse, diffuse_colors, with_gloss = colour.row_diffuse, colour.diffuse_colors, colour.with_gloss
    outside_first, two_tone_of, cape_second = colour.outside_first, colour.two_tone, colour.cape_second -- capes'
    nearest_lightness, cape_structure = colour.nearest_lightness, colour.cape_structure
end

local GROUP_DE, KEEP_DE = 6.0, 8.0
local TGT_MIN_SHARE, PAIR_MIN_SHARE, ANCHOR_MIN_SHARE = 0.02, 0.02, 0.10
-- The weight of dark neutrals in an armor's identity: screen shares (measured) count them as they show; texture
-- shares overcount an armor's many small dark parts (straps, gloves, plate backs; v11.5).
local DARK_SALIENCE, DARK_SALIENCE_TEXTURE = 0.5, 0.25
local UNDER_SALIENCE = 0.5 -- an armor's undersuit area counts half in its identity: its plates define the look
local ACCENT_SMALL, ACCENT_VIVID = 0.10, 35.0 -- a muted accent is small; a larger or dark one must be vivid
local LARGE_AREA, MAIN_COLOR = 0.15, 0.10
local ACCENT_C, ACCENT_MAX_SHARE, ACCENT_MIN_L = 20.0, 0.35, 20.0
local SOURCE_ACCENT_MIN_L, SOURCE_ACCENT_MIN_SHARE = 30.0, 0.005
local SOURCE_ACCENT_MIN_SHARE_MEASURED = 0.001 -- screen share: the SR-64 Cinderblock's orange emblem shows 0.12%
local NEUTRAL_L, NEUTRAL_C = 35.0, 10.0
local LOOK_DARK_L = 30.0 -- a part looks dark below this perceived lightness (a medium grey L 34 is no dark mask)
local SECOND_MAIN_SHARE, LIGHTER_MAIN_L = 0.25, 20.0 -- a source's second main color (anchor_of, vivid_minor_guard)
local TWO_TONE_SHARE = 0.15 -- a cape's vivid color this big is its design when it has no other muted one (two_tone)
local OWN_COLOR_C, BLACK_C, BAND_MAX_SHARE, LIGHT_BAND_L, DARK_PAIR_L = 9.0, 4.0, 0.4, 45.0, 30.0 -- tint_bands
local BAND_ARMOR_MIN_SHARE = 0.10 -- an armor's band takes a source color of this share or more (band_hue_source)
local CAPE_LIMITS = {second = SECOND_MAIN_SHARE, main = MAIN_COLOR, keep = KEEP_DE, accent_c = ACCENT_C, -- capes'
                     own_c = OWN_COLOR_C}
local W_LIGHT, W_CHROMA, W_KEEP, W_PROP, W_FLAT = 1.0, 0.5, 0.15, 1.0, 0.5
local PALETTE_LIMIT = 8
local BIG_SHARE = 0.05
local PAINT_REFLECTION = 0.04 -- linear light a paint shows over a bare metal of the same model color
local PAINT_SHARE = 0.05 -- Match Materials: a metal part from this share of the item's paint (or an accent) takes paint

-- Stable sort by descending `field` (Python's sorted(..., key=lambda x: -x[field])).
local function sort_desc(list, field)
    for i, item in ipairs(list) do item._order = i end
    table.sort(list, function(x, y)
        if x[field] ~= y[field] then return x[field] > y[field] end
        return x._order < y._order
    end)
    return list
end

local function chroma(a, b) return math.sqrt(a * a + b * b) end

local function is_neutral(L, a, b)
    return L < NEUTRAL_L and chroma(a, b) < NEUTRAL_C
end
Matcher.is_neutral = is_neutral

-- Classes go by the model color (mL, ma, mb).
local function neutral(g) return is_neutral(g.mL, g.ma, g.mb) end

-- Whether a group looks a dark neutral (perceived L < LOOK_DARK_L, chroma < NEUTRAL_C): the anchor's class, so a
-- light identity lands on a light part and a dark one on a dark part.
local function looks_dark(g) return g.L < LOOK_DARK_L and chroma(g.a, g.b) < NEUTRAL_C end

local function is_structure(g)
    return neutral(g) and g.under >= 0.5 * g.area
end

-- Whether an armor's undersuit black is its paint: no group outside it reaches LARGE_AREA of what shows (the SC-34
-- Infiltrator, 93% undersuit: its 2% light-grey trims had become its identity and turned helmets white, user
-- 2026-10-06). As a source its undersuit groups then count as paint, for its identity and its pairs.
local function suit_is_paint(groups, limit)
    for _, g in ipairs(groups) do
        if not is_structure(g) and g.share >= limit then return false end
    end
    return true
end

-- Groups of an item's paint rows: greedy by descending area, a row joins the first group of its hood, metal and
-- camo class whose founding model color is within GROUP_DE (row.hood: a hood row kept by Recolor Hoods off).
local function make_groups(paint, paint_area)
    local groups = {}
    for _, row in ipairs(sort_desc({unpack(paint)}, 'area')) do
        local joined = false
        for _, g in ipairs(groups) do
            if g.hood == row.hood and g.metal == row.metal and g.camo == row.camo
                and de2000(g.mL, g.ma, g.mb, row.mL, row.ma, row.mb) < GROUP_DE then
                g.rows[#g.rows + 1] = row
                g.area, g.under = g.area + row.area, g.under + row.under
                joined = true
                break
            end
        end
        if not joined then
            groups[#groups + 1] = {L = row.L, a = row.a, b = row.b, mL = row.mL, ma = row.ma, mb = row.mb,
                                   metal = row.metal, camo = row.camo, hood = row.hood, rows = {row}, area = row.area,
                                   under = row.under, rep = row}
        end
    end
    for _, g in ipairs(groups) do g.share = g.area / paint_area end
    return sort_desc(groups, 'area')
end

-- Whether every LUT of the rows was measured with the kit (else it changed since, or the rows are another body's).
local function measured_kit(rows, kit)
    if not kit then return false end
    for _, row in ipairs(rows) do
        if not kit.luts[row.lut] then return false end
    end
    return true
end

-- Relative luminance of display-linear RGB.
local function luminance(r, g, b) return 0.2126 * r + 0.7152 * g + 0.0722 * b end

-- A row of a mod's LUT that differs from the archived one (row.vanilla, src/kits.lua): its measured light, taken
-- with the archived colors, scaled by how much brighter or darker it looks now (through its response, else the
-- model).
local function light_scale(row, cal)
    local v = row.vanilla
    local now, before
    if cal then
        now, before = luminance(seen(cal, row.ar, row.ag, row.ab)), luminance(seen(cal, v.ar, v.ag, v.ab))
    else
        now, before = luminance(lab_to_linear(row.L, row.a, row.b)), luminance(lab_to_linear(v.L, v.a, v.b))
    end
    return before > 1e-9 and now / before or 1.0
end

-- Measured rows: screen pixels for area (the undersuit part scaled alike), the light they show (pixels x mean
-- screen luminance) and the perceived color of the row's response (row.cal = {gr, gg, gb, sr, sg, sb}; Colour.seen:
-- gloss counts on neutral paint only), else the model color. A mod's LUT row keeps its measured response only while
-- its finish is the archived one (row.finish_changed: its metal, gloss or mode differ; the response was measured
-- with them), and its light follows its new colors (KB match-your-colors-review-transmog-v13).
-- A row's perceived color through its measured response (look.row; row.cal, row.lin, its L, a, b), unless a mod changed
-- its finish (the response was measured with the archived one): then its model color. Returns the response or nil.
local function respond(row, look)
    local cal = not row.finish_changed and look.row(row.lut, row.row) or nil
    if cal then
        row.cal = cal
        row.lin = {seen(cal, row.ar, row.ag, row.ab)}
        row.L, row.a, row.b = linear_to_lab(row.lin[1], row.lin[2], row.lin[3])
    else
        row.lin = {lab_to_linear(row.L, row.a, row.b)}
    end
    return cal
end

-- A row 0 that coverage leaves out (src/kits.lua add_rows) weighs nothing even where the study saw it: counted, the
-- CM-21 Trench Paramedic's chest pouches (4.8% of its view) turned its black undersuit group from structure to paint
-- and its own set's plan asked L 34 for L 21 black; weighing nothing, no other row's plan changes (match12
-- ROW_ZERO_WEIGHS).
local function measure_rows(rows, kit, look)
    for _, row in ipairs(rows) do
        local frac = row.area > 0 and row.under / row.area or 0.0
        local seen_row = row.tex_area > 1e-6 and kit.rows[row.key] or nil
        row.area, row.light = seen_row and seen_row[1] or 0, seen_row and seen_row[2] or 0
        row.under = row.area * frac
        local cal = respond(row, look)
        if row.vanilla then row.light = row.light * light_scale(row, cal) end
    end
end

-- An item without its own measurement: a mod's patch to a piece's unit, material or masks (the kit's measured pixels
-- no longer hold), a kit or record the study did not measure, a LUT the kit was not measured with. What the study knows
-- of each LUT row holds whatever the geometry: its response (respond) and how much of a view it ever showed
-- (look.seen_share: the largest share of any measured kit's pixels). A row of a measured LUT that no kit showed on
-- SEEN_MIN_SHARE of its view, and that no mod changed (row.vanilla, row.finish_changed: src/kits.lua), weighs nothing,
-- as in a measured view: with no share it is no source (accent, pairing, second color) and shapes no proportion, and as
-- a target it still joins a group and takes its color. Texture coverage alone counted such rows in full: a mod's patch
-- to the CE-27 Ground Breaker dropped its measurement, and the pure green of a hidden debug row (2.2% of its texture,
-- never on screen) became its accent and every helmet's stripes (end user 2026-10-08); over all 21,330 helmet plans
-- with the source armor unmeasured, 665 took such a row (158 goals of chroma over 100), none now, and the goals came
-- 17% nearer the measured plans' (CIEDE2000 6.47 -> 5.38). Rows of LUTs the study never measured keep their coverage.
local SEEN_MIN_SHARE = SOURCE_ACCENT_MIN_SHARE_MEASURED -- what a measured view counts as a visible color
local function unmeasured_rows(rows, look)
    for _, row in ipairs(rows) do
        respond(row, look)
        local share = look.seen_share(row.lut, row.row)
        if share and share < SEEN_MIN_SHARE and not row.vanilla and not row.finish_changed then
            row.area, row.under = 0, 0
        end
    end
end

-- The item's patterns: {key, pattern, area, share, L, a, b (perceived), mL, ma, mb (model: texel 0), gain, rep,
-- rows}; measured: the pattern's screen pixels and, when measured, its look (gain x texel color, linear).
local function item_patterns(patterns, kit, paint_area)
    local out = {}
    for _, p in ipairs(patterns or {}) do
        local mL, ma, mb = srgb_to_lab(p.r, p.g, p.b)
        local key = 'pattern:' .. p.pattern
        local entry = {key = key, pattern = p.pattern, area = p.area, L = mL, a = ma, b = mb, mL = mL, ma = ma, mb = mb,
                       texel = {p.r, p.g, p.b}, rep = {key = key}, rows = {}}
        local m = kit and kit.patterns[p.pattern]
        if kit then entry.area = m and m.px or 0 end
        if m and m.gain then
            entry.gain = m.gain
            entry.L, entry.a, entry.b = linear_to_lab(math.max(m.gain[1] * srgb_to_linear(p.r), 0),
                math.max(m.gain[2] * srgb_to_linear(p.g), 0), math.max(m.gain[3] * srgb_to_linear(p.b), 0))
        end
        entry.share = entry.area / paint_area
        out[#out + 1] = entry
    end
    return out
end

-- Whether a row keeps its colors as a lens or light: lenses and lights (mode >= 2.5), and glowing paint (mode 0
-- with an emissive intensity, column 13 x: the game's own light strips, at most 2.7% of a kit, and the glowing
-- visors of LUT mods; v1.3). Cloth rows use column 13 otherwise.
function Matcher.light(row)
    return row.mode >= 2.5 or (row.mode < 0.5 and (row.emissive or 0) > 0)
end

-- An item from rows {key, lut, row, area, under, L, a, b (model), ar, ag, ab (mean linear albedo), metal, camo,
-- mode, full, emissive} in first-seen order; armor: true for an armor kit (identity color by salience); patterns:
-- {{pattern, area, r, g, b (texel 0, sRGB)}, ...} or nil; look: nil or {kit = Appearance kit entry or nil, row =
-- Appearance row function, hoods = the kit's hood rows {['lut:row'] -> true} or nil}; keep_hoods: Recolor Hoods off
-- (the hood rows group apart and take no color).
-- The item's own copies of the analysis rows (the analysis is kept and cached as it is), with the model color and
-- texture area kept as mL, ma, mb, tex_area; hoods: the hood rows to keep, or nil.
local function copy_rows(analysis_rows, hoods)
    local rows = {}
    for i, source in ipairs(analysis_rows) do
        local row = {}
        for k, v in pairs(source) do row[k] = v end
        row.lens = Matcher.light(row)
        row.hood = hoods ~= nil and hoods[row.key] == true
        row.mL, row.ma, row.mb, row.tex_area = row.L, row.a, row.b, row.area
        rows[i] = row
    end
    return rows
end

-- The paint rows (not lens) into item.paint; returns the paint area (a measured kit's pattern pixels included; 1
-- when nothing shows): Python's sum of the rows' areas (pysum; match.py, match12.py), then the pattern pixels.
local function paint_of(item, kit)
    local areas = {}
    for _, row in ipairs(item.rows) do
        if not row.lens then
            item.paint[#item.paint + 1] = row
            areas[#areas + 1] = row.area
        end
    end
    local paint_area = pysum(areas, #areas)
    if item.measured then
        for _, m in pairs(kit.patterns) do paint_area = paint_area + m.px end
    end
    if paint_area == 0 then paint_area = 1.0 end
    return paint_area
end

-- A cape's rows (look.borrow: not measured, the study hid the cape) fit through the response their cloth borrows from
-- measured rows of the same material controls (research/make_appearance.py cape_rows writes it under the cape's LUT
-- rows), a tint row through its material row's (look.tint_of: cape LUT -> material LUT), tint included (a fit through
-- a response cancels the cloth's own tint toward a neutral goal, src/transfer.lua neutral_goal): Drape of Glory's sheen
-- cloth took the B-01 Tactical's dark and looked brown (image review 2026-10-07). Looks stay the model's; a mod's row
-- whose finish changed keeps the model.
-- A cape as the SOURCE (look.seen: Helmet and Armor Match Cape) also gets the look parts aim at (the group's gL, ga,
-- gb: Matcher.item): its colors through those responses. Its identity's look so meets the cape's back on screen (117
-- capes of the 2026-10-11 gallery: a median +0.6 L; research/scratch/v15/cape_shade_fit.py), its model color a median
-- 1.0 L lighter, and the default black capes' black is a look of L 22.7 (on screen 18-23) for a model L 25.3. Aimed at
-- the model color, armors under them were painted L 28-34 and read grey (user report 2026-10-14: "black in the default
-- capes is grey when applied to armour"). Decisions (identity, pairs, guards) keep the model colors: only goals move.
local SEEN_TINT_C = 5.0 -- a model color under this chroma passes no tint (NEUTRAL_TINT_C, map_group)
local function borrow_rows(rows, look)
    for _, row in ipairs(rows) do
        local lut = look.tint_of and look.tint_of[row.lut] or row.lut
        local cal = not row.finish_changed and look.row(lut, row.row) or nil
        if cal then row.cal = {cal[1], cal[2], cal[3], cal[4], cal[5], cal[6]} end
        if look.seen then
            row.lin = cal and {seen(row.cal, row.ar, row.ag, row.ab)} or {lab_to_linear(row.L, row.a, row.b)}
        end
    end
end

-- The rows as the look knows them: a measured kit's pixels and responses, a cape's borrowed responses, or without a
-- measurement of its own what the study knows of each LUT row.
local function look_rows(rows, measured, kit, look)
    if measured then
        measure_rows(rows, kit, look)
    elseif look and look.borrow then
        borrow_rows(rows, look)
    elseif look and look.seen_share then
        unmeasured_rows(rows, look)
    end
end

-- A cape source group's goal look (borrow_rows): a neutral keeps its own hue (a black cloth's sheen gave its look a
-- warm cast, chroma 1.1).
local function seen_look(g)
    g.gL, g.ga, g.gb = group_look(g.rows)
    if chroma(g.ma, g.mb) < SEEN_TINT_C then g.ga, g.gb = g.ma, g.mb end
end
-- The groups' looks: a measured item's perceived colors; a cape source's goal looks.
local function group_looks(item, look)
    if item.measured then
        for _, g in ipairs(item.groups) do g.L, g.a, g.b = group_look(g.rows) end
    elseif look and look.seen then
        for _, g in ipairs(item.groups) do seen_look(g) end
    end
end

function Matcher.item(analysis_rows, armor, patterns, look, keep_hoods)
    local kit = look and look.kit
    local rows = copy_rows(analysis_rows, keep_hoods and look and look.hoods or nil)
    local item = {rows = rows, armor = armor, paint = {}, measured = measured_kit(rows, kit)}
    look_rows(rows, item.measured, kit, look)
    local paint_area = paint_of(item, kit)
    item.paint_area = paint_area
    item.groups = make_groups(item.paint, paint_area)
    group_looks(item, look)
    item.suit_paint = armor and suit_is_paint(item.groups, LARGE_AREA) or false
    -- as a target its suit takes colors when no group outside it reaches PAINT_SHARE: else the recolor shows nowhere
    -- (the O-3 Free Spirit, 97% suit, unchanged with the UF-50 Bloodhound; user 2026-10-07); an armor with a part of
    -- its own that size (the DP-00 Tactical's 7% yellow plates) keeps its dark undersuit
    item.suit_target = armor and suit_is_paint(item.groups, PAINT_SHARE) or false
    item.patterns = item_patterns(patterns, item.measured and kit or nil, paint_area)
    return item
end

-- Whether the assignment's source lightnesses and the identity's span less than 10 (light/dark flattened).
local function flat(assign, s, ref_s)
    local lo, hi = ref_s, ref_s
    for i = 1, #assign do
        local L = s[assign[i]].L
        if L < lo then lo = L end
        if L > hi then hi = L end
    end
    return hi - lo < 10
end

-- The objective of one assignment (source index per target paint group); see match.py _cost. c: the search
-- context {t, s, keep_ok, ref_t, ref_s, flat_check}.
local function cost(assign, c)
    local t, s = c.t, c.s
    local n, m = #t, #s
    local per, used = {}, {}
    for j = 1, m do used[j] = c.pre_used[s[j]] or 0 end
    for i = 1, n do
        local j = assign[i]
        local rel = math.abs((s[j].L - c.ref_s) - (t[i].L - c.ref_t))
        local dc = math.abs(chroma(s[j].a, s[j].b) - chroma(t[i].a, t[i].b))
        per[i] = t[i].share * (W_LIGHT * rel / 100 + W_CHROMA * dc / 100 + W_KEEP * (c.keep_ok[i][j] and 0 or 1))
        used[j] = used[j] + t[i].share
    end
    local total = npsum(per, n)
    local used_sum = math.max(npsum(used, m), 1e-9)
    local gaps = {}
    for j = 1, m do gaps[j] = math.abs(used[j] / used_sum - s[j].share / s.share_sum) end
    total = total + W_PROP * npsum(gaps, m) / 2
    if c.flat_check and flat(assign, s, c.ref_s) then total = total + W_FLAT end
    return total
end

-- One pass over target group i's allowed alternatives: returns the best cost and assignment and whether it
-- improved (first improvement wins, as match11.py _search).
local function improve(i, assign, best, c)
    local improved = false
    for j = 1, #c.s do
        if j ~= assign[i] and c.allowed[i][j] then
            local trial = {unpack(assign)}
            trial[i] = j
            local value = cost(trial, c)
            if value < best - 1e-9 then best, assign, improved = value, trial, true end
        end
    end
    return best, assign, improved
end

-- First-improvement local search over single reassignments; target groups in `fixed` (the anchor, parts that
-- already match a main source color) never move.
local function search(assign, fixed, c)
    local best = cost(assign, c)
    local improved = true
    while improved do
        improved = false
        for i = 1, #assign do
            if not fixed[i] then
                local better
                best, assign, better = improve(i, assign, best, c)
                improved = improved or better
            end
        end
    end
    return assign
end

-- Peak-to-peak of the L of groups with share >= BIG_SHARE, and how many there are.
local function big_spread(list)
    local count, lo, hi = 0, math.huge, -math.huge
    for _, g in ipairs(list) do
        if g.share >= BIG_SHARE then
            count = count + 1
            lo, hi = math.min(lo, g.L), math.max(hi, g.L)
        end
    end
    return count, count > 0 and hi - lo or 0
end

-- The source's palette: its groups of at least PAIR_MIN_SHARE, largest first, at most PALETTE_LIMIT (else
-- its largest group).
local function palette_of(source)
    local palette = {}
    for _, g in ipairs(source.groups) do
        if g.share >= PAIR_MIN_SHARE and #palette < PALETTE_LIMIT then palette[#palette + 1] = g end
    end
    if #palette == 0 and source.groups[1] then palette[1] = source.groups[1] end
    return palette
end

-- The light a group shows (measured items): its rows' pixels x mean screen luminance, a row's undersuit part weighed
-- UNDER_SALIENCE.
local function light_of(g)
    local total = 0.0
    for _, row in ipairs(g.rows) do
        local frac = row.area > 0 and row.under / row.area or 0.0
        total = total + (row.light or 0) * (1.0 - frac * (1.0 - UNDER_SALIENCE))
    end
    return total
end

-- The source's identity color: a helmet's largest paint group (helmet_main: not a vivid minority); an armor's most
-- salient (undersuit area weighs
-- UNDER_SALIENCE, dark neutrals DARK_SALIENCE, DARK_SALIENCE_TEXTURE when unmeasured). A measured armor whose most
-- salient color looks dark but which has a main color (share >= LARGE_AREA) that looks light and shows more light
-- reads as that color (the SR-64 Cinderblock as its light plates, not its dark straps). Structure groups are skipped
-- while any other group exists.
-- An armor's most salient group of pool (undersuit area weighs UNDER_SALIENCE, dark neutrals DARK_SALIENCE,
-- DARK_SALIENCE_TEXTURE when unmeasured).
local function salience(source, g)
    if not source.armor then return g.share end
    local dark = source.measured and DARK_SALIENCE or DARK_SALIENCE_TEXTURE
    return (g.area - g.under * (1 - UNDER_SALIENCE)) / source.paint_area * (neutral(g) and dark or 1.0)
end

local function most_salient(source, pool)
    local main, best = pool[1], -math.huge
    for _, g in ipairs(pool) do
        local s = salience(source, g)
        if s > best then best, main = s, g end
    end
    return main
end

-- The main color (share >= LARGE_AREA) of pool that looks light and shows the most light, if it shows more than
-- main.
local function lighter_main(pool, main)
    local light, most = nil, -math.huge
    for _, g in ipairs(pool) do
        if g.share >= LARGE_AREA and not looks_dark(g) and light_of(g) > most then light, most = g, light_of(g) end
    end
    if light and most > light_of(main) then return light end
    return nil
end

-- A helmet's identity: its largest group, unless that is a vivid color (model chroma >= ACCENT_VIVID) on less than
-- VIVID_MAJORITY of its paint while a muted group (model chroma < ACCENT_C) covers at least ANCHOR_MIN_SHARE: then the
-- largest muted group (pool runs from the largest). An armor is far larger than a helmet, so a vivid minority as its
-- main color takes over the whole body: the PH-9 Predator's red beret (42% of what shows) turned an entire dark armor
-- bright red (user 2026-10-06). The vivid color stays the source's accent.
local VIVID_MAJORITY = 0.5
local function helmet_main(pool)
    local top = pool[1]
    if chroma(top.ma, top.mb) < ACCENT_VIVID or top.share >= VIVID_MAJORITY then return top end
    for _, g in ipairs(pool) do
        if chroma(g.ma, g.mb) < ACCENT_C and g.share >= ANCHOR_MIN_SHARE then return g end
    end
    return top
end

-- A cape's identity is its outside's main color (Colour.outside_first; the user chose "outside first", 2026-10-11).
local function identity_of(source, palette)
    local pool = {}
    for _, g in ipairs(palette) do
        if source.suit_paint or not is_structure(g) then pool[#pool + 1] = g end
    end
    if #pool == 0 then pool = palette end
    if source.cape_source then pool = outside_first(pool) end
    if not source.armor then return helmet_main(pool) end
    local main = most_salient(source, pool)
    if not source.measured or not looks_dark(main) then return main end
    return lighter_main(pool, main) or main
end

-- Structure groups keep a dark neutral: the source's nearest by lightness, when it has one. Returns the paint groups
-- (the others, or all of them when suit: the target's undersuit is its paint, suit_target) and the share each palette
-- color took here ({[palette group] = share}), which counts in the search's proportions: the SC-30 Trailblazer Scout's
-- 51% black suit took the AF-50 Noxious Ranger's dark, but the search saw that dark unused and gave it the armor's light
-- tan plates too (gallery 2026-10-10; research/match12.py pair_groups pre_used). Set fidelity, armors from their sets'
-- helmets: dE median 7.06 -> 5.99 (metal), 5.69 -> 5.55 (paint). A cape of no dark neutral (guard: its part guard)
-- gives them a main color its guard allows (Colour.cape_structure).
local function structure_pairs(targets, palette, pairs, suit, guard)
    local neutrals, used, rest = {}, {}, {}
    for _, g in ipairs(palette) do if neutral(g) then neutrals[#neutrals + 1] = g end end
    local paint = {}
    for _, g in ipairs(targets) do
        if suit or not is_structure(g) then
            paint[#paint + 1] = g
        elseif #neutrals > 0 then
            local n = nearest_lightness(neutrals, g)
            pairs[#pairs + 1], used[n] = {g, n}, (used[n] or 0) + g.share
        elseif guard then
            rest[#rest + 1] = g
        end
    end
    if #rest > 0 then cape_structure(rest, palette, guard, CAPE_LIMITS, pairs, used) end -- src/colour.lua
    return paint, used
end

-- Initial assignment: each target group takes the allowed source color whose lightness relative to the
-- source's identity color best matches its own relative to the anchor.
local function initial_assign(t, s, ref_t, ref_s, allowed)
    local assign = {}
    for i = 1, #t do
        local best, gap = nil, math.huge
        for j = 1, #s do
            local d = math.abs((s[j].L - ref_s) - (t[i].L - ref_t))
            if allowed[i][j] and (best == nil or d < gap) then best, gap = j, d end
        end
        assign[i] = best
    end
    return assign
end

-- The source's largest color that is not its undersuit (the largest of all when every color is; the first of equal
-- shares). s.suit: the source's undersuit black is its paint (suit_is_paint).
local function largest_paint(s)
    local largest
    for j = 1, #s do
        if (s.suit or not is_structure(s[j])) and (largest == nil or s[j].share > s[largest].share) then largest = j end
    end
    if largest then return largest end
    largest = 1
    for j = 2, #s do if s[j].share > s[largest].share then largest = j end end
    return largest
end

-- Whether target group g may take source color j (keep: g already matches it). A large area takes only main colors,
-- one it already matches or the largest, never a trim; an undersuit color goes only to a small dark neutral group,
-- unless the source's undersuit black is its paint (s.suit).
local function may_take(g, s, j, keep, largest)
    local small = g.share < LARGE_AREA
    local size_ok = small or s[j].share >= MAIN_COLOR or keep or j == largest
    return size_ok and (keep or s.suit or not is_structure(s[j]) or (small and neutral(g)))
end

-- allowed[i][j]: target group i may take source color j (may_take); a group allowed none takes the largest.
local function allowed_matrix(t, s, keep_ok)
    local largest = largest_paint(s)
    local allowed = {}
    for i = 1, #t do
        local row, any = {}, false
        for j = 1, #s do
            row[j] = may_take(t[i], s, j, keep_ok[i][j], largest)
            any = any or row[j]
        end
        if not any then row[largest] = true end
        allowed[i] = row
    end
    return allowed
end

-- A muted target part (model chroma < ACCENT_C) of at least PAINT_SHARE of the paint never takes a vivid source color
-- (model chroma >= ACCENT_VIVID) other than the identity, unless it already matches it: a vivid minority is the
-- source's accent, and on a part that size it reads as a new main color (research/match12.py vivid_minor_guard). The
-- CPR-80 Bulwark's 9% yellow stripes turned the RS-40 Beast of Prey's khaki leg camo (8%) and the DS-191 Scorpion's
-- tan vest and leg panels (13%) solid yellow (user 2026-10-09: "mostly uniform light gray and yellow"; the I-44
-- Salamander's orange the same). Undergarment cloth (shirts, undersuits: under >= half its area) is covered at any size:
-- the PH-202 Twigsnapper's t-shirt sleeves (2.4% of the front view, far more from the side and back) turned yellow.
-- Target accents keep taking the source's accent. A part left with no color takes the identity. A vivid second main
-- color (SECOND_MAIN_SHARE or more, LIGHTER_MAIN_L lighter than the identity: a two-tone design, as anchor_of) is no
-- minority: it may take a muted part that is not undergarment cloth (the Thundering Hooves of Loyalty's gold, 40%, L 71
-- over its red's 36, never reached the SR-64 Cinderblock's grey plates, and the whole armor took the red: user
-- 2026-10-10, "pure red ... losing the accenting entirely"). The Cover of Darkness's red lining (35%, L 37 over its
-- dark grey's 21) stays off the DS-191 Scorpion's tan shell.
-- A cape whose colors besides its identity are all vivid (no muted one of MAIN_COLOR: two_tone) shows each of at least
-- TWO_TONE_SHARE as its design, no minority: guarded, every big part took the identity and the FS-37 Ravager went one
-- dark grey under the black cape 0beb97bc with its 21% red (gallery 2026-10-11, the same loss as the Hooves'); the
-- search's proportion term places it. The Cover of Darkness keeps its guard: its 11% grey sash is a muted color.
-- Helmet and armor sources keep the guard (Lua only, as src/capes.lua's part_guard: match12 plans no capes).
-- A vivid color covering VIVID_PART_SHARE of a helmet or armor source is no minority either: it may take muted parts
-- that are not undergarment cloth (the user's version comparisons 2026-10-15: the FS-05 Marksman's red, 27%, and the
-- I-92 Fire Fighter's orange, 22%, never reached the FS-37 Ravager's plates or the B-22 Model Citizen's chrome, "the
-- red failed to transfer"; the CPR-80 Bulwark's 9% yellow stays guarded; the same 10% as a secondary's floor), as long
-- as it covers no more of the source than the identity: a vivid color bigger than the identity is one the identity
-- passed over (helmet_main: the PH-9 Predator's red beret, 42% over its olive's 29%, may not lead an armor) and stays
-- an accent (user 2026-10-15: the I-44 Salamander turned red on 43% of its paint, "places red on almost everything as a
-- dominant color"; its red shoulder pad was fine).
-- A part of PAINT_SHARE or more in an earth tone that is not vivid (model chroma ACCENT_C to ACCENT_VIVID, model hue
-- EARTH_HUE_MIN to EARTH_HUE_MAX degrees: brown leather, tan, khaki, olive drab: a material, no accent) is guarded as a
-- muted part that is not undergarment cloth: the CPG-48 SAPPER's brown gloves, boots and waist panel (16%, chroma 27,
-- hue 74) took the PH-9 Predator's beret red as a main color (user 2026-10-15: "the boots and gloves aren't even
-- accented"; only its yellow shoulder pads are), the CW-4 Arctic Ranger's leather (14%, hue 66) the CPR-80 Bulwark's 9%
-- yellow. Colored parts of other hues are the item's accents and keep taking accent colors: the CM-14 Physician's
-- green trims and gloves (hue 164-169), the B-24 Enforcer's red-brown pads (hue 25).
local VIVID_PART_SHARE = 0.10
local EARTH_HUE_MIN, EARTH_HUE_MAX = 45.0, 110.0
local function earth_tone(g)
    local c = chroma(g.ma, g.mb)
    if c < ACCENT_C or c >= ACCENT_VIVID then return false end
    local hue = math.deg(math.atan2(g.mb, g.ma)) % 360.0
    return hue >= EARTH_HUE_MIN and hue <= EARTH_HUE_MAX
end
local function guard_part(row, s, keep_row, j_main, under, pair_only, least)
    local any = false
    for j = 1, #s do
        local part = s[j].share >= least and s[j].share <= s[j_main].share
        local second = not under and (s[j].share >= SECOND_MAIN_SHARE and s[j].L >= s[j_main].L + LIGHTER_MAIN_L
            or pair_only and s[j].share >= TWO_TONE_SHARE or part)
        if j ~= j_main and chroma(s[j].ma, s[j].mb) >= ACCENT_VIVID and not keep_row[j] and not second then
            row[j] = false
        end
        any = any or row[j]
    end
    if not any then row[j_main] = true end
end

local function vivid_minor_guard(allowed, t, s, keep_ok, j_main, cape)
    local pair_only = cape and two_tone_of(s, j_main, MAIN_COLOR, ACCENT_VIVID) -- src/colour.lua Colour.two_tone
    local least = cape and math.huge or VIVID_PART_SHARE
    for i = 1, #t do
        local muted = chroma(t[i].ma, t[i].mb) < ACCENT_C
        -- undergarment cloth: the Helldiver's base clothing, any size (a muted one)
        local under = t[i].under >= 0.5 * t[i].area and muted
        if (t[i].share >= PAINT_SHARE or under) and (muted or earth_tone(t[i])) then
            guard_part(allowed[i], s, keep_ok[i], j_main, under, pair_only, least)
        end
    end
end

-- keep_ok[i][j]: target group i already matches source group j (CIEDE2000 < KEEP_DE, as they look).
local function keep_matrix(t, s)
    local keep_ok = {}
    for i = 1, #t do
        keep_ok[i] = {}
        for j = 1, #s do keep_ok[i][j] = de2000(t[i].L, t[i].a, t[i].b, s[j].L, s[j].a, s[j].b) < KEEP_DE end
    end
    return keep_ok
end

-- The target group that takes the identity: the largest (share >= ANCHOR_MIN_SHARE) of the identity's look class
-- (looks dark or not: the helmet's main part takes the armor's main color, a light identity never lands on a dark
-- mask), else one that already matches it, else the largest. An identity under a second main color of the source
-- (share SECOND_MAIN_SHARE or more, LIGHTER_MAIN_L lighter) is the dark one of the two: the Thundering Hooves of
-- Loyalty's red (55%, L 36) under its gold (40%, L 71) landed on the SR-64 Cinderblock's light grey plates, the dark
-- main took the red too and the gold went unused (user 2026-10-10: "pure red ... losing the accenting entirely").
local function anchor_of(t, keep_ok, j_main, s)
    local identity, dark = s[j_main], looks_dark(s[j_main])
    for _, g in ipairs(s) do
        if g ~= identity and g.share >= SECOND_MAIN_SHARE and g.L >= identity.L + LIGHTER_MAIN_L then dark = true end
    end
    for i = 1, #t do
        if t[i].share >= ANCHOR_MIN_SHARE and looks_dark(t[i]) == dark then return i end
    end
    for i = 1, #t do
        if t[i].share >= ANCHOR_MIN_SHARE and keep_ok[i][j_main] then return i end
    end
    return 1
end

-- The closest of the source's main colors (share >= MAIN_COLOR) that target group g already matches, or nil.
local function closest_main(g, s, keep_row, allowed_row)
    local pick, gap = nil, math.huge
    for j = 1, #s do
        if keep_row[j] and allowed_row[j] and s[j].share >= MAIN_COLOR then
            local d = de2000(g.L, g.a, g.b, s[j].L, s[j].a, s[j].b)
            if d < gap then pick, gap = j, d end
        end
    end
    return pick
end

-- Parts that already match one of the source's main colors keep it: assign[i] = the closest such color, fixed[i] =
-- true (the FS-23 Battle Master's light crest, matching the SR-64 Cinderblock's light plates, went black when the
-- search mirrored the armor's 72% dark).
local function keep_matches(t, s, assign, fixed, keep_ok, allowed)
    for i = 1, #t do
        local pick = not fixed[i] and closest_main(t[i], s, keep_ok[i], allowed[i])
        if pick then assign[i], fixed[i] = pick, true end
    end
end

-- Whether both sides show light/dark structure (two big groups 20 L apart): the search then penalizes
-- flattening it.
local function needs_flat_check(t, s)
    local big_t, spread_t = big_spread(t)
    local big_s, spread_s = big_spread(s)
    return big_t >= 2 and spread_t >= 20 and big_s >= 2 and spread_s >= 20
end

-- The palette's share sum and suit paint (s.share_sum, s.suit), and the identity's (main's) index in it (1 when
-- absent).
local function palette_main(s, main, source)
    local shares = {}
    for i, g in ipairs(s) do shares[i] = g.share end
    s.share_sum, s.suit = npsum(shares, #s), source.suit_paint
    local j_main = 1
    for j = 1, #s do if s[j] == main then j_main = j end end
    return j_main
end

-- Pairs {target group, source group} and the anchor group (nil without paint) (match12.py pair_groups). Hood
-- groups (Recolor Hoods off) take no color.
function Matcher.pair_groups(target, source)
    local targets = {}
    for _, g in ipairs(target.groups) do
        if g.share >= TGT_MIN_SHARE and not g.hood then targets[#targets + 1] = g end
    end
    local palette = palette_of(source)
    local pairs = {}
    if #targets == 0 or #palette == 0 then return pairs, nil end
    local main = identity_of(source, palette)
    local t, pre_used = structure_pairs(targets, palette, pairs, target.suit_target,
                                        source.cape_source and source.part_guard)
    if #t == 0 then return pairs, nil end
    local s = palette
    local j_main = palette_main(s, main, source)
    local keep_ok = keep_matrix(t, s)
    -- a weapon (src/recolor.lua, Recolor Weapons) takes the identity on its largest painted part whatever its lightness,
    -- as the game's paint schemes paint a dark rifle white: by look class the Liberator's dark body went to the
    -- source's dark greys and only its light optic took a tan armor's color (offline plans 2026-10-15)
    local anchor = target.weapon and 1 or anchor_of(t, keep_ok, j_main, s)
    local allowed = allowed_matrix(t, s, keep_ok)
    vivid_minor_guard(allowed, t, s, keep_ok, j_main, source.cape_source)
    if source.part_guard then source.part_guard(allowed, t, s, keep_ok, ACCENT_C) end -- a cape source's (src/capes.lua)
    local c = {t = t, s = s, keep_ok = keep_ok, allowed = allowed, ref_t = t[anchor].L, ref_s = s[j_main].L,
               flat_check = needs_flat_check(t, s), pre_used = pre_used}
    local assign = initial_assign(t, s, c.ref_t, c.ref_s, allowed)
    assign[anchor] = j_main
    local fixed = {[anchor] = true}
    keep_matches(t, s, assign, fixed, keep_ok, allowed)
    assign = search(assign, fixed, c)
    if source.cape_source then cape_second(c, assign, anchor, j_main, CAPE_LIMITS) end -- src/colour.lua
    for i = 1, #t do pairs[#pairs + 1] = {t[i], s[assign[i]]} end
    return pairs, t[anchor]
end

-- The source's accent: its most salient visible saturated color (model chroma x sqrt(share)), or nil. A measured
-- item counts what shows from SOURCE_ACCENT_MIN_SHARE_MEASURED of its pixels (a small emblem is what the eye takes for
-- an armor's accent), texture shares from SOURCE_ACCENT_MIN_SHARE.
local function source_accent(source)
    local min_share = source.measured and SOURCE_ACCENT_MIN_SHARE_MEASURED or SOURCE_ACCENT_MIN_SHARE
    local best, pick = 0.0, nil
    for i = 1, #source.groups + #source.patterns do
        local g = source.groups[i] or source.patterns[i - #source.groups]
        local c = chroma(g.ma, g.mb)
        local light = g.mL >= SOURCE_ACCENT_MIN_L or (g.mL >= ACCENT_MIN_L and c >= ACCENT_VIVID)
        local visible = g.share >= min_share and light
        if visible and c >= ACCENT_C and c * math.sqrt(g.share) > best then best, pick = c * math.sqrt(g.share), g end
    end
    return pick
end

-- A target accent: saturated, not the anchor, small (share <= ACCENT_SMALL) or vivid up to ACCENT_MAX_SHARE (the
-- DS-10 Big Game Hunter's 26% muted tan hood is a main part, the CM-09 Bonesnapper helmet's 21% red jaw an accent).
-- A source's second color, what its target's small accents and patterns take when it has no visible saturated accent
-- (its accents then follow the pairing): its most salient paint group other than the identity and unlike it (CIEDE2000
-- >= KEEP_DE), hoods and (unless its suit is its paint) structure left out; nil when there is none (a one-color source:
-- the accents keep their color). They kept their own color before (v1.1), so a 1.5% yellow trim stayed yellow on the
-- DP-00 Tactical with the white and grey CW-36 Winter Warrior (user 2026-10-07); now it takes the Winter Warrior's
-- dark, a muted color counting (the IX-VOIDWALKER's navy).
local function fallback_accent(source)
    local palette = palette_of(source)
    if #palette == 0 then return nil end
    local main = identity_of(source, palette)
    local best, pick = -math.huge, nil
    for _, g in ipairs(palette) do
        if g ~= main and not g.hood and (source.suit_paint or not is_structure(g))
            and de2000(g.L, g.a, g.b, main.L, main.a, main.b) >= KEEP_DE and salience(source, g) > best then
            best, pick = salience(source, g), g
        end
    end
    return pick
end

-- Degrees between two hues (a, b pairs), 0-180 (match11.hue_gap).
local function hue_gap(a1, b1, a2, b2)
    local d = math.abs(math.deg(math.atan2(b1, a1) - math.atan2(b2, a2))) % 360.0
    return d > 180.0 and 360.0 - d or d
end

-- The share of g's hue family: g's own, plus every other group of the target that is saturated (model chroma >=
-- ACCENT_C) within FAMILY_HUE of g's model hue, added in group order (match12.family_share). The CM-14 Physician's
-- green is two groups (15% and 12%): each passed as a trim and the RS-67 Null Cipher's 0.3% yellow painted a quarter of
-- the armor (user 2026-10-07).
local FAMILY_HUE = 30.0
local function family_share(g, target)
    local total = g.share
    for _, o in ipairs(target.groups) do
        if o ~= g and chroma(o.ma, o.mb) >= ACCENT_C and hue_gap(o.ma, o.mb, g.ma, g.mb) <= FAMILY_HUE then
            total = total + o.share
        end
    end
    return total
end

-- A target accent: saturated (model chroma; a metal group's look when that is more saturated: metal's model color is
-- darkened and muted, its look is not, the RE-2310 Honorary Guard's gold band model chroma 28, look 42, image review
-- 2026-10-06), not the anchor, small or vivid up to ACCENT_MAX_SHARE. A trim goes by its hue family's share (family:
-- family_share).
local function is_accent(g, anchor, family)
    local c = chroma(g.ma, g.mb)
    if g.metal then c = math.max(c, chroma(g.a, g.b)) end
    if g == anchor or g.share > ACCENT_MAX_SHARE or c < ACCENT_C then return false end
    -- a colored trim up to LARGE_AREA on a neutral main surface (the anchor) is an accent whatever its chroma, so a
    -- trim's class does not flip between 9.9% and 10.5%: the DP-53 Savior of the Free's gold braid (10.5%, chroma 26) went
    -- black with the B-01 Tactical's dark shell instead of taking its yellow (user 2026-10-07); its hue family counts
    -- whole, so a color split in groups is no trim (family_share: the CM-14 Physician's green)
    return g.share <= ACCENT_SMALL or c >= ACCENT_VIVID or (family <= LARGE_AREA and anchor ~= nil and neutral(anchor))
end

-- Whether group g already matches one of the source's colors (share >= min_share, default PAIR_MIN_SHARE), as they
-- look.
local function matches_source(g, source, min_share)
    for _, s in ipairs(source.groups) do
        if s.share >= (min_share or PAIR_MIN_SHARE) and de2000(g.L, g.a, g.b, s.L, s.a, s.b) < KEEP_DE then return true end
    end
    return false
end

-- A target accent that already matches a source color keeps its own; under a cape a large one (share over
-- ACCENT_SMALL) only when the cape shows that color on MAIN_COLOR or more, else it takes the cape's main color: the
-- TR-7 Ambassador of the Brand's cyan plates (28%) matched the black cape bd961a7c's 5% navy hem and stayed vivid cyan
-- (independent review 2026-10-11, case 120; the user chose "the cape's main"; their pairing gave the cape's 4% red).
local function kept_match(t, source)
    if not (source.cape_source and t.share > ACCENT_SMALL) or matches_source(t, source, MAIN_COLOR) then return nil end
    return identity_of(source, palette_of(source)), 'pair', true -- the main as it is: no band coat (tint_bands)
end

-- The source group a target group takes and how ('pair' or 'accent'); nil keeps its color.
-- The source's most visible bare-metal group (at least PAINT_SHARE of its paint) for target group t when t is bare
-- metal taking s, a dark color (perceived L < LOOK_DARK_L, chroma >= TINT_C), with Match Materials off; else nil. A
-- dark color on bare metal shows only in its dim reflections and reads near-black, while metal next to metal reads as
-- one material: the CPR-80 Bulwark's steel took the DP-8 Mountain-Scaled's dull navy and turned near-black on its
-- silver, navy and gold armor; its chainmail's silver is what the steel should echo (image review 2026-10-06).
local TINT_C = 8.0 -- as src/transfer.lua: a color at least this saturated is a tint
local function metal_echo(t, s, source, materials)
    if materials or not t.metal or s.metal or s.L >= LOOK_DARK_L or chroma(s.a, s.b) < TINT_C then return nil end
    for _, g in ipairs(source.groups) do -- by area: the most visible first
        if g.metal and g.share >= PAINT_SHARE then return g end
    end
    return nil
end

-- What target group t takes: the source's saturated accent when it is an accent (none when it is dark or already
-- matches), else what the pairing gave it, s. Without a saturated accent, a source with a second color leaves its
-- accents the pairing's color (the DP-40 Hero of the Federation's gold trim the IX-VOIDWALKER's navy: v1.1 to v1.3 kept
-- their own color, user 2026-10-07); a one-color source (second nil) leaves them their own, as its color would erase
-- them (the RE-2310 Honorary Guard's gold trim with the all-dark AC-2 Obedient, agreed 2026-10-05).
-- A target accent above ACCENT_SMALL takes the source's accent only when the source shows it on at least
-- ACCENT_SOURCE_BIG of its paint, else what the pairing gives it: the RS-67 Null Cipher's 0.28% yellow painted United
-- in Equality's 24% purple band, as it had the CM-14 Physician's green (user 2026-10-07). The agreed accents keep
-- theirs: the I-44 Salamander's 7% orange (under ACCENT_SMALL) takes the SR-64 Cinderblock's 0.12% emblem, the RE-2310
-- Honorary Guard's 15% band the CE-27 Ground Breaker's 2.8% trim (match12.ACCENT_SOURCE_BIG).
local ACCENT_SOURCE_BIG = 0.01
-- A source accent under ACCENT_SOURCE_BIG (a speck) recolors a target accent bigger than itself only within the
-- accent's hue family: the RS-67 Null Cipher's 0.28% yellow turned the CM-14 Physician's 3% red canisters a bright
-- yellow (image review 2026-10-07, 66 degrees apart). Every agreed accent taking a speck stays within 28 degrees (the
-- I-44 Salamander's orange: the Bonesnapper's, Doubt Killer's and Cinderblock's reds and orange) or is smaller than it
-- (the Null Cipher's 0.3% marks take the Doubt Killer's 0.5% red); patterns keep their rule (match12.speck_across).
local function speck_across(t, accent)
    return accent.share < ACCENT_SOURCE_BIG and t.share > accent.share
        and hue_gap(t.ma, t.mb, accent.ma, accent.mb) > FAMILY_HUE
end

-- A one-color cape (no accent, no second color) repaints the target's accents with the pairing's color, where a
-- one-color helmet or armor leaves them (the RE-2310 Honorary Guard's gold): the I-92 Fire Fighter helmet's orange
-- stayed under the dark grey Triangulation Veil (independent review 2026-10-11; the user chose "repaint for capes").
local function choice(t, s, anchor, accent, second, source, target)
    if (accent == nil and second ~= nil) or not is_accent(t, anchor, family_share(t, target)) then return s, 'pair' end
    if accent == nil and source.cape_source then return s, 'pair' end
    if accent == nil or t.mL < ACCENT_MIN_L then return nil end
    if matches_source(t, source) then return kept_match(t, source) end
    if t.share > ACCENT_SMALL and accent.share < ACCENT_SOURCE_BIG or speck_across(t, accent) then return s, 'pair' end
    return accent, 'accent'
end

-- A CIELAB color with `lift` linear light added to each channel (white; negative removes it, down to black).
local function reflected(L, a, b, lift)
    local r, g, bl = lab_to_linear(L, a, b)
    return linear_to_lab(r + lift, g + lift, bl + lift)
end

-- Whether target row `row` of group t becomes the paint it takes (Match Materials): a hard (mode 0) metal row
-- taking a LUT row's paint (a pattern accent has no row), as a pair of a big part (share >= PAINT_SHARE) or as an
-- accent. Small metal details (bolts, rims) stay metal; parts never turn into metal (a metal's look cannot be fitted
-- reliably: it shows what it reflects).
local function painted(t, kind, src, row)
    local rep = src.rep
    if not rep.lut then return false end
    return row.mode == 0 and row.metal and not rep.metal and (kind == 'accent' or t.share >= PAINT_SHARE)
end

-- Whether target row `row` of group t becomes the metal it takes (Match Materials, v1.5): a hard (mode 0) paint row,
-- not bare metal and not clothing (mostly on undergarment pieces), taking a hard bare-metal LUT row of a helmet or
-- armor, or a cape's metallic row of any mode (src/capes.lua source_rows row.cape: its cloth renders the metallic, the
-- Eye of Liberty's gold going flat pale yellow with its column 6 w zeroed, live 2026-10-14; a paint scheme's camo
-- copy is no metal), as a pair or as an accent of any size, where it takes the color as it is: not as a darker part
-- keeping a share of its own lightness (tone < 0, tonal_offsets) nor as the undersuit's structure, which would turn
-- bright chrome on the FS-37 Ravager's black parts with the B-22 Model Citizen. Until v1.5 parts never turned into
-- metal ("only the color gets translated": the B-22 Model Citizen's chrome and the AD-26 Bleeding Edge's cobalt
-- accents gave matte paint; user report 2026-10-14). Cloth never becomes metal (v1.0's whole-row copies gave gold
-- fabric).
local function metallized(t, src, row, tone)
    local rep = src.rep
    if not rep.lut or rep.copy or not rep.metal or (rep.mode ~= 0 and not rep.cape) then return false end
    if (tone or 0) < 0 or is_structure(t) then return false end
    return row.mode == 0 and not row.metal and not (row.area > 0 and row.under >= 0.5 * row.area)
end

-- mapping[row key] = {source, kind, L, a, b, cal, finish, copy} for every row of target group t taking source color
-- src: each row keeps its lightness offset from its group and its hue offset scaled with the chroma change; an
-- unmeasured bare metal row taking paint aims PAINT_REFLECTION lighter. materials: a painted row aims at the paint's own
-- look (its offset came from its metal) through the source row's measured response (cal), and finish names the source
-- row whose finish it takes (src/recolor.lua). A source row marked copy (a paint scheme's camo row, src/schemes.lua)
-- is copied, colors and camo, instead of fitted: copy names it.
-- A source color below NEUTRAL_TINT_C passes its lightness only: its slight tint does not show on it (the GS-66
-- Lawmaker's silver measures b -3.7 from the Armory's bluish fill light in its metal, its dark visor surround a navy
-- that reads black), yet on a big matte part it turns into a cast (the B-24 Enforcer's leather went navy-purple and its
-- plates steel-blue; image review 2026-10-06). A row that becomes the paint it takes (Match Materials) aims at that
-- paint's own look, tint included: the same material shows the same tint on both.
local NEUTRAL_TINT_C = 5.0

-- The tint a target group's rows aim at (the goal's a, b) and the share of their own hue offsets they keep (the
-- chroma change, at most 1); a near-neutral goal passes no tint and no offsets.
local function source_tint(ta, tb, a, b)
    local s_c = chroma(a, b)
    if s_c < NEUTRAL_TINT_C then return 0, 0, 0 end
    local t_c = chroma(ta, tb)
    return a, b, t_c > 1.0 and math.min(1.0, s_c / t_c) or 1.0
end


-- How much lighter or darker (perceived L) a part matching a bare-metal source color is in the game's own complete
-- sets, by what the metal sits on (the source item type; a cape takes the same as any part) and whether the target row
-- is bare metal itself (research/match12.py METAL_SHIFT,
-- research/scratch/set_metal2.py): a metal's look counts its reflections, which a matte paint does not have, and a
-- helmet's dome takes the key light an armor's metal does not. The artists paint a matte armor part 9.4 L darker than the
-- helmet metal it matches (the CPR-80 Bulwark's own armor L 30 against its helmet steel's L 39), armor metal 2.9 L
-- darker, and a matte helmet part 2.8 L darker than an armor's metal; paint matching paint needs none. The Bulwark's
-- armors were asked for L 36-41 and showed far lighter than the helmet looks (user 2026-10-09: "way too bright").
-- The shift scales with the metal's own lightness (METAL_SHIFT_L, the sets' median metal look): a reflection is a
-- smaller part of a dark metal's look, and a dark bronze must not turn the paint taking it black (the FS-37 Ravager
-- helmet from the PH-202 Twigsnapper, 2026-10-05).
-- Helmet metal on armor metal takes the matte value too (research/match12.py: a metal's look does not carry from a helmet's
-- dome to an armor's plates; the PH-202 Twigsnapper's steel plates showed brighter than the Bulwark, 2026-10-09).
local METAL_SHIFT = {Helmet = {[false] = -9.4, [true] = -9.4}, Armor = {[false] = -2.8}}
local METAL_SHIFT_L = 36.6
local function metal_shift(source_armor, src, row)
    if not src.metal then return 0 end -- a pattern color as source is paint
    local shift = METAL_SHIFT[source_armor and 'Armor' or 'Helmet'][row.metal and true or false]
    return shift and shift * src.L / METAL_SHIFT_L or 0
end

-- Target groups that take the same source color as a larger one: {[group] = lightness offset}. The lead (the anchor
-- when it takes that color, else the largest) takes the color as it is; every other one darker than the lead keeps
-- TONAL_K of its own perceived lightness difference from it (research/match12.py tonal_offsets). Lighter ones keep none:
-- a dark source still darkens a light part (the agreed I-44 Salamander shell from the B-01 Tactical's dark, 2026-10-05). A source with one main color gave
-- every large part that color: the RS-40 Beast of Prey's dark L 20 straps and its L 32 plates both the CPR-80 Bulwark's
-- steel, a uniform light grey (user 2026-10-09: "mostly uniform light gray and yellow"). Structure groups (they take
-- the source's dark neutral by lightness) and accents keep none. 0.5: on the one-helmet one-armor sets
-- (research/scratch/set_fidelity.py) closer to the sets' own colors in every class; 1.0 overshot where parts also take
-- other colors.
local TONAL_K = 0.5

-- The paired (not structure) target groups per source color they take, in first-seen order: {{group, ...}, ...}.
local function groups_by_source(choices)
    local by_source, order = {}, {}
    for _, c in ipairs(choices) do
        local t, src, kind = c[1], c[2], c[3]
        if kind == 'pair' and not is_structure(t) then
            if not by_source[src] then
                by_source[src] = {}
                order[#order + 1] = by_source[src]
            end
            table.insert(by_source[src], t)
        end
    end
    return order
end

-- The lead of groups taking one color: the anchor when among them, else the largest (the first of equals, as
-- Python's max).
local function lead_of(list, anchor)
    local lead
    for _, g in ipairs(list) do
        if g == anchor then return g end
        if not lead or g.share > lead.share then lead = g end
    end
    return lead
end

local function tonal_offsets(choices, anchor)
    local out = {}
    for _, list in ipairs(groups_by_source(choices)) do
        local lead = #list >= 2 and lead_of(list, anchor) or nil
        for _, g in ipairs(lead and list or {}) do
            if g ~= lead then out[g] = TONAL_K * math.min(g.L - lead.L, 0) end
        end
    end
    return out
end

-- A row's lightness when its group, of perceived lightness t_L, takes base: the row keeps its offset from its group as
-- a luminance ratio when the group darkens (one paint scaled: rows of one paint look apart by their responses), as a
-- difference when it lightens. Kept as differences, the B-22 Model Citizen's chrome guards (one paint, responses 0.05
-- to 0.17) were asked L 6 to 21 from a cape's dark L 24, fitted to paints as low as L 39 and read pitch black (user
-- 2026-10-10: "the shinguards turning pitch black", "some of the armor pieces on that set have the same problem").
local function row_lightness(base, row_L, t_L)
    if base >= t_L then return base + (row_L - t_L) end
    local y = lab_to_linear(base, 0, 0) * lab_to_linear(row_L, 0, 0) / math.max(lab_to_linear(t_L, 0, 0), 1e-9)
    return (linear_to_lab(y, y, y))
end

-- A paired row's goal (map_group): its group's diffuse goal d (diffuse_colors: L, its tint sa, sb at scale, the
-- target group's own tL, ta, tb, glossy) with the row's offset from its group, its gloss over it.
local function pair_goal(row, src, d, source_armor, tone)
    local rL, ra, rb, dr, dg, db = row.L, row.a, row.b
    if d.glossy then dr, dg, db = row_diffuse(row) end
    if dr then rL, ra, rb = linear_to_lab(math.max(dr, 0), math.max(dg, 0), math.max(db, 0)) end
    local L = row_lightness(d.L + metal_shift(source_armor, src, row) + (tone or 0), rL, d.tL)
    local a, b = d.sa + (ra - d.ta) * d.scale, d.sb + (rb - d.tb) * d.scale
    if dr then L, a, b = with_gloss(L, a, b, row.cal) end
    if not row.cal and row.full == true and src.rep.full ~= true then -- bare metal taking paint: the paint's sheen
        L, a, b = reflected(L, a, b, PAINT_REFLECTION)
    end
    return L, a, b
end

local function map_group(mapping, t, kind, src, materials, source_armor, tone)
    local gL, ga, gb, tL, ta, tb, glossy = diffuse_colors(t, src)
    local sa, sb, scale = source_tint(ta, tb, ga, gb)
    local d = {L = gL, sa = sa, sb = sb, scale = scale, tL = tL, ta = ta, tb = tb, glossy = glossy}
    for _, row in ipairs(t.rows) do
        if src.rep.copy then
            local paint = materials and painted(t, kind, src, row)
            mapping[row.key] = {source = src.rep.key, kind = kind, L = src.L, a = src.a, b = src.b,
                                copy = src.rep.key, finish = paint and src.rep.key or nil}
        elseif materials and painted(t, kind, src, row) then
            mapping[row.key] = {source = src.rep.key, kind = kind, L = src.gL or src.L, a = src.ga or src.a,
                                b = src.gb or src.b, cal = src.rep.cal, finish = src.rep.key}
        elseif materials and metallized(t, src, row, tone) then -- its finish and one coat of its paint (transfer)
            local rep = src.rep
            mapping[row.key] = {source = rep.key, kind = kind, L = rep.mL, a = rep.ma, b = rep.mb, finish = rep.key,
                                coat = true}
        else
            local L, a, b = pair_goal(row, src, d, source_armor, tone)
            mapping[row.key] = {source = src.rep.key, kind = kind, L = L, a = a, b = b, cal = row.cal}
        end
    end
end

-- Accent groups below the pairing minimum (v11.4: the RS-67 Null Cipher's 0.9% yellow) take `small`: the source's
-- saturated accent, else its second color.
local function map_small_accents(mapping, target, source, small, materials)
    for _, t in ipairs(target.groups) do
        if t.share < TGT_MIN_SHARE and not t.hood and chroma(t.ma, t.mb) >= ACCENT_C and t.mL >= ACCENT_MIN_L
            and not matches_source(t, source) then
            map_group(mapping, t, 'accent', small, materials, source.armor)
        end
    end
end

-- The plan: {target row key -> {source = source row key, kind, L, a, b (desired perceived color), cal (the measured
-- response the fit goes through, or nil), finish (Match Materials: the source row whose finish the row takes, or
-- nil), band (an accent band's row: L, a, b are a paint, src/transfer.lua)}} for every recolored row. materials: Match
-- Materials on. cape: the target is a cape: its parts keep no lightness
-- offsets (tonal_offsets), its design zones and emblems have their own readability rules (Matcher.cape_zones).
-- An accent band (user 2026-10-09: the IX-VOIDWALKER's navy stripe band, 26% of the helmet, read as a pitch black
-- stripe on the RE-1861 Parade Commander and most dark armors). A painted hard target part of PAINT_SHARE to
-- BAND_MAX_SHARE of the item that shows a color of its own (model chroma OWN_COLOR_C or more; not undergarment cloth),
-- paired with a neutral source color (model chroma under BLACK_C: a black, or a grey, as the CE-64 Grenadier's band
-- paired with a mod-patched CE-27 Ground Breaker turned a grey-beige: "transferred gray"), takes the source
-- accent's paint (band_hue_source; its model color: mapping.band, a flat coat fitted through the model,
-- src/transfer.lua).
-- Its look through the band's response read pale: the IX-VOIDWALKER's band (response 0.52, measured on its navy)
-- fitted to the B-01 Tactical's yellow look went to a base of L 96, its detail colors lime and light grey (user
-- 2026-10-10: "doesn't match the armor's own accenting"; on screen L 87 C 31 against the armor's L 67 C 52); a coat of
-- the armor's own paint matched it best of seven live variants, as the game's sets paint matching parts (500 part
-- pairs of one paint against 31 of one look across responses 1.5x apart, research/scratch/dark-band/
-- set_paint_vs_look.lua). A darker shade of its look (2026-10-09, rounds 12-13) read olive, then,
-- turned toward bronze, orange on the B-01 Tactical (user 2026-10-10: "should be yellow"), and a B-01 Tactical
-- helmet's red stripes (45%) went grey with the KDM-763 Pacesetter's yellow stripes. A part that large may only take
-- the source's main colors (may_take), so on an armor whose one main color is black the band had no other choice.
-- Without a colored source color the part stays as paired (research/match12.py tint_bands). A band is under half the
-- item: the EX-16 Prototype 16's olive base (81%) stays the SC-34 Infiltrator's black (agreed 2026-10-06). Its
-- constants are with the others at the top (OWN_COLOR_C ...).

local function hard_part(g)
    local hard, all = 0.0, 0.0
    for _, row in ipairs(g.rows) do all, hard = all + row.area, hard + (row.mode == 0 and row.area or 0) end
    return (all > 0 and hard >= 0.5 * all) or (all <= 0 and g.rep.mode == 0)
end
-- A band's pairing (research/match12.py band_part, band_like): paired with a neutral source color, not the item's largest part
-- (its main: a B-01 Tactical helmet's red, 45%, turned the KDM-763 Pacesetter's yellow, "inverted"; gallery
-- 2026-10-10), at most BAND_MAX_SHARE, not undergarment cloth, mostly hard paint.
local function band_pair(c, largest)
    local t = c[1]
    return c[3] == 'pair' and not c[4] and t ~= largest and t.share <= BAND_MAX_SHARE and t.under < 0.5 * t.area
        and hard_part(t) and chroma(c[2].ma, c[2].mb) < BLACK_C
end
-- A band (band_part): from PAINT_SHARE, colored or a light stripe (look L LIGHT_BAND_L or more) the pairing turned dark
-- (its pair's look under DARK_PAIR_L: its white stripe).
local function band_part(c, largest)
    local t = c[1]
    return band_pair(c, largest) and t.share >= PAINT_SHARE
        and (chroma(t.ma, t.mb) >= OWN_COLOR_C or (t.L >= LIGHT_BAND_L and c[2].L < DARK_PAIR_L))
end
-- Whether group t is one of bands or of a band's color and material (model CIEDE2000 under KEEP_DE, any share: one
-- design color; a bare-metal part of it is a metal finish, the B-01 Tactical helmet's silver jaw badges with its
-- cream jaw; its band-colored patterns take the coat too, band_coat).
local function of_bands(t, bands)
    for _, b in ipairs(bands) do
        if b == t or (b.metal == t.metal and de2000(t.mL, t.ma, t.mb, b.mL, b.ma, b.mb) < KEEP_DE) then return true end
    end
    return false
end
-- The color a band takes: the source accent, else the source's most colorful group that pairs (share PAIR_MIN_SHARE
-- or more, model chroma ACCENT_C or more; the B-24 Enforcer's dark reds, 16%, too dark to be its visible accent), else
-- its most salient colored light or lens (Matcher.light: the KDM-763 Pacesetter's yellow light strips on black paint,
-- gallery 2026-10-10; lights never give their color otherwise; by texture area and model color, as the appearance
-- study measured paint only), else nil. An armor's band (armor) takes a color covering BAND_ARMOR_MIN_SHARE of the
-- source and no light: an armor is far larger than a helmet, and the RS-100 Sanctioner's 2.8% gold painted a quarter
-- of the O-44 Bonded Pilot, its red-brown plates, light gold (Reddit report 2026-10-14; v1.3 made them its black; the
-- user's floor for a secondary, review 1). A weapon's band (Recolor Weapons) takes the armor's rule: a scheme's light
-- detail rows are bands of the weapon's body, and the PH-56 Jaguar's 0.6% yellow trim painted 40% of the P-2
-- Peacemaker lemon yellow (independent render review 2026-10-15, case 6). A helmet's band keeps the agreed rule (the
-- IX-VOIDWALKER's navy band takes the RE-1861 Parade Commander's 5% dark red, the B-01 Tactical's lemon decal).
local function band_group(source, least)
    local best
    for _, g in ipairs(source.groups) do
        local c = chroma(g.ma, g.mb)
        if g.share >= math.max(PAIR_MIN_SHARE, least) and c >= ACCENT_C and (not best or c > chroma(best.ma, best.mb)) then
            best = g
        end
    end
    return best
end
local function band_light(source)
    local best, weight = nil, 0
    for _, row in ipairs(source.rows) do
        local w = Matcher.light(row) and chroma(row.ma, row.mb) >= ACCENT_C and row.tex_area * chroma(row.ma, row.mb) or 0
        if w > weight then best, weight = {L = row.mL, a = row.ma, b = row.mb, mL = row.mL, ma = row.ma, mb = row.mb}, w end
    end
    return best
end
local function band_hue_source(source, accent, armor)
    local least = armor and BAND_ARMOR_MIN_SHARE or 0
    if accent and chroma(accent.ma, accent.mb) >= ACCENT_C and (accent.share or 0) >= least then return accent end
    return band_group(source, least) or (not armor and band_light(source)) or nil
end
-- The item's largest part and its bands (band_part).
local function bands_of(choices)
    local largest, bands = choices[1] and choices[1][1], {}
    for _, c in ipairs(choices) do if c[1].share > largest.share then largest = c[1] end end
    for _, c in ipairs(choices) do if band_part(c, largest) then bands[#bands + 1] = c[1] end end
    return largest, bands
end
local function tint_bands(mapping, choices, source, accent, armor)
    accent = band_hue_source(source, accent, armor)
    if not accent then return end
    local largest, bands = bands_of(choices)
    for _, c in ipairs(choices) do
        for _, row in ipairs(band_pair(c, largest) and of_bands(c[1], bands) and c[1].rows or {}) do
            local m = mapping[row.key] -- the pair's source and finish stay; the paint, a flat coat (src/transfer.lua)
            if m then
                -- shows: the source color whose paint it takes (src/variety.lua counts the row as that color)
                m.L, m.a, m.b, m.band, m.shows = accent.mL, accent.ma, accent.mb, true, accent.rep and accent.rep.key
                if m.coat then m.coat, m.finish = nil, nil end -- a band stays paint (Match Materials' metal: metallized)
            end
        end
    end
end

-- Cloth (soft rows) paired with a colored bare-metal source color (look chroma TINT_C or more: gold, bronze, cobalt)
-- takes the source's non-metal palette color nearest it in look lightness instead: cloth never turns metal, and the
-- metal's paint on it read as a flat mustard that barely shows on the source (the B-24 Enforcer's coat and undersuit,
-- 46% of it, from the BP-77 Grand Juror's 31% gold; the user's version comparisons 2026-10-15, case 15). A source of
-- metal alone leaves it (research/match12.py cloth_off_metal).
local function plain_nearest(source, src)
    local best, gap
    for _, g in ipairs(palette_of(source)) do
        local d = math.abs(g.L - src.L)
        if not g.metal and (not best or d < gap) then best, gap = g, d end
    end
    return best
end
-- The planned cloth rows of target group t (soft, no band coat), or nil.
local function cloth_rows(mapping, t)
    local rows
    for _, row in ipairs(t.rows) do
        local m = mapping[row.key]
        if m and not m.band and row.mode >= 0.5 then
            rows = rows or {}
            rows[#rows + 1] = row
        end
    end
    return rows
end
local function cloth_off_metal(mapping, choices, source, materials, tones)
    for _, c in ipairs(choices) do
        local t, src = c[1], c[2]
        local rows = c[3] == 'pair' and src.metal and chroma(src.a, src.b) >= TINT_C and cloth_rows(mapping, t)
        local alt = rows and plain_nearest(source, src)
        if alt then
            local part = {}
            for key, v in pairs(t) do part[key] = v end
            part.rows = rows
            map_group(mapping, part, 'pair', alt, materials, source.armor, tones[t])
        end
    end
end

-- An armor's plan never left in one color (src/variety.lua Matcher.balance, v1.5); a cape's as it is.
local function balanced(mapping, target, source, cape)
    if Matcher.balance and target.armor and not cape then Matcher.balance(mapping, target, source) end
    return mapping
end

function Matcher.plan(target, source, materials, cape)
    local mapping = {}
    local pairs, anchor = Matcher.pair_groups(target, source)
    local accent = source_accent(source)
    local second = accent == nil and fallback_accent(source) or nil
    local choices = {}
    for _, pair in ipairs(pairs) do
        local t = pair[1]
        local src, kind, main = choice(t, pair[2], anchor, accent, second, source, target)
        if kind == 'pair' then src = metal_echo(t, src, source, materials) or src end
        if src then choices[#choices + 1] = {t, src, kind, main} end
    end
    local tones = cape and {} or tonal_offsets(choices, anchor)
    for _, c in ipairs(choices) do map_group(mapping, c[1], c[3], c[2], materials, source.armor, tones[c[1]]) end
    tint_bands(mapping, choices, source, accent, target.armor or target.weapon)
    cloth_off_metal(mapping, choices, source, materials, tones)
    local small = accent or second or (source.cape_source and anchor and Matcher.identity(source)) or nil
    if small then map_small_accents(mapping, target, source, small, materials) end
    return balanced(mapping, target, source, cape)
end

-- The source's identity color (identity_of over its palette); src/schemes.lua's near one-color split takes it as the
-- cape's main.
function Matcher.identity(source) return identity_of(source, palette_of(source)) end

-- For src/schemes.lua's material roles (a paint scheme whose parts take its colors by material, SEAF): the row mapping
-- and the thresholds they share with the pairing.
Matcher.map_group = map_group
-- for src/zones.lua (a cape's design zones and emblems: Matcher.cape_zones, cape_emblems)
Matcher.palette_of, Matcher.source_accent, Matcher.ACCENT_SOURCE_BIG = palette_of, source_accent, ACCENT_SOURCE_BIG
Matcher.is_structure = is_structure -- src/variety.lua
Matcher.ACCENT_C, Matcher.MAIN_COLOR, Matcher.PAINT_SHARE = ACCENT_C, MAIN_COLOR, PAINT_SHARE

-- The source color a light neutral pattern takes: the source's neutral paint (palette groups under ACCENT_C model
-- chroma; hoods and, unless its suit is its paint, structure left out) nearest in lightness to the pattern's look, the
-- earlier in the palette on a tie; nil when the source has fewer than two (its one neutral would erase the pattern),
-- and never a saturated color (the UF-84 Doubt Killer's red trim). The CM-14 Physician's cream panels (13.7% of what
-- shows) stayed cream with the all-dark RS-67 Null Cipher; they take its grey (image review 2026-10-07;
-- match12.neutral_pattern_color).
local LIGHT_PATTERN_L = 40.0 -- a neutral pattern at least this light (model L) takes a source color
local function neutral_pattern_color(p, source)
    local pick, gap, count = nil, math.huge, 0
    for _, g in ipairs(palette_of(source)) do
        if not g.hood and (source.suit_paint or not is_structure(g)) and chroma(g.ma, g.mb) < ACCENT_C then
            count = count + 1
            local d = math.abs(g.L - p.L)
            if d < gap then pick, gap = g, d end
        end
    end
    return count >= 2 and pick or nil
end

-- The band coat a target pattern of a band's color takes (one design color with a target group the plan coats,
-- mapping.band: model CIEDE2000 under KEEP_DE; a B-01 Tactical helmet's cream dome stripes, a pattern of 7%, with its
-- cream jaw, 18%; gallery 2026-10-10, user: "One helmet's stripes remained white and failed to accent"), or nil: its
-- texel the coat's paint (the desired color is the paint through the pattern's gain).
local function band_coat(p, target, plan)
    for _, g in ipairs(plan and target.groups or {}) do
        local m = plan[g.rows[1].key]
        if m and m.band and de2000(p.mL, p.ma, p.mb, g.mL, g.ma, g.mb) < KEEP_DE then
            local L, a, b, k = m.L, m.a, m.b, p.gain
            if k then
                local r, gr, bl = lab_to_linear(L, a, b)
                L, a, b = linear_to_lab(math.max(k[1] * r, 0), math.max(k[2] * gr, 0), math.max(k[3] * bl, 0))
            end
            return {source = m.source, L = L, a = a, b = b, gain = k}
        end
    end
end

-- The source color a target pattern takes (pattern_plan), or nil.
local function pattern_pick(p, source, accent)
    if matches_source(p, source) then return nil end
    if chroma(p.ma, p.mb) < ACCENT_C then return p.mL >= LIGHT_PATTERN_L and neutral_pattern_color(p, source) or nil end
    return p.mL >= ACCENT_MIN_L and accent or nil
end

-- The pattern plan: {target pattern texture -> {source, L, a, b (desired perceived color), gain}} (v11.4: the FS-23
-- Battle Master's yellow stripes): each target pattern whose color is an accent takes the source's accent (else its
-- second color), a light neutral one (model L at least LIGHT_PATTERN_L) the color neutral_pattern_color gives, unless
-- it already matches that color or a source color, or the source has none; a dark neutral one keeps its color, as a
-- dark undersuit does; one of a band's color takes the band's coat (band_coat; plan: the target's Matcher.plan, or
-- nil). gain: the target pattern's measured gain (its new texel color is the desired color through it), or nil.
-- A cape of one color gives its identity, as Matcher.plan's small accents take it (the user chose "repaint for capes"):
-- the FS-23 Battle Master's yellow stripes, a pattern of 7.7%, stayed yellow under the all-dark-grey cape e7619545
-- (independent review 2026-10-11, fresh gallery case 37).
function Matcher.pattern_plan(target, source, plan)
    local out = {}
    local accent = source_accent(source) or fallback_accent(source) or (source.cape_source and Matcher.identity(source))
    for _, p in ipairs(target.patterns) do
        local pick = accent and pattern_pick(p, source, accent)
        out[p.pattern] = band_coat(p, target, plan)
        if not out[p.pattern] and pick and de2000(p.L, p.a, p.b, pick.L, pick.a, pick.b) >= KEEP_DE then
            out[p.pattern] = {source = pick.rep.key, L = pick.L, a = pick.a, b = pick.b, gain = p.gain}
        end
    end
    return out
end

-- Code that runs once or rarely (jobs, startup, events) stays interpreted, sub-functions included: it must not
-- add traces to the LuaJIT code cache the game and every mod share. Only the hot loops stay compiled.
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({Matcher.use, sort_desc, chroma, is_neutral, neutral, looks_dark, light_of,
        is_structure, suit_is_paint, make_groups, item_patterns, copy_rows, paint_of, Matcher.item, most_salient,
        measured_kit, luminance, light_scale, respond, measure_rows, unmeasured_rows, borrow_rows, look_rows,
        lighter_main, salience, fallback_accent, flat, cost, improve, search, seen_look, group_looks, balanced,
        big_spread, palette_of, helmet_main, identity_of, Matcher.identity, structure_pairs,
        initial_assign, largest_paint,
        may_take, allowed_matrix, earth_tone, guard_part, vivid_minor_guard,
        keep_matrix, anchor_of, closest_main, keep_matches, needs_flat_check, palette_main, Matcher.pair_groups,
        source_accent,
        hue_gap, family_share, is_accent, matches_source, kept_match, metal_echo, speck_across, choice, source_tint,
        reflected, painted, metallized, metal_shift, groups_by_source, lead_of, tonal_offsets, row_lightness,
        pair_goal, map_group,
        map_small_accents,
        hard_part, band_pair, band_part, of_bands, band_group, band_light, band_hue_source, bands_of, tint_bands,
        plain_nearest, cloth_rows, cloth_off_metal,
        Matcher.plan,
        neutral_pattern_color, band_coat, pattern_pick, Matcher.pattern_plan, Matcher.light}) do
        jit.off(fn, true)
    end
end

return Matcher
end)()
local Zones = (function()
-- Match Your Colors: a cape's design zones and emblems kept readable when the cape is recolored (Recolor Cape: the
-- cape as the target). Attached to src/matcher.lua as Matcher.cape_zones and Matcher.cape_emblems (Zones.attach), with
-- the matcher's palette and accent; it was part of src/matcher.lua until v1.5. Nothing here runs per frame.
local Zones = {}

-- Set once by Zones.attach (the matcher's and the color model's functions).
local lab_to_linear, linear_to_lab, palette_of, source_accent, ACCENT_SOURCE_BIG
function Zones.attach(Matcher, colour)
    lab_to_linear, linear_to_lab = colour.lab_to_linear, colour.linear_to_lab
    palette_of, source_accent, ACCENT_SOURCE_BIG = Matcher.palette_of, Matcher.source_accent, Matcher.ACCENT_SOURCE_BIG
    Matcher.cape_zones, Matcher.cape_emblems = Zones.cape_zones, Zones.cape_emblems
end

-- Cape design zones (v1.3, KB match-your-colors-cape-tint; research/match12.py cape_zones; moved from src/matcher.lua in v1.5): an outside emblem, mark or
-- sash (src/capes.lua zones: the cloth bordering it by row and tint bin) that read against half its border (lightness
-- contrast >= ZONE_READ) and no longer reads against half of it as planned (< ZONE_LOST) takes the source color that
-- reads against the most of its planned border (a palette color or the source's accent; ties: the zone's light/dark
-- order against its border kept, then the larger share), when that reads against half; failing that, the one reading
-- against the most of it by CIELAB distance (and against half its cloth), else a smaller source color by lightness,
-- when that reads against half (zone_choice); else its own colors, when they read against half; else the plan stays.
-- Zones go from the largest; a zone first tries the color an earlier zone of its target group took, so a design drawn
-- in one color stays one. The B-01 Tactical made the Drape of Glory's light top and blue-grey bottom one dark, and the
-- CW-36 Winter Warrior's light gave United in Equality's emblem and the purple band around it the same off-white
-- (2026-10-07).
local ZONE_READ, ZONE_LOST, ZONE_BINS = 15.0, 10.0, 8

-- {[row] = {base = item row, tint = item row}} of a cape item (tint_of: its cape LUT -> material LUT).
local function zone_parts(target, tint_of)
    local parts = {}
    for _, row in ipairs(target.rows) do
        local p = parts[row.row] or {}
        parts[row.row] = p
        if tint_of and tint_of[row.lut] then p.tint = row else p.base = row end
    end
    return parts
end

-- A row's display-linear color: plan's desired color (plan nil: its own).
local function row_linear(row, plan)
    local goal = plan and plan[row.key]
    if goal then return lab_to_linear(goal.L, goal.a, goal.b) end
    return lab_to_linear(row.L, row.a, row.b)
end

-- A zone's lightness: its base and tint mixed by area.
local function zone_lightness(p, plan)
    local r, g, b, w = 0, 0, 0, 0
    for _, row in ipairs({p.base or false, p.tint or false}) do
        if row then
            local lr, lg, lb = row_linear(row, plan)
            r, g, b, w = r + row.tex_area * lr, g + row.tex_area * lg, b + row.tex_area * lb, w + row.tex_area
        end
    end
    return (linear_to_lab(r / w, g / w, b / w))
end

-- Whether a border cell of Lab color (cL, ca, cb) reads against lightness L: their lightness at least `threshold`
-- apart, or (hue: a Lab color {L, a, b}) their CIELAB distance from hue, where hue and chroma count too (squared, in
-- research/match12.py apart's order).
local function apart(L, hue, cL, ca, cb, threshold)
    if not hue then return math.abs(L - cL) >= threshold end
    local dL, da, db = hue.L - cL, hue.a - ca, hue.b - cb
    return dL * dL + da * da + db * db >= threshold * threshold
end

-- One border row's cells into acc ({good, total, mean, hue}): at bin k its color is its base blended toward its tint
-- by (k + 0.5) / ZONE_BINS; a cell reads when it is `threshold` apart from L (acc.hue: from that color; apart).
local function border_row(acc, L, counts, p, plan, threshold)
    local br, bg, bb = row_linear(p.base or p.tint, plan)
    local tr, tg, tb = row_linear(p.tint or p.base, plan)
    for k = 0, ZONE_BINS - 1 do
        local n = counts[k]
        if n > 0 then
            local t = (k + 0.5) / ZONE_BINS
            local bL, ba, bb2 = linear_to_lab(br * (1 - t) + tr * t, bg * (1 - t) + tg * t, bb * (1 - t) + tb * t)
            acc.total, acc.mean = acc.total + n, acc.mean + n * bL
            if apart(L, acc.hue, bL, ba, bb2, threshold) then acc.good = acc.good + n end
        end
    end
end

-- (border cells read, border cells, mean border L) of a zone of lightness L against `around` ({[row] = {[bin] =
-- cells}}) as plan colors it; hue (a Lab color {L, a, b}, or nil): read by CIELAB distance from it instead.
local function zone_reads(L, around, parts, plan, threshold, hue)
    local acc = {good = 0, total = 0, mean = 0.0, hue = hue or false}
    for q = 0, 4 do
        local counts, p = around[q], parts[q]
        if counts and p and (p.base or p.tint) then border_row(acc, L, counts, p, plan, threshold) end
    end
    return acc.good, acc.total, acc.total > 0 and acc.mean / acc.total or 0.0
end

-- The source colors a zone may take: the palette, then the accent when it is not in it.
local function zone_candidates(source)
    local list = palette_of(source)
    local accent = source_accent(source)
    if accent then
        for _, g in ipairs(list) do if g == accent then return list end end
        list[#list + 1] = accent
    end
    return list
end

-- The smaller source colors the zone rule falls back on (zone_choice): groups outside `candidates` the source shows on
-- at least ACCENT_SOURCE_BIG of itself (no speck), largest first.
local function zone_minor(source, candidates)
    local list = {}
    for _, g in ipairs(source.groups) do
        local listed = false
        for _, c in ipairs(candidates) do if c == g then listed = true end end
        if g.share >= ACCENT_SOURCE_BIG and not listed then list[#list + 1] = g end
    end
    return list
end

-- Whether candidate g may be picked by CIELAB distance (hue) for a zone with cloth (z.cloth: its border on rows that
-- are no design zones): it reads against half of that cloth too, so a zone does not take its cloth's color while
-- reading against its outline alone (Strength in Our Arms' stripe on the CW-4 Arctic Ranger, render 2026-10-07).
local function on_cloth(g, z, hue)
    if not (hue and z.cloth) then return true end
    local good, total = zone_reads(g.L, z.cloth, z.parts, z.plan, ZONE_READ, g)
    return 2 * good >= total
end

-- The candidate reading against the most of a zone's border (z: {around, cloth, parts, plan, order, mean}; hue: by
-- CIELAB distance, on_cloth; ties: the order kept, then the earlier): it and its border cells read.
local function zone_pick(candidates, z, hue)
    local best, best_good, best_same
    for _, g in ipairs(candidates) do
        if on_cloth(g, z, hue) then
            local good = zone_reads(g.L, z.around, z.parts, z.plan, ZONE_READ, hue and g)
            local same = (g.L >= z.mean) == z.order
            if not best or good > best_good or (good == best_good and same and not best_same) then
                best, best_good, best_same = g, good, same
            end
        end
    end
    return best, best_good
end

-- The source color a lost zone or emblem takes (z: see zone_pick; total: its border cells), or nil, the first that
-- reads against half its border: the candidates' pick by lightness; their pick by CIELAB distance (on_cloth); the
-- smaller source colors' (minor) pick by lightness. The UF-50 Bloodhound's red and black share a lightness (L 21.1 and
-- 20.8), so none of its colors read by lightness against the other: its red took the Pillars of Freedom's black and red
-- alike (the red bars lost), and the Judgment Day's, Liberty's Herald's and Fre Liberam's marks went back to their own
-- colors on its black (user, 2026-10-07: not recolored). Black reads against red, red against black; Liberty's
-- Herald's chevron, on black cloth above and red below, takes the Bloodhound's 1.8% silver.
-- A design drawn by lightness: its own lightness and its border's at least STRONG_GAP apart (z.strong; lost_tone). It
-- never takes a color reading by hue alone: Proof of Faultless Virtue's chevrons and skull took the Bloodhound's black
-- on its red, the same lightness, and the cape read plain red (independent review 1 2026-10-14; the user chose
-- "readable by lightness", knowing it changes the agreed Judgment Day x Bloodhound marks the same way).
local STRONG_GAP = 2 * ZONE_READ
local function zone_choice(candidates, minor, z, total)
    local best, good = zone_pick(candidates, z, false)
    if best and 2 * good >= total then return best end
    if not z.strong then
        best, good = zone_pick(candidates, z, true)
        if best and 2 * good >= total then return best end
    end
    best, good = zone_pick(minor, z, false)
    if best and 2 * good >= total then return best end
    return nil
end

-- A design drawn by lightness (z.strong) that no source color keeps readable takes a neutral tone of its planned
-- border, LOST_TONE apart, its own light/dark order kept where that fits; key: the source color it is named after (the
-- first of the candidates). v1.5: Proof of Faultless Virtue's design went the FS-38 Eradicator's olive like its cloth.
local LOST_TONE = 30.0
local function lost_tone(z, key)
    local L = z.order and z.mean + LOST_TONE or z.mean - LOST_TONE
    if L < 8 or L > 92 then L = z.order and z.mean - LOST_TONE or z.mean + LOST_TONE end
    return {L = math.min(math.max(L, 8), 92), a = 0.0, b = 0.0, rep = {key = key}}
end

-- Zone p's rows take source group `best`, or (best nil) keep their own colors.
local function apply_zone(mapping, p, best)
    for _, row in ipairs({p.base or false, p.tint or false}) do
        if row then -- the row fits through its own response (a cape's borrowed one), as every planned row does
            mapping[row.key] = best and {source = best.rep.key, kind = 'zone', L = best.L, a = best.a, b = best.b,
                                         cal = row.cal} or nil
        end
    end
end

-- The part of a zone's border on rows that are no design zones (its cloth), or nil when it borders none.
local function cloth_of(around, zones)
    local cloth
    for q = 0, 4 do
        if around[q] and not zones[q] then
            cloth = cloth or {}
            cloth[q] = around[q]
        end
    end
    return cloth
end

-- One zone kept readable in mapping (see above; rule: {candidates, minor, zones, group_of, taken}): 'picked' (a source
-- color), 'kept' (its own colors), 'lost' (nothing reads), or nil (it did not read before, or still reads).
local function keep_zone(mapping, z, around, parts, rule)
    local p = parts[z]
    local L0 = zone_lightness(p, nil)
    local good, total, mean0 = zone_reads(L0, around, parts, nil, ZONE_READ)
    if total == 0 or 2 * good < total then return nil end
    local mean1
    good, total, mean1 = zone_reads(zone_lightness(p, mapping), around, parts, mapping, ZONE_LOST)
    if 2 * good >= total then return nil end
    local zone = {around = around, cloth = cloth_of(around, rule.zones), parts = parts, plan = mapping,
                  order = L0 >= mean0, mean = mean1, strong = math.abs(L0 - mean0) >= STRONG_GAP}
    local group = rule.group_of[p.base or p.tint]
    local taken = group and rule.taken[group]
    local best = taken and zone_choice({taken}, rule.none, zone, total)
    best = best or zone_choice(rule.candidates, rule.minor, zone, total)
    if best then
        apply_zone(mapping, p, best)
        if group and not taken then rule.taken[group] = best end
        return 'picked'
    end
    if 2 * zone_reads(L0, around, parts, mapping, ZONE_READ) >= total then
        apply_zone(mapping, p, nil)
        return 'kept'
    end
    -- the lost tone for a zone bordered mostly by cloth: one bordered by another zone reads with it as one shape (a
    -- stripe and its outline, Strength in Our Arms)
    local cloth_cells = 0
    if zone.cloth then
        local _, cells = zone_reads(L0, zone.cloth, parts, mapping, ZONE_READ)
        cloth_cells = cells
    end
    if zone.strong and 2 * cloth_cells >= total then
        apply_zone(mapping, p, lost_tone(zone, rule.candidates[1].rep.key))
        return 'picked'
    end
    return 'lost'
end

-- mapping (Matcher.plan's, of a cape item) with its design zones kept readable; zones: src/capes.lua zones, tint_of: the
-- cape's {[cape LUT] = material LUT} or nil. Changes mapping in place; returns it and {picked, kept, lost} (how many
-- zones took a source color, kept their own colors, or read against nothing; diagnostics).
function Zones.cape_zones(mapping, target, source, zones, tint_of)
    local parts = zone_parts(target, tint_of)
    local order = {}
    for z in pairs(zones) do
        local p = parts[z]
        if p then
            local area = 0.0
            if p.base then area = area + p.base.tex_area end
            if p.tint then area = area + p.tint.tex_area end
            order[#order + 1] = {zone = z, area = area}
        end
    end
    table.sort(order, function(x, y)
        if x.area ~= y.area then return x.area > y.area end
        return x.zone < y.zone
    end)
    local candidates = zone_candidates(source)
    local rule = {candidates = candidates, minor = zone_minor(source, candidates), none = {}, zones = zones,
                  group_of = {}, taken = {}}
    for i, g in ipairs(target.groups) do
        for _, row in ipairs(g.rows) do rule.group_of[row] = i end
    end
    local outcomes = {picked = 0, kept = 0, lost = 0}
    for _, entry in ipairs(order) do
        local outcome = keep_zone(mapping, entry.zone, zones[entry.zone], parts, rule)
        if outcome then outcomes[outcome] = outcomes[outcome] + 1 end
    end
    return mapping, outcomes
end

-- The emblems of a cape (src/capes.lua emblems: emblem-sheet layers, their colors the decal sheet's) kept readable
-- over the cloth under them as mapping colors it (Zones.cape_zones applied first): one that read against half that
-- cloth (lightness contrast >= ZONE_READ) and no longer reads against half of it (< ZONE_LOST) takes the source color
-- reading against the most of it (zone_choice: by lightness, else by CIELAB distance), when that reads against half
-- (src/recolor.lua recolors its sheet cell);
-- else it stays, lost. The B-01 Tactical's dark gave the Drape of Glory's cloth its dark grey emblem's lightness and
-- the emblem vanished (user, image review 2026-10-07). Emblems go from the most cells. Returns {[emblem index] =
-- {source, L, a, b}} and {picked, lost} (diagnostics; match12.cape_emblems).
-- One emblem (see below): 'picked' and the source color it takes, 'lost', or nil (it did not read before, or still
-- reads).
local function keep_emblem(e, parts, mapping, candidates, minor)
    local good, total, mean0 = zone_reads(e.L, e.around, parts, nil, ZONE_READ)
    if total == 0 or 2 * good < total then return nil end
    local mean1
    good, total, mean1 = zone_reads(e.L, e.around, parts, mapping, ZONE_LOST)
    if 2 * good >= total then return nil end
    local z = {around = e.around, parts = parts, plan = mapping, order = e.L >= mean0, mean = mean1,
               strong = math.abs(e.L - mean0) >= STRONG_GAP}
    local best = zone_choice(candidates, minor, z, total) or (z.strong and lost_tone(z, candidates[1].rep.key))
    if best then return 'picked', {source = best.rep.key, L = best.L, a = best.a, b = best.b} end
    return 'lost'
end

function Zones.cape_emblems(mapping, target, source, emblems, tint_of)
    local picks, outcomes = {}, {picked = 0, lost = 0}
    if not emblems or #emblems == 0 then return picks, outcomes end
    local parts = zone_parts(target, tint_of)
    local order = {}
    for i = 1, #emblems do order[i] = i end
    table.sort(order, function(x, y)
        if emblems[x].cells ~= emblems[y].cells then return emblems[x].cells > emblems[y].cells end
        return x < y
    end)
    local candidates = zone_candidates(source)
    local minor = zone_minor(source, candidates)
    for _, i in ipairs(order) do
        local outcome, pick = keep_emblem(emblems[i], parts, mapping, candidates, minor)
        if outcome then outcomes[outcome] = outcomes[outcome] + 1 end
        picks[i] = pick
    end
    return picks, outcomes
end

if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({Zones.attach, zone_parts, row_linear, zone_lightness, apart, border_row, zone_reads,
        zone_candidates, zone_minor, on_cloth, zone_pick, zone_choice, lost_tone, apply_zone, cloth_of, keep_zone, Zones.cape_zones,
        keep_emblem, Zones.cape_emblems}) do
        jit.off(fn, true)
    end
end

return Zones
end)()
local Variety = (function()
-- Match Your Colors: an armor never left in one color (v1.5). The user's rule (2026-10-14): "armors should not _ever_
-- be dominated entirely by a single color. No matter the circumstance, there should always be secondary and accenting
-- colors", and they should match the source ("I fear certain colors will clash harshly"): from the source's palette
-- first, a tone of its main color when it has one, the armor's own accent only when it already matches the source. The
-- SA-25 Steel Trooper took one helmet color on 94-100% of its paint for every helmet, plates, coat, undersuit and its
-- prosthetic arm alike (end-user report 2026-10-14).
--
-- An armor's plan (Matcher.plan; the cape split, src/schemes.lua) is dominated when one design color (a source color,
-- or a target group's own) covers DOMINANT_SHARE of the paint that shows and less than SECOND_MIN of it reads apart
-- from that color (CIE76 >= APART). Then that color's rows take roles: hard armor parts and a coat keep it; clothing
-- (soft rows of undergarment pieces) takes the secondary; gear (small soft armor parts, hard parts of undergarment
-- pieces) the dark; colored trims the accent; and while still too little reads apart, the darkest main parts up to
-- DARKEST_SHARE take the darker of secondary and dark. The secondary is always a color of the source: a source with no
-- muted color of its own covering SECOND_MIN_SHARE of it apart from that color leaves the plan as made (user, independent
-- review 1 2026-10-14: a muted shade of the accent's hue "seems to come from nowhere", the published look was better: the
-- PH-9 Predator's red beret gave clothing a dusty pink, a lemon cape an olive; the GS-17 Frontier Marshal's 6.5% tan face
-- mask dressed a whole B-01 Tactical in mustard). A prosthetic limb (PROSTHETIC_LUTS) is no plate: on every armor plan
-- it takes the source's dark muted color, else keeps its own. Mirrored in research/match12.py balance. Nothing here runs
-- per frame.
local Variety = {}

local de2000, palette_of, source_accent, identity, is_structure, ACCENT_C, MAIN_COLOR, pattern_plan
-- Set once with the matcher's functions and constants (src/addon.lua and the tests, after Matcher.use).
function Variety.attach(Matcher, colour)
    de2000 = colour.de2000
    palette_of, source_accent, identity = Matcher.palette_of, Matcher.source_accent, Matcher.identity
    pattern_plan = Matcher.pattern_plan
    is_structure, ACCENT_C, MAIN_COLOR = Matcher.is_structure, Matcher.ACCENT_C, Matcher.MAIN_COLOR
    Matcher.balance = Variety.balance
end

Variety.DOMINANT_SHARE, Variety.SECOND_MIN, Variety.APART = 0.85, 0.10, 15.0
-- a coat: a LUT whose soft rows outside undergarment pieces show on this share of the paint; the darkest main parts
-- re-colored at most; the smallest source color an accent may come from; the armor's own accent kept within KEEP_DE
-- (CIEDE2000) of the source
Variety.COAT_SHARE, Variety.DARKEST_SHARE, Variety.ACCENT_MIN_SHARE = 0.10, 0.25, 0.005
Variety.KEEP_DE = 8.0
-- the smallest share of the source a secondary may come from (user, review 1 2026-10-14); a dark neutral one (black,
-- dark grey: look under DARK_NEUTRAL_L, model chroma under DARK_NEUTRAL_C) from DARK_SECOND_SHARE: black clothing is no
-- color from nowhere, and the CE-74 Breaker's black (7.7%) keeps the SA-25 Steel Trooper's undersuit black (the ticket)
Variety.SECOND_MIN_SHARE, Variety.DARK_SECOND_SHARE = 0.10, 0.05
Variety.DARK_NEUTRAL_L, Variety.DARK_NEUTRAL_C = 35.0, 8.0
-- an armor of one row over this share of what shows is left as planned (a row takes one color)
Variety.ROW_MAX = 0.90
-- a role color's row keeps at most this much of its lightness offset from its group (src/schemes.lua ROLE_TONE)
Variety.ROLE_TONE, Variety.TONE_UP = 6.0, 2.0
-- the prosthetic arm and leg of the SA-12 Servo-Assisted, SA-25 Steel Trooper and SA-32 Dynamo (Steam build 25480438)
Variety.PROSTHETIC_LUTS = {['5789f549cead6c3d'] = true}
-- a dark muted source color a prosthetic takes: under this lightness (look)
Variety.PROSTHETIC_DARK_L = 40.0

local function chroma(a, b) return math.sqrt(a * a + b * b) end
local function apart(x, y)
    local dL, da, db = x.L - y.L, x.a - y.a, x.b - y.b
    return dL * dL + da * da + db * db >= Variety.APART * Variety.APART
end
-- A source group's color as goals aim at it (a cape's look: src/matcher.lua gL).
local function color_of(g) return {L = g.gL or g.L, a = g.ga or g.a, b = g.gb or g.b, g = g} end
local function muted(g) return chroma(g.ma, g.mb) < ACCENT_C end

-- The plan's colors over what shows, by row in group then row order: {row, group, key (its source, a tone of it by
-- role, or its group's index when kept), L, a, b, share}. A band's row is keyed by the source color whose paint it
-- shows (src/matcher.lua tint_bands, m.shows): the SA-04 Combat Technician's band took the CE-35 Trench Engineer's
-- orange, its main color, while paired with its grey.
local function cell_of(plan, g, gi, row, paint_area)
    local m, share = plan[row.key], row.area / paint_area
    if not m then return {row = row, group = g, key = gi, L = row.L, a = row.a, b = row.b, share = share} end
    local key = m.shows or m.tone and m.source .. '/' .. m.tone or m.source
    return {row = row, group = g, key = key, L = m.L, a = m.a, b = m.b, share = share}
end
function Variety.cells(plan, t)
    local cells = {}
    for gi, g in ipairs(t.groups) do
        for _, row in ipairs(g.rows) do
            if row.area > 0 then cells[#cells + 1] = cell_of(plan, g, gi, row, t.paint_area) end
        end
    end
    return cells
end

-- The share of cells apart from color `mean`.
local function distinct_of(cells, mean)
    local distinct = 0.0
    for _, c in ipairs(cells) do if apart(c, mean) then distinct = distinct + c.share end end
    return distinct
end

-- The target's patterns the pattern plan leaves in their own color (Matcher.pattern_plan): parts the armor shows as
-- they are.
function Variety.kept_patterns(plan, t, s)
    local kept, planned = {}, pattern_plan(t, s, plan)
    for _, p in ipairs(t.patterns or {}) do
        if not planned[p.pattern] and p.share > 0 then kept[#kept + 1] = p end
    end
    return kept
end

-- The dominant design color of cells: its key, share and mean color (by share), and the share apart from it, both
-- shares of the paint the cells cover plus the kept patterns (Variety.kept_patterns) that read apart from that color;
-- nil when nothing shows. Patterns the plan recolors and kept ones close to the color stay out. The SA-04 Combat
-- Technician's cells cover 85% of its paint (its pattern takes the helmet's colors): the CE-35 Trench Engineer's
-- orange on 83% of it (its 68% and its band, cell_of) never reached DOMINANT_SHARE and the armor read one solid orange
-- (user 2026-10-15: "still bugged ... sorely stuck out"). The I-09 Heatseeker's own black pattern, 22.5% of it, keeps
-- it apart from the CW-36 Winter Warrior's white (user: its published look "was better"). Colors close to each other
-- but of different keys stay apart: counting every cell within APART as the dominant color balanced 680 more plans and
-- split two greys of one helmet by a shade it does not have (the SC-15 Drone Master's jumpsuit near-white from the
-- SR-64 Cinderblock; user: "clearly being dominated by a non-dominant color").
function Variety.dominance(cells, kept)
    local by, order, total = {}, {}, 0.0
    for _, c in ipairs(cells) do
        local d = by[c.key]
        if not d then
            d = {key = c.key, share = 0.0, L = 0.0, a = 0.0, b = 0.0}
            by[c.key], order[#order + 1] = d, d
        end
        d.share, d.L, d.a, d.b = d.share + c.share, d.L + c.share * c.L, d.a + c.share * c.a, d.b + c.share * c.b
        total = total + c.share
    end
    local top
    for _, d in ipairs(order) do if not top or d.share > top.share then top = d end end
    if not top or top.share <= 0 then return nil end
    local mean = {L = top.L / top.share, a = top.a / top.share, b = top.b / top.share}
    local apart_kept = 0.0
    for _, p in ipairs(kept or {}) do if apart(p, mean) then apart_kept = apart_kept + p.share end end
    local all = total + apart_kept
    return top.key, top.share / all, mean, (distinct_of(cells, mean) + apart_kept) / all
end

-- A tone of color c: dL lighter (darker when negative; the other way when that leaves 12 to 90), chroma times k.
local function tone(c, dL, k)
    local L = c.L + dL
    if L < 12 or L > 90 then L = c.L - dL end
    return {L = math.min(math.max(L, 12), 90), a = c.a * k, b = c.b * k, derived = true}
end

-- The source's secondary and dark colors for main color `main`: its largest muted palette color apart from main
-- covering SECOND_MIN_SHARE of it (DARK_SECOND_SHARE a dark neutral) (a vivid color on clothing is the agreed vivid guard's case: the PH-9 Predator's red
-- beret, 42% of it, turned whole armors red; vivid colors reach trims as the accent; no bare metal either, as cloth never
-- turns into metal: the Cowboy Hat's 7% silver badge made the B-01 Tactical's jacket light grey, review renders
-- 2026-10-14), else none (nil: the plan stays as made); and its darkest muted palette color apart from main (its
-- structure counting, any share), else a tone of main 25 L darker (6 on a dark main) at a third of the chroma.
local function second_share(g, c)
    if c.L < Variety.DARK_NEUTRAL_L and chroma(g.ma, g.mb) < Variety.DARK_NEUTRAL_C then
        return Variety.DARK_SECOND_SHARE
    end
    return Variety.SECOND_MIN_SHARE
end
local function palette_second_dark(source, main)
    local second, dark
    for _, g in ipairs(palette_of(source)) do
        local c = color_of(g)
        if g ~= main.g and not g.hood and muted(g) and apart(c, main) then
            if not second and not g.rep.metal and g.share >= second_share(g, c)
                and (source.suit_paint or not is_structure(g)) then
                second = c
            end
            if not dark or c.L < dark.L then dark = c end
        end
    end
    return second, dark
end
local function second_and_dark(source, main)
    local second, dark = palette_second_dark(source, main)
    if not second then return nil end
    return second, dark or tone(main, main.L >= 40 and -25 or -6, 0.33)
end

-- The source's accent for main and second: its accent (Matcher's source_accent) apart from both, else its most
-- saturated color of ACCENT_MIN_SHARE or more apart from both (chroma x sqrt(share)), else nil.
local function accent_of(source, main, second)
    local a = source_accent(source)
    if a and a ~= main.g then
        local c = color_of(a)
        if apart(c, main) and apart(c, second) then return c end
    end
    local best, score = nil, -1.0
    for _, g in ipairs(source.groups) do
        local c = color_of(g)
        local s = chroma(g.ma, g.mb) * math.sqrt(g.share)
        if g ~= main.g and not g.hood and g.share >= Variety.ACCENT_MIN_SHARE and apart(c, main) and apart(c, second)
            and s > score then
            best, score = c, s
        end
    end
    return best
end

-- Whether target group g's own color matches a color of the source's palette (CIEDE2000 under KEEP_DE).
local function matches_palette(g, source)
    for _, p in ipairs(palette_of(source)) do
        local c = color_of(p)
        if de2000(g.L, g.a, g.b, c.L, c.a, c.b) < Variety.KEEP_DE then return true end
    end
    return false
end

-- The LUTs whose soft rows outside undergarment pieces show on COAT_SHARE of the paint (a coat: main, not gear).
local function coats_of(cells)
    local share, out = {}, {}
    for _, c in ipairs(cells) do
        local row = c.row
        if row.mode >= 0.5 and row.under < 0.5 * row.area then share[row.lut] = (share[row.lut] or 0.0) + c.share end
    end
    for lut, s in pairs(share) do out[lut] = s >= Variety.COAT_SHARE end
    return out
end

-- A cell's role on a dominated armor: 'accent' (a colored trim), 'main' (hard armor parts, a coat), 'second'
-- (clothing) or 'dark' (gear).
local function role_of(c, coats)
    local g, row = c.group, c.row
    if chroma(g.ma, g.mb) >= ACCENT_C and g.share < MAIN_COLOR then return 'accent' end
    local under = row.under >= 0.5 * row.area
    local hard = row.mode < 0.5
    if not under and (hard or coats[row.lut]) then return 'main' end
    if under and not hard then return 'second' end
    return 'dark'
end

-- Row c.row takes role color `color` (kind: 'pair' or 'accent'): its goal the color with its own lightness offset
-- from its group (at most ROLE_TONE), through its own response; source: the color's source row, else main_key (a tone
-- of the main color: goal.tone names its role).
local function assign(plan, c, color, kind, main_key, role)
    local row = c.row
    local up = color.derived and Variety.TONE_UP or Variety.ROLE_TONE -- a tone stays the tone it was made
    local offset = math.max(-Variety.ROLE_TONE, math.min(up, row.L - c.group.L))
    local L = color.L + offset
    plan[row.key] = {source = color.g and color.g.rep.key or main_key, kind = kind, L = L, a = color.a, b = color.b,
                     cal = row.cal, tone = color.derived and role or nil}
    c.L, c.a, c.b = L, color.a, color.b
end

-- Prosthetic rows (every armor plan): the source's darkest muted color under PROSTHETIC_DARK_L, else their own.
local function prosthetics(plan, cells, source)
    local dark
    for _, g in ipairs(palette_of(source)) do
        local c = color_of(g)
        if not g.hood and muted(g) and c.L < Variety.PROSTHETIC_DARK_L and (not dark or c.L < dark.L) then dark = c end
    end
    for _, c in ipairs(cells) do
        if Variety.PROSTHETIC_LUTS[c.row.lut] then
            if dark then
                assign(plan, c, dark, 'pair', dark.g.rep.key, 'prosthetic')
            else
                plan[c.row.key] = nil
                c.L, c.a, c.b = c.row.L, c.row.a, c.row.b
            end
        end
    end
end

-- The darkest of cells, up to DARKEST_SHARE of the paint (the darkest one alone up to half of it: the B-01 Tactical's
-- jacket is one row), take `color` (role: its tone's name).
local function darken(plan, cells, color, main_key, role)
    table.sort(cells, function(x, y)
        if x.row.L ~= y.row.L then return x.row.L < y.row.L end
        return x.row.key < y.row.key
    end)
    local taken = 0.0
    for _, c in ipairs(cells) do
        if taken + c.share > (taken == 0 and 0.5 or Variety.DARKEST_SHARE) then break end
        assign(plan, c, color, 'pair', main_key, role)
        taken = taken + c.share
    end
end

-- Whether a plan's dominance (Variety.dominance) leaves it in one color.
local function dominated(key, share, distinct)
    return key ~= nil and share >= Variety.DOMINANT_SHARE and distinct < Variety.SECOND_MIN
end

-- Still dominated by a role color (the B-01 Tactical is mostly clothing: its secondary covered 86% with the O-2 Heavy
-- Operator): the darkest cells of that color take the first of `colors` reading apart from it, else a tone of it.
local function settle(plan, t, colors, main_key, kept)
    local cells = Variety.cells(plan, t)
    local key, share, mean, distinct = Variety.dominance(cells, kept)
    if not dominated(key, share, distinct) then return end
    local pick = tone(mean, mean.L >= 45 and -18 or 15, 0.5)
    for i = #colors, 1, -1 do
        if apart(colors[i], mean) then pick = colors[i] end
    end
    local list = {}
    for _, c in ipairs(cells) do
        if c.key == key and not Variety.PROSTHETIC_LUTS[c.row.lut] then list[#list + 1] = c end
    end
    if pick then darken(plan, list, pick, main_key, 'settle') end
end

-- The dominant color of armor t's plan, as given (a prosthetic counts as the color it was given) and as the prosthetic
-- rule leaves it: its cells, key, mean and kept patterns (Variety.kept_patterns), or nil when the plan is not dominated.
local function dominant(plan, t, s)
    local cells, kept = Variety.cells(plan, t), Variety.kept_patterns(plan, t, s)
    local key, share, mean, distinct = Variety.dominance(cells, kept)
    prosthetics(plan, cells, s)
    if not dominated(key, share, distinct) then
        cells = Variety.cells(plan, t)
        key, share, mean, distinct = Variety.dominance(cells, kept)
        if not dominated(key, share, distinct) then return nil end
    end
    return cells, key, mean, kept
end

-- Whether one row shows on more than ROW_MAX of the armor (it cannot be split: a dark armor of one row).
local function one_row(cells)
    for _, c in ipairs(cells) do if c.share > Variety.ROW_MAX then return true end end
    return false
end

-- The role colors of a dominated plan (key, mean: Variety.dominance's): {main, main_key, second, dark, accent}; nil when
-- the source has no secondary of its own.
local function role_colors(s, key, mean)
    local main_g
    for _, g in ipairs(s.groups) do if g.rep.key == key then main_g = g end end
    local main = {L = mean.L, a = mean.a, b = mean.b, g = main_g}
    local second, dark = second_and_dark(s, main)
    if not second then return nil end
    return {main = main, main_key = type(key) == 'string' and key or (identity(s) or s.groups[1]).rep.key,
            second = second, dark = dark, accent = accent_of(s, main, second)}
end

-- A colored trim's cell: the accent; else its own color when it already matches the source; else a tone of main.
local function accent_cell(plan, c, k, s)
    if k.accent then return assign(plan, c, k.accent, 'accent', k.main_key, 'accent') end
    if matches_palette(c.group, s) then
        plan[c.row.key] = nil
        c.L, c.a, c.b = c.row.L, c.row.a, c.row.b
        return
    end
    assign(plan, c, tone(k.main, k.second.L > k.main.L and -25 or 25, 1.0), 'accent', k.main_key, 'accent')
end

-- One cell of the dominant color in its role (role_of; k: role_colors).
local function play_role(plan, c, role, k, s)
    if role == 'second' or role == 'dark' then
        assign(plan, c, k[role], 'pair', k.main_key, role)
    elseif role == 'accent' then
        accent_cell(plan, c, k, s)
    end
end

-- The shares of the main, second and dark roles (cells in order).
local function role_shares(cells, roles)
    local share = {main = 0.0, second = 0.0, dark = 0.0}
    for i, c in ipairs(cells) do
        local role = roles[i]
        if share[role] then share[role] = share[role] + c.share end
    end
    return share
end

-- How far the main, second and dark shares of a split are from the source's (summed absolute difference of the
-- normalized shares).
local function deviation(m, s2, s3, src)
    local total, stotal = m + s2 + s3, src[1] + src[2] + src[3]
    if total <= 0 or stotal <= 0 then return 0.0 end
    return math.abs(m / total - src[1] / stotal) + math.abs(s2 / total - src[2] / stotal)
        + math.abs(s3 / total - src[3] / stotal)
end

-- The roles of the dominant color's cells (role_of). A secondary lighter than the main color does not take the
-- clothing when the main color keeping it brings the armor's proportions of main, second and dark closer to the
-- source's: a light minor color of the source read as the armor's main (user 2026-10-15: "clearly being dominated by a
-- non-dominant color"; the FS-23 Battle Master's 20% light grey took the DP-00 Tactical's coat, 64% of it). A darker
-- secondary keeps the clothing, as dark undersuits do (the SA-25 Steel Trooper's dark suit under the TR-40 Gold
-- Eagle's yellow, passed by the user). The dark role (gloves, straps) stays dark; it counts as the secondary when the
-- source has one dark color.
local function group_share(g) return g and g.share or 0.0 end
-- Whether the clothing keeping the main color brings the role shares closer to the source's main, second and dark.
local function main_keeps_clothing(share, k)
    local same = k.dark.g ~= nil and k.dark.g == k.second.g
    local src = {group_share(k.main.g), group_share(k.second.g), 0.0}
    local with_second, dark = 0.0, share.dark
    if same then
        with_second, dark = share.dark, 0.0
    else
        src[3] = group_share(k.dark.g)
    end
    local kept = deviation(share.main, share.second + with_second, dark, src)
    return deviation(share.main + share.second, with_second, dark, src) < kept
end
local function roles_of(cells, key, coats, k)
    local roles = {}
    for i, c in ipairs(cells) do
        if c.key == key and not Variety.PROSTHETIC_LUTS[c.row.lut] then roles[i] = role_of(c, coats) end
    end
    if k.second.L > k.main.L and main_keeps_clothing(role_shares(cells, roles), k) then
        for i, role in pairs(roles) do if role == 'second' then roles[i] = 'main' end end
    end
    return roles
end

-- Too little apart after the roles: the darkest main parts take the darker of secondary and dark reading apart from
-- main, else the secondary when it does (a charcoal of a black does not: then nothing).
local function shade(plan, cells, roles, k)
    local darker = k.second.L < k.dark.L and k.second or k.dark
    local pick = apart(darker, k.main) and darker or apart(k.second, k.main) and k.second or nil
    if not pick then return end
    local mains = {}
    for i, c in ipairs(cells) do if roles[i] == 'main' then mains[#mains + 1] = c end end
    darken(plan, mains, pick, k.main_key, 'shade')
end

-- The plan of armor item t against source s (Matcher.plan's, or the cape split's), balanced in place (see above).
-- Returns plan and whether it was dominated. A source without colors gives none to balance with: the armor keeps its
-- own, as in v1.4 (a v1.4 analysis of the Cowboy Hat had no rows and its plan failed here, review renders 2026-10-14).
function Variety.balance(plan, t, s)
    if not (s.groups and s.groups[1]) then return plan, false end
    local cells, key, mean, kept = dominant(plan, t, s)
    if not cells then return plan, false end
    if one_row(cells) then return plan, true end
    local k = role_colors(s, key, mean)
    if not k then return plan, true end -- no color of the source to balance with: as made
    local roles = roles_of(cells, key, coats_of(cells), k)
    for i, c in ipairs(cells) do
        if roles[i] then play_role(plan, c, roles[i], k, s) end
    end
    if distinct_of(cells, mean) < Variety.SECOND_MIN then shade(plan, cells, roles, k) end
    for _ = 1, 2 do settle(plan, t, {k.dark, k.main, k.second}, k.main_key, kept) end -- a second color may lead once
    return plan, true
end

if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({Variety.attach, chroma, apart, color_of, muted, cell_of, Variety.cells, distinct_of,
        Variety.kept_patterns, Variety.dominance, tone, second_share, palette_second_dark, second_and_dark, accent_of, matches_palette, coats_of, role_of,
        assign, prosthetics, darken, dominated, settle, dominant, one_row, role_colors, accent_cell, play_role, role_shares, deviation, group_share, main_keeps_clothing, roles_of,
        shade,
        Variety.balance}) do
        jit.off(fn, true)
    end
end

return Variety
end)()
