    {id = 'seaf', text = 'scheme.seaf', archive = '792b2a2ba11ae85d', lut = '493b5a6a30e49de5', rows = {2, 1, 3},
     roles = 'material', looks = {[1] = {40.0, 0.0, 0.0}, [2] = {32.0, -1.0, -12.0}, [3] = {20.0, 0.0, 0.0}}},
