local Preview = (function()
-- Match Your Colors: the UI preview Helldivers: the local player's (the Armory's big CHARACTER view and the other UI
-- previews of the local player) and the squad cards of the loadout screen (src/lineup.lua), in the UiPreviewSystem's
-- player slots (Steam build 25480438, static research).
--
-- UiPreviewSystem [game + 0x347CE60]: occupied-slot count +50440 and bitmask +50444 (bit s); slot records
-- +49160 + 160 * s (s 0-3: players, by the player's UI slot; 4-7: thumbnail temporaries, never used here):
-- +8 body unit, +12 / +52 / +92 three arrays of 10 piece unit refs (the avatar record's layout: slot 0 helmet,
-- 1-9 armor), +132 animation, +136 body type, +140 armor kit, +144 helmet kit, +148 cape kit shown (a hovered item
-- included; KB ui-preview-system-armory-units). The Armory's slot is u32 [player manager + 948 + 32 * index]
-- (src/avatar.lua identity.ui_slot); a squad card's is its player's session slot (src/lineup.lua; KB
-- match-your-colors-squad-cards).
local ffi = require('ffi')
local band = require('bit').band

local Preview = {}

Preview.SYSTEM = 0x2E38190
Preview.MAX_SLOT = 3
Preview.RECORD_BYTES = 160
local SLOTS, GATE, UNITS = 49160, 50440, 12
-- The units compared: the 120 bytes of unit refs the recolor binds (src/avatar.lua Avatar.units), not the animation
-- word after them (v1.3 compared +12 to +135: a new animation alone rebound the preview's materials).
local UNITS_END = UNITS + 120
local BODY, ARMOR, HELMET, CAPE, KITS_END = 136, 140, 144, 148, 152
local MAX_OCCUPIED = 8
-- The read: slot 0's record to the weapon ring's tail; the compares run over 32-bit words of a record.
local GATE_OFFSET = GATE - SLOTS
local SPAN = GATE_OFFSET + 16
local WORDS = Preview.RECORD_BYTES / 4
local UNITS_W, UNITS_END_W, BODY_W, KITS_END_W = UNITS / 4, UNITS_END / 4, BODY / 4, KITS_END / 4
local BITS = {[0] = 1, 2, 4, 8}
local PLAYER_BITS = 15 -- slots 0-3

local function at(address) return ffi.cast('const uint8_t *', address) end
local function u32(p, o) return p[o] + p[o + 1] * 256 + p[o + 2] * 65536 + p[o + 3] * 16777216 end

-- Where the local player's preview lives: {system, slot, first (slot 0's record), record, units_at, bit}, or nil when
-- there is no preview system or the player has no UI slot. read: Avatar.reader.
function Preview.locate(read, game, ui_slot)
    if type(ui_slot) ~= 'number' or ui_slot < 0 or ui_slot > Preview.MAX_SLOT then return nil end
    local b = read(game + Preview.SYSTEM, 8)
    if not b then return nil end
    local system = u32(b, 0) + u32(b, 4) * 4294967296
    if system < 0x10000 or system >= 0x800000000000 then return nil end
    local where = {system = system, first = system + SLOTS}
    return Preview.retarget(where, ui_slot)
end

-- where moved to player slot `slot` (the local player's preview found in another slot: src/lineup.lua); where.
function Preview.retarget(where, slot)
    where.slot, where.record, where.bit = slot, where.first + Preview.RECORD_BYTES * slot, 2 ^ slot
    where.units_at = where.record + UNITS
    return where
end

-- The watch over the player slots: poll() reads the records of slots 0-3 and 4-7, the occupied count and mask and the
-- weapon preview ring's head and tail (16 bytes) in one read: the records end where the count begins, so the span
-- from slot 0's record to the ring's tail is contiguous (1,296 bytes; until the squad cards it read from the local
-- player's slot, as many bytes for slot 0). It returns the status of where.slot: 'absent' (slot free or unreadable),
-- 'kits' (the kits shown changed, or the slot appeared), 'units' (only its units changed) or 'same'; status(s) gives
-- each player slot's, changes how many slots showed, changed or went at this poll. kits() gives the helmet, armor, body
-- and cape where.slot showed at the last poll, slot_kits(s) any player slot's; ring_moved() whether the weapon ring's
-- head moved since the poll before (the game spawned or updated a preview weapon: src/weapons.lua Weapons.preview),
-- whatever the slot shows. No allocation per call.
function Preview.watch(memory, where)
    local first_at = at(where.first)
    local players = Preview.RECORD_BYTES * (Preview.MAX_SLOT + 1)
    local now, kept = ffi.new('uint8_t[?]', SPAN), ffi.new('uint8_t[?]', players)
    local gate_at, gate = at(where.first + GATE_OFFSET), ffi.new('uint8_t[16]')
    local now32, kept32 = ffi.cast('const uint32_t *', now), ffi.cast('const uint32_t *', kept)
    local present, statuses = {}, {}
    for s = 0, Preview.MAX_SLOT do present[s], statuses[s] = false, 'absent' end
    local head, moved = -1, false
    local self = {reads = 0, changes = 0}

    local function differs(base, first, last)
        for i = base + first, base + last - 1 do if now32[i] ~= kept32[i] then return true end end
        return false
    end

    -- Slot s at this poll (shown: its bit set): its status, its record kept when it changed.
    local function slot_status(s, shown)
        if not shown then
            if present[s] then self.changes = self.changes + 1 end
            present[s] = false
            return 'absent'
        end
        local base = WORDS * s
        local status = 'same'
        if not present[s] or differs(base, BODY_W, KITS_END_W) then
            status = 'kits'
        elseif differs(base, UNITS_W, UNITS_END_W) then
            status = 'units'
        end
        if status ~= 'same' then
            local offset = Preview.RECORD_BYTES * s
            ffi.copy(kept + offset, now + offset, Preview.RECORD_BYTES)
            self.changes = self.changes + 1
        end
        present[s] = true
        return status
    end

    -- The occupied count, mask and ring of bytes b at offset o: the mask (0 when the count is not believable).
    local function gate_of(b, o)
        local ring = u32(b, o + 8)
        moved, head = head >= 0 and ring ~= head, ring
        if u32(b, o) <= MAX_OCCUPIED then return u32(b, o + 4) end
        return 0
    end

    -- While no player slot showed at the last poll, the gate's 16 bytes alone (2026-10-17; v1.5 read the whole span,
    -- 1,296 bytes, every time): with no player slot shown now either, the records are not needed (every status
    -- 'absent', nothing kept), else the span is read as before on that frame.
    local function idle_poll()
        if not memory.read_into(gate_at, 16, gate) then
            moved = false
            return true
        end
        local saved_head = head
        if band(gate_of(gate, 0), PLAYER_BITS) == 0 then return true end
        head = saved_head -- the span's read below sets the ring again
        return false
    end

    function self.poll()
        self.reads, self.changes = self.reads + 1, 0
        if not (present[0] or present[1] or present[2] or present[3]) and idle_poll() then
            -- slots 0-3 (Preview.MAX_SLOT), written out: a 4-pass loop here would be a loop trace start that leaves
            statuses[0], statuses[1], statuses[2], statuses[3] = 'absent', 'absent', 'absent', 'absent'
            return statuses[where.slot]
        end
        local ok = memory.read_into(first_at, SPAN, now)
        local mask = 0
        if ok then
            mask = gate_of(now, GATE_OFFSET)
        else
            moved = false
        end
        for s = 0, Preview.MAX_SLOT do statuses[s] = slot_status(s, band(mask, BITS[s]) ~= 0) end
        return statuses[where.slot]
    end

    function self.status(s) return statuses[s] end

    function self.slot_kits(s)
        local o = Preview.RECORD_BYTES * s
        return u32(kept, o + HELMET), u32(kept, o + ARMOR), u32(kept, o + BODY), u32(kept, o + CAPE)
    end

    function self.kits() return self.slot_kits(where.slot) end

    function self.units_at(s) return where.first + Preview.RECORD_BYTES * s + UNITS end

    function self.ring_moved() return moved end

    -- The next poll reports 'kits' while where.slot is shown, as if it had just appeared (after it went unwatched).
    function self.reset() present[where.slot] = false end
    return self
end

-- Locating runs on few frames: interpreted. poll() is the per-frame check and stays compiled.
if type(jit) == 'table' and type(jit.off) == 'function' then
    jit.off(Preview.locate, true)
    jit.off(Preview.retarget, true)
end

return Preview
end)()
local Recolor = (function()
-- Match Your Colors: from the local player's kits to recolored materials.
--
-- A job (a coroutine resumed by the frame step with a time budget) reads the two kits from game memory,
-- analyses them from the game's files (src/kits.lua; kept for the session), plans the match
-- (src/matcher.lua) and builds the new LUT data: each planned row keeps its material and takes fitted colors
-- (src/transfer.lua); a planned pattern (v11.4) is a copy of the pattern texture with texel 0's color replaced.
-- The step then applies it in one frame through the bindings controller (Recolor.controller: src/bindings.lua,
-- attached to Recolor by Bindings.attach before any plan is applied).
local ffi = require('ffi')

local Recolor = {}

Recolor.OFF, Recolor.HELMET_FROM_ARMOR, Recolor.ARMOR_FROM_HELMET = 1, 2, 3
-- a plan's units without materials at its apply are tried again every PENDING_EVERY frames for PENDING_FRAMES
-- (controller settle)
Recolor.PENDING_EVERY, Recolor.PENDING_FRAMES = 4, 120
-- Helmet and Armor Match Cape: both items planned against the worn (or previewed) cape (cape_source_job).
Recolor.CAPE_SOURCE = 4
Recolor.RETIRE_FRAMES = 4
-- The emblem-sheet copies (Recolor.sheet_recipe, sheet_spec, c_buffer, SHEET_FORMAT, SHEET_CHUNK, SHEETS_KEPT) are
-- src/sheets.lua's, attached to Recolor (Sheets.attach) before any job runs.
local SLOTS = {[Recolor.HELMET_FROM_ARMOR] = {0, 0}, [Recolor.ARMOR_FROM_HELMET] = {1, 9}}
local LUT_WIDTH = 23
local HIGH = 4294967296

-- Match Materials: LUT row r of data (width columns) takes the finish of source row `key` ('lut:row' of the source
-- analysis): metallic (column 6 w, clipped to 0-1), no detail metallic controls (column 7: they follow the source's
-- detail and mesh; v1.0's whole-row copies drew chrome specks with them), the source's specular (column 8) and
-- roughness (column 10 x). Mode, detail layer and controls, colors, camo and tiling stay the target's. A cape's tint
-- row (source.tint_of: its cape LUT -> material LUT; a cape as the source) has its material row's finish.
-- A row that was paint (metallic under 0.5) taking a metal finish is at least METAL_ON_PAINT_ROUGH rough, the game's
-- median hard bare-metal roughness (1,083 rows by area: p25 and p50 0.30; research/scratch/v15/metal_rough_survey.lua):
-- the B-22 Model Citizen's mirror chrome (0.10, kept for parts made for it) on the FS-37 Ravager's quilted chest
-- reflected the Armory's lights as a white blotch and sparkle (independent review round 3, 2026-10-14).
Recolor.METAL_ON_PAINT_ROUGH = 0.30
function Recolor.apply_finish(data, width, r, source, key)
    local lut, row = key:match('^(%x+):(%d+)$')
    lut = lut and source.tint_of and source.tint_of[lut] or lut
    local spec = lut and source.luts[lut]
    if not spec then error('finish source ' .. tostring(key) .. ' not in the source analysis', 0) end
    local v, s = spec.values, tonumber(row) * spec.width * 4
    local t = r * width * 4
    local was_paint = data[t + 27] < 0.5
    data[t + 27] = math.min(math.max(v[s + 27], 0), 1)
    data[t + 28], data[t + 29], data[t + 30], data[t + 31] = 0, 0, 0, 0
    data[t + 32], data[t + 33], data[t + 34], data[t + 35] = v[s + 32], v[s + 33], v[s + 34], v[s + 35]
    data[t + 40] = v[s + 40]
    if was_paint and data[t + 27] >= 0.5 then data[t + 40] = math.max(data[t + 40], Recolor.METAL_ON_PAINT_ROUGH) end
end

-- A paint scheme's camo row onto LUT row r of data (width columns): its colors (base, detail, wear: columns 0, 2,
-- 5, 6 RGB) and its camo (camo colors and controls 16-19, camo extra 20 w, camo controls and layer 21, camo tiling
-- 22 w), from source row `key`. Mode, detail layer and controls, metallic, specular, roughness and the other w
-- channels stay the target's (a camo copy, src/schemes.lua; unfitted: the camo is several colors).
local COPY_RGB, COPY_ALL = {0, 2, 5, 6}, {16, 17, 18, 19, 21}
function Recolor.apply_copy(data, width, r, source, key)
    local lut, row = key:match('^(%x+):(%d+)$')
    local spec = lut and source.luts[lut]
    if not spec then error('copy source ' .. tostring(key) .. ' not in the source analysis', 0) end
    local v, s = spec.values, tonumber(row) * spec.width * 4
    local t = r * width * 4
    for _, c in ipairs(COPY_RGB) do
        for ch = 0, 2 do data[t + c * 4 + ch] = v[s + c * 4 + ch] end
    end
    for _, c in ipairs(COPY_ALL) do
        for ch = 0, 3 do data[t + c * 4 + ch] = v[s + c * 4 + ch] end
    end
