    -- A new plan is due (options, kits or the source changed): the next job slot plans the weapons again, and the
    -- Armory's preview weapon while one is shown (live 2026-10-15: mode changes left the preview in its first plan).
    function self.replan()
        if self.watch then self.dirty, self.changed = true, true end
        if self.preview then self.preview_dirty = true end
    end

    -- The resolve after a change: the same weapons and paints bound again at once, others a job. Another mod user's
    -- changed row is first checked to be still theirs (moved).
    local function settle(frame)
        if self.changed and moved() then return end
        local resolved = Weapons.resolve(m.read, Avatar.lookup, m.game, self.where, m.memory, copy)
        if not resolved then return end
        resolved = prepared(resolved)
        local sig = signature(resolved)
        self.resolved = resolved
        follow(resolved)
        if self.reload then self.reloads = self.reloads + 1 end
        self.changed, self.reload = false, false
        if sig == '' then -- no weapon (dead, or a loadout without any): nothing bound, nothing to watch
            return
        end
        if sig ~= self.sig or not controller.result or self.dirty then
            self.dirty, self.pending_sig = true, sig
            return
        end
        rebind(frame)
    end

    -- Every frame while on (busy: the avatar's chain check ran this frame; a resolve waits a frame then; every: the row
    -- read on this call whatever the frame, another mod user's watch turn, src/remote.lua). True when it resolved.
    function self.step(frame, busy, every)
        local watch = self.watch
        if not watch then return false end
        -- v1.5: the weapon in hand's LUT binding read every frame; its reload (the paint bound again) bound again the
        -- next frame. Replaced by the source lease (src/weapon_source.lua) and the record watch below.
        -- if self.entry and not watch.bound(self.entry, self.low, self.high) then self.reload = true end
        if self.record and watch.units_changed() then self.reload = true end
        if (every or frame % Loadout.ROW_FRAMES == Loadout.ROW_PHASE) and watch.row_changed() then self.changed = true end
        if busy or not (self.changed or self.reload) then return false end
        settle(frame)
        return true
    end

    -- The weapons' request for a job (src/addon.lua adds the options and kits), or nil when none is due.
    function self.request()
        if not self.dirty or not self.resolved then return nil end
        self.dirty = false
        local list = {}
        for slot = 1, 3 do
            if self.resolved.list[slot] then list[#list + 1] = self.resolved.list[slot] end
        end
        if #list == 0 then return nil end -- no weapon held (dead): nothing to plan
        return {weapons = list, sig = self.pending_sig or signature(self.resolved)}
    end

    -- A finished weapons job: applied when the weapons are still the ones planned (the bindings it made), else nil and
    -- a new job follows.
    function self.finish(result, request, frame)
        self.jobs = self.jobs + 1
        if request.sig ~= signature(self.resolved) then
            self.dirty = true
            return nil
        end
        local count = controller.apply(result, {list = self.resolved.list}, nil, frame)
        self.sig = result.action == 'apply' and request.sig or nil
        lease('apply')
        return count
    end

    -- Every CHECK_FRAMES frames: one recolored material per texture still holds its texture (an optic's spawn binds
    -- the underbarrel's paint again two frames later; static research); another mod user's row still theirs (moved:
    -- their row moved away leaves its old bytes, which then never change).
    function self.check(frame)
        if controller.probes > 0 and not controller.check() and controller.result and self.resolved then
            rebind(frame)
        end
        if shown.probes > 0 then self.check_shown(frame) end
        moved()
    end

    function self.collect(frame)
        if controller.retired[1] then controller.collect(frame) end
        if shown.retired[1] then shown.collect(frame) end
    end

    -- The Armory's weapon preview, read again after the UI gate saw its ring head move (the game spawned or updated a
    -- preview weapon: another weapon, an attachment, a paint scheme): the same weapon and customization bound again at
    -- once, another a job (preview_dirty), none (closed) its textures retired. Also read when an option changes while
    -- none is tracked (src/addon.lua weapons_option: Recolor Weapons turned on in the Armory); a slot whose unit is
    -- not alive (left from an earlier Armory visit) shows none.
    function self.preview_changed(frame)
        local now = Weapons.preview(m.read, m.game)
        if now and m.native.alive(now.unit) == 0 then now = nil end
        if not now then
            if self.preview then shown.restore(frame) end
            self.preview, self.preview_dirty = nil, false
            return
        end
        local applied = self.preview and self.preview.applied
        self.preview = {now = now, applied = applied}
        if applied == now.key and shown.result then
            shown.apply(shown.result, {list = {now}}, nil, frame)
        else
            self.preview_dirty = true
        end
    end

    -- The preview weapon's request (src/addon.lua adds the options and kits), or nil.
    function self.preview_request()
        local p = self.preview
        if not self.preview_dirty or not p then return nil end
        self.preview_dirty = false
        local w = {id = 0, name = p.now.name, unit = p.now.unit, units = p.now.units, ids = p.now.ids, overrides = {},
                   attachments = {}}
        return {weapons = {w}, sig = p.now.key}
    end

    -- A finished preview job: applied when the preview still shows that weapon and customization.
    function self.finish_preview(result, request, frame)
        local now = Weapons.preview(m.read, m.game)
        if not now or now.key ~= request.sig then
            self.preview_changed(frame)
            return 0
        end
        self.previews = self.previews + 1
        local count = shown.apply(result, {list = {now}}, nil, frame)
        self.preview = {now = now, applied = result.action == 'apply' and now.key or nil}
        return count
    end

    -- The preview's textures given back when its units are gone (the Armory closed without another preview).
    local function check_shown(frame)
        local b = shown.bindings[1]
        if b and m.native.alive(b.unit) == 0 then
            shown.restore(frame)
            self.preview = nil
        end
    end
    self.check_shown = check_shown

    -- Everything but the per-frame step runs on changes only: interpreted (no traces in the code cache every mod
    -- shares).
    if type(jit) == 'table' and type(jit.off) == 'function' then
        for _, fn in ipairs({signature, note_source, lease, release, prepared, follow, rebind, self.adopt, moved,
                             self.clear, self.replan, settle, self.request,
                             self.finish, self.check, self.collect, self.preview_changed,
                             self.preview_request, self.finish_preview, check_shown}) do
            jit.off(fn, true)
        end
    end
    return self
end

return Loadout
end)()
local Sheets = (function()
-- Match Your Colors: the emblem-sheet copies (moved from src/recolor.lua in v1.5; KB match-your-colors-cape-tint,
-- round 2). Attached to Recolor (Sheets.attach: Recolor.sheet_recipe, sheet_spec, c_buffer and the SHEET constants)
-- before any job runs; src/recolor.lua plans and binds them.
local ffi = require('ffi')

local Sheets = {}

Sheets.SHEETS_KEPT = 2 -- recolored sheets a session keeps ready (the bound one and the next)
Sheets.SHEET_FORMAT = 77 -- DXGI BC3 (src/texture.lua FORMAT_BC3): the decal sheets recolored
Sheets.SHEET_CHUNK = 262144 -- bytes of a sheet read between two pause points

-- Emblem sheets (KB match-your-colors-cape-tint, round 2). A cape emblem that would no longer read
-- (Matcher.cape_emblems) is recolored in a copy of the cape's decal sheet (Capes.recolor_sheet) bound on the
-- decal_sheet slot of its materials (src/engine.lua DECAL_SLOT, BC3 with its mip chain). A plan keeps only the
-- recipe (sheet_recipe); each job turns it into the sheet's data (sheet_spec: SHEETS_KEPT recipes kept, the original
-- bytes of the last sheet read kept by the pipeline), in buffers outside the Lua heap (the game's LuaJIT keeps every
-- Lua object below 2 GB, shared with the whole game: KB user-crash-report-2026-10-02), freed by the collector once
-- nothing references them (a texture keeps its data). About 5.6 MB per sheet; nothing here runs per frame.
local MALLOC_DECLARED = 'myc1_malloc_declared'
local function c_buffer(size)
    if not pcall(ffi.typeof, MALLOC_DECLARED) then
        ffi.cdef [[
            typedef struct myc1_malloc_declared { int unused; } myc1_malloc_declared;
            void *myc1_malloc(size_t size) __asm__("malloc");
            void myc1_free(void *pointer) __asm__("free");
        ]]
    end
    local raw = ffi.C.myc1_malloc(size)
    if raw == nil then error('no memory for a ' .. size .. '-byte sheet', 0) end
    return ffi.gc(ffi.cast('uint8_t *', raw), ffi.C.myc1_free)
end
Sheets.c_buffer = c_buffer

-- The bytes of a w x h BC3 mip chain of `mips` mips.
local function bc3_bytes(width, height, mips)
    local total = 0
    for m = 0, mips - 1 do
        local w, h = math.max(1, math.floor(width / 2 ^ m)), math.max(1, math.floor(height / 2 ^ m))
        total = total + math.max(1, math.floor((w + 3) / 4)) * math.max(1, math.floor((h + 3) / 4)) * 16
    end
    return total
end

-- A color shift rounded to SHIFT_STEP: the endpoints round to 5-6 bits, and a shift that differs in its last bits
-- (the reference's and the runtime's emblem colors agree to about 1e-12) could move one across a rounding edge.
Sheets.SHIFT_STEP = 1 / 1024
local function step(x) return math.floor(x / Sheets.SHIFT_STEP + 0.5) * Sheets.SHIFT_STEP end

-- The recipe of a cape plan's sheet: {name, width, height, mips, size, cells = {{rect, shift}}} for the emblems that
-- take a color (picks: Matcher.cape_emblems, by emblem index), in emblem order, a cell overlapping an earlier one left
-- out; nil when none takes one or its sheet is not a BC3 sheet.
-- Whether rect overlaps the rect of one of cells.
local function overlaps(cells, rect)
    for _, cell in ipairs(cells) do
        local r = cell.rect
        if rect[1] < r[3] and r[1] < rect[3] and rect[2] < r[4] and r[2] < rect[4] then return true end
    end
    return false
end

function Sheets.sheet_recipe(target, picks)
    local recipe
    for i, e in ipairs(target.emblems or {}) do
        local pick = picks[i]
        if pick and e.rect and e.sheet_format == Sheets.SHEET_FORMAT and (not recipe or recipe.name == e.sheet) then
            recipe = recipe or {name = e.sheet, width = e.sheet_width, height = e.sheet_height, mips = e.sheet_mips,
                                size = bc3_bytes(e.sheet_width, e.sheet_height, e.sheet_mips), cells = {}}
            if not overlaps(recipe.cells, e.rect) then
                recipe.cells[#recipe.cells + 1] = {rect = e.rect, shift = {step(pick.L - e.L), step(pick.a - e.a),
                                                                           step(pick.b - e.b)}}
            end
        end
    end
    return recipe
end

-- A recipe as a string (the sheets kept are keyed by it).
local function sheet_key(recipe)
    local parts = {recipe.name}
    for _, cell in ipairs(recipe.cells) do
        local r, d = cell.rect, cell.shift
        parts[#parts + 1] = string.format('%d,%d,%d,%d:%.9g,%.9g,%.9g', r[1], r[2], r[3], r[4], d[1], d[2], d[3])
    end
    return table.concat(parts, ';')
end

local sheets_kept, sheets_order = {}, {}
-- Every prepared sheet anything still references (a result a controller has bound, the local player's, the preview's
-- or a squadmate's), found again by its recipe before another copy is made: SHEETS_KEPT alone made six 5.6 MB copies
-- for the recipes 1, 2, 3, 1, 2, 3 of three live capes (the audit, rank 6). Weak: it keeps nothing alive.
local sheets_live = setmetatable({}, {__mode = 'v'})

-- key's spec among the kept ones, most recently used last; the oldest past SHEETS_KEPT is let go.
local function keep_sheet(key, spec)
    for i, k in ipairs(sheets_order) do
        if k == key then table.remove(sheets_order, i) break end
    end
    sheets_kept[key], sheets_order[#sheets_order + 1] = spec, key
    if #sheets_order > Sheets.SHEETS_KEPT then sheets_kept[table.remove(sheets_order, 1)] = nil end
end

-- The sheet data of a recipe (a job's: ctx with p, the pipeline, cape_kit and deps): {sheet = true, width, height,
-- mips, size, data (uint8_t pointer, outside the Lua heap)}, the recolored copy of the cape's sheet; nil and why when
-- the sheet cannot be read. yield() between the steps and inside the recolor.
function Sheets.sheet_spec(ctx, recipe, yield)
    local key = sheet_key(recipe)
    local spec = sheets_kept[key] or sheets_live[key]
    if spec then
        keep_sheet(key, spec)
        return spec
    end
    local original, why = ctx.p.sheet(recipe, ctx.cape_kit.archive)
    if not original then return nil, why end
    local data = c_buffer(recipe.size)
    for at = 0, recipe.size - 1, Sheets.SHEET_CHUNK * 4 do -- about 0.1 ms a piece outside the game
        ffi.copy(data + at, original + at, math.min(Sheets.SHEET_CHUNK * 4, recipe.size - at))
        yield()
    end
    for _, cell in ipairs(recipe.cells) do
        ctx.deps.Capes.recolor_sheet(data, recipe, cell, ctx.deps.Colour, yield)
    end
    spec = {sheet = true, width = recipe.width, height = recipe.height, mips = recipe.mips, size = recipe.size,
            data = data, name = recipe.name}
    spec.recipe_sum, spec.sample = ctx.deps.Capes.sheet_sums(key, data, recipe.size)
    sheets_live[key] = spec
    keep_sheet(key, spec)
    return spec
end

-- Recolor's sheet functions and constants (src/recolor.lua calls them through Recolor).
function Sheets.attach(Recolor)
    Recolor.sheet_recipe, Recolor.sheet_spec, Recolor.c_buffer = Sheets.sheet_recipe, Sheets.sheet_spec, Sheets.c_buffer
    Recolor.SHEETS_KEPT, Recolor.SHEET_FORMAT = Sheets.SHEETS_KEPT, Sheets.SHEET_FORMAT
    Recolor.SHEET_CHUNK, Recolor.SHIFT_STEP = Sheets.SHEET_CHUNK, Sheets.SHIFT_STEP
end

-- Runs inside jobs, once per recipe: interpreted.
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({c_buffer, bc3_bytes, step, overlaps, Sheets.sheet_recipe, sheet_key, keep_sheet,
        Sheets.sheet_spec, Sheets.attach}) do
        jit.off(fn, true)
    end
end

return Sheets
end)()
local Sync = (function()
-- Match Your Colors: Sync With Mod Users. Each player's color settings travel as a PlayFab lobby member property of
-- the squad's lobby (KB match-your-colors-multiplayer-visibility, match-your-colors-schemes-sync); every mod user then
-- recolors the others' Helldivers locally (src/remote.lua). Non-modded games read member properties only by their own
-- keys, so the extra key changes nothing for them.
--
-- Lobby (Steam build 25480438, as Better Lobby Management reads it): network context [game + 0x347CEF0], engine
-- lobby +0x1D470, its PlayFab lobby +0x10: members +0x100, state +0x118 (3 = joined), lobby handle +0x120 (an exact
-- 64-bit token: read as uint64, never through a double), the local user's entity key {id, type} +0x130. Entity ids
-- are peer ids in hex without zero padding (KB lobby-manager-session-research). PlayFab's exports come from
-- PlayFabMultiplayerWin.dll (GetModuleHandleA, GetProcAddress once per session).
--
-- Values, two member properties posted together (v1.5, user request 2026-10-15: no new key per new option):
--   * KEY2 'cbmyc2': fields 'name=value;' in any order: v the format level a reader must know (LEVEL), m the mode, f
--     the flags (complete sets 1, hoods recolored 2, materials matched 4, cape recolored 8, weapons recolored 16,
--     cape hidden 32: Hide Cape, 2026-10-16, which squadmates' copies honor on their screens), s
--     the paint scheme. A reader takes the fields and flag bits it knows and ignores the others, so a new option is a
--     new bit or field that older copies skip; v rises only when an existing field changes its meaning (older copies
--     then refuse the value, as they must).
--   * KEY 'cbmyc' (v1.3-v1.4's): '<version>|<mode>|<flags>|<scheme>' with flags under 16. Those copies refuse any
--     other value whole and read no other key; it is posted alongside until they are rare, then dropped.
-- A member's value is read from KEY2 first and from KEY only when KEY2 is missing (an older copy): a copy that read
-- KEY first would miss a later version that posts KEY2 alone.
-- Posts are rare: once per lobby and after an options change has settled for POST_DELAY_FRAMES; never while not
-- joined (a failed post can set the game's lobby session state 4), and only once the lobby has stayed joined under
-- one handle for STEADY_FRAMES. A post names the local user by PlayFab's own key of the local member (from its member
-- list), never by the game's copy at PL_USER: on arrival on the ship that copy was not yet valid, PFLobbyPostUpdate
-- read a bad string pointer through it and the game crashed (user, 2026-10-07; dump at
-- PlayFabMultiplayerWin+0x5fde4). Reads run on the caller's poll (every POLL_FRAMES): 7 memory reads for the lobby,
-- one member list, then per member 2 reads (the local member's 4) and, for the others while this player shares, one
-- member property and 1 read (two properties for a member without KEY2: an older copy, or a player without the mod). All game memory is read through bingus_memory's read_into
-- (pointer objects kept per address); PlayFab's strings are copied the same way. The poll's tables are reused.
local ffi = require('ffi')

local Sync = {}

Sync.KEY, Sync.KEY2, Sync.VERSION, Sync.LEVEL = 'cbmyc', 'cbmyc2', 1, 1
Sync.DLL = 'PlayFabMultiplayerWin.dll'
Sync.TEXT_MAX = 127 -- the longest value read or posted
Sync.POLL_FRAMES, Sync.POST_DELAY_FRAMES, Sync.RETRY_FRAMES, Sync.STEADY_FRAMES = 120, 300, 1800, 600
Sync.CONTEXT, Sync.LOBBY, Sync.PLAYFAB = 0x2E38228, 0x1D478, 0x10
Sync.PL_MEMBERS, Sync.PL_STATE, Sync.PL_HANDLE, Sync.PL_USER = 0x100, 0x118, 0x120, 0x130
Sync.JOINED, Sync.MAX_MEMBERS = 3, 16
local HIGH = 4294967296
local U64 = ffi.typeof('uint64_t')

-- The options each flag bit carries; KEY's value holds the bits under LEGACY_FLAGS + 1 only.
Sync.FLAGS = {{'keep_sets', 1}, {'recolor_hoods', 2}, {'match_materials', 4}, {'recolor_cape', 8},
              {'recolor_weapons', 16}, {'cape_hidden', 32}}
local LEGACY_FLAGS = 15
local MODES, SCHEMES = 4, 64

local function flags_of(o)
    local flags = 0
    for _, flag in ipairs(Sync.FLAGS) do
        if o[flag[1]] then flags = flags + flag[2] end
    end
    return flags
end

-- Options from a mode, flags and scheme, or nil when a copy cannot show them (a mode or scheme it does not have).
local function options_of(mode, flags, scheme)
    if not (mode and flags and scheme) or mode < 1 or mode > MODES or mode % 1 ~= 0 or scheme > SCHEMES
        or scheme % 1 ~= 0 then
        return nil
    end
    local o = {mode = mode, scheme = scheme}
    for _, flag in ipairs(Sync.FLAGS) do o[flag[1]] = math.floor(flags / flag[2]) % 2 == 1 end
    return o
end

-- KEY2's value for options {mode, scheme and the FLAGS options}.
function Sync.encode(o)
    return string.format('v=%d;m=%d;f=%d;s=%d;', Sync.LEVEL, o.mode, flags_of(o), o.scheme or 0)
end

-- KEY's value (v1.3-v1.4's format) for the same options: the flags they know.
function Sync.legacy(o)
    return string.format('%d|%d|%d|%d', Sync.VERSION, o.mode, flags_of(o) % (LEGACY_FLAGS + 1), o.scheme or 0)
end

-- A KEY2 value's fields {name = text}, or nil when it is not a list of 'name=value;' (a value cut short included).
local function fields_of(text)
    if text:gsub('[%a_][%w_]*=[^;=]*;', '') ~= '' then return nil end
    local fields = {}
    for name, value in text:gmatch('([%a_][%w_]*)=([^;=]*);') do fields[name] = value end
    return fields
end

-- The options a value of either key carries, or nil (a level or mode this copy does not know, anything malformed).
-- Unknown KEY2 fields and flag bits are ignored. Options this version knows but the value does not carry are false.
function Sync.decode(text)
    if type(text) ~= 'string' or #text == 0 or #text > Sync.TEXT_MAX then return nil end
    local version, mode, flags, scheme = text:match('^(%d+)|(%d+)|(%d+)|(%d+)$')
    if version then
        if tonumber(version) ~= Sync.VERSION or tonumber(flags) > LEGACY_FLAGS then return nil end
        return options_of(tonumber(mode), tonumber(flags), tonumber(scheme))
    end
    local fields = fields_of(text)
    local level = fields and tonumber(fields.v)
    if not level or level > Sync.LEVEL then return nil end
    local f = tonumber(fields.f or '0')
    if not f or f < 0 or f % 1 ~= 0 or f >= 2 ^ 31 then return nil end
    return options_of(tonumber(fields.m), f, tonumber(fields.s or '0'))
end

-- The peer id of an entity id: up to 16 hex digits (the engine prints peer ids with %llX, no zero padding, and
-- parses entity ids with strtoull base 16) -> low and high 32 bits (exact; no double above 2^53), or nil.
function Sync.peer_of(id)
    if type(id) ~= 'string' or #id < 1 or #id > 16 or id:find('[^%x]') then return nil end
    local padded = string.rep('0', 16 - #id) .. id
    return tonumber(padded:sub(9, 16), 16), tonumber(padded:sub(1, 8), 16)
end

local declared = false
local function declare()
    if declared then return end
    declared = true
    -- Names of their own (the first cdef of a name wins in a Lua state every mod shares); pcall: a second copy of
    -- this module in the same state finds them declared.
    pcall(ffi.cdef, [[
void *MycGetModuleHandleA(const char *name) __asm__("GetModuleHandleA");
void *MycGetProcAddress(void *module, const char *name) __asm__("GetProcAddress");
typedef struct MycEntityKey { const char *id; const char *type; } MycEntityKey;
typedef struct MycMemberUpdate { uint32_t count; const char *const *keys; const char *const *values; } MycMemberUpdate;
typedef int32_t (*MycPostUpdate)(uint64_t lobby, const MycEntityKey *user, const void *lobby_update,
                                 const MycMemberUpdate *member_update, void *context);
typedef int32_t (*MycGetMembers)(uint64_t lobby, uint32_t *count, const MycEntityKey **members);
typedef int32_t (*MycGetMemberProperty)(uint64_t lobby, const MycEntityKey *member, const char *key,
                                        const char **value);
]])
end

-- PlayFab's lobby calls as {post(handle, key address (PlayFab's own key of the local member), text or nil (KEY2's
-- value), legacy or nil (KEY's): both keys in one update, nil removes a key), members(handle) -> count, array address
-- or nil, hresult, property(handle, member address, legacy) -> value address or nil, hresult (KEY2's, or KEY's with
-- legacy)}, or nil and why. Every buffer is made here once; a call allocates only its pointer and result boxes.
-- lookup(name, ctype): an export as ctype or nil (default: PlayFabMultiplayerWin.dll's; tests give their own).
function Sync.natives(lookup)
    declare()
    if not lookup then
        local C = ffi.C
        local module = C.MycGetModuleHandleA(Sync.DLL)
        if module == nil then return nil, Sync.DLL .. ' not loaded' end
        lookup = function(name, ctype)
            local proc = C.MycGetProcAddress(module, name)
            if proc == nil then return nil end
            return ffi.cast(ctype, proc)
        end
    end
    local post = lookup('PFLobbyPostUpdate', 'MycPostUpdate')
    local members = lookup('PFLobbyGetMembers', 'MycGetMembers')
    local property = lookup('PFLobbyGetMemberProperty', 'MycGetMemberProperty')
    if not (post and members and property) then return nil, 'PlayFab lobby exports missing' end
    local KEY_PTR = ffi.typeof('const MycEntityKey *')
    local key, key2 = ffi.new('char[8]', Sync.KEY), ffi.new('char[8]', Sync.KEY2)
    local value, value2 = ffi.new('char[?]', Sync.TEXT_MAX + 1), ffi.new('char[?]', Sync.TEXT_MAX + 1)
    local keys, values = ffi.new('const char *[2]'), ffi.new('const char *[2]')
    keys[0], keys[1] = key2, key
    local update = ffi.new('MycMemberUpdate')
    update.count, update.keys, update.values = 2, keys, values
    local count, list, out = ffi.new('uint32_t[1]'), ffi.new('const MycEntityKey *[1]'), ffi.new('const char *[1]')
    -- Every buffer the update points into stays referenced for the session: a pointer stored in a struct field keeps
    -- no cdata alive. The keys array, referenced by nothing else, was collected after this function returned and its
    -- memory reused; PFLobbyPostUpdate then read a garbage key pointer through it and the game crashed (user,
    -- 2026-10-07; dump at PlayFabMultiplayerWin+0x5fde4 reading keys[0] = 0x13FE3012E).
    local api = {keep = {key, key2, value, value2, keys, values, update, count, list, out}}
    -- values[i]: text copied into buffer, or nil (removes the key).
    local function set(i, buffer, text)
        if text then
            ffi.copy(buffer, text:sub(1, Sync.TEXT_MAX))
            values[i] = buffer
        else
            values[i] = nil
        end
    end
    function api.post(handle, user, text, legacy)
        set(0, value2, text)
        set(1, value, legacy)
        return post(handle, ffi.cast(KEY_PTR, user), nil, update, nil)
    end
    function api.members(handle)
        local result = members(handle, count, list)
        if result ~= 0 then return nil, nil, result end
        return count[0], tonumber(ffi.cast(U64, list[0])), 0
    end
    function api.property(handle, member, legacy)
        out[0] = nil
        local result = property(handle, ffi.cast(KEY_PTR, member), legacy and key or key2, out)
        if result ~= 0 then return nil, result end
        if out[0] == nil then return nil, 0 end
        return tonumber(ffi.cast(U64, out[0])), 0
    end
    return api
end

-- Safe reads for the session into one buffer: u32 and u64 (an address as a number) or nil, halves (a 64-bit value's
-- low and high 32 bits) or nil, text (a C string up to TEXT_MAX bytes; nil when it does not end within the bytes
-- read, so a value is never taken cut short) or nil. Shorter reads are tried when a long one fails (a string near the
-- end of readable memory). One pointer object per address is kept (the lobby's addresses are stable; the cache starts
-- over at 256). memory: bingus_memory.
local TEXT_SIZES = {Sync.TEXT_MAX + 1, 64, 48, 24, 16, 8}
local function reader(memory)
    local U8P = ffi.typeof('const uint8_t *')
    local bytes = ffi.new('uint8_t[?]', Sync.TEXT_MAX + 1)
    local pointers, cached = {}, 0
    local self = {}
    local function read(address, size)
        if not address or address < 0x10000 or address >= 0x800000000000 then return nil end
        local p = pointers[address]
        if not p then
            if cached >= 256 then pointers, cached = {}, 0 end
            p = ffi.cast(U8P, address)
            pointers[address], cached = p, cached + 1
        end
        return memory.read_into(p, size, bytes) and bytes or nil
    end
    local function u32_at(b, o) return b[o] + b[o + 1] * 256 + b[o + 2] * 65536 + b[o + 3] * 16777216 end
    function self.u32(address)
        local b = read(address, 4)
        return b and u32_at(b, 0) or nil
    end
    function self.halves(address)
        local b = read(address, 8)
        if not b then return nil end
        return u32_at(b, 0), u32_at(b, 4)
    end
    function self.u64(address)
        local low, high = self.halves(address)
        return low and low + high * HIGH or nil
    end
    function self.text(address)
        for _, size in ipairs(TEXT_SIZES) do
            local b = read(address, size)
            if b then
                local n = 0
                while n < size and b[n] ~= 0 do n = n + 1 end
                if n == size then return nil end
                return ffi.string(b, n)
            end
        end
        return nil
    end
    return self
end

-- The squad's PlayFab lobby into out (reused): {low, high (its handle's halves), handle (uint64, made once per
-- lobby), id (the local entity id, read through the game's copy of the key: only compared, never handed to PlayFab),
-- joined, since (the poll frame it was first seen joined under this handle; the caller sets it)}; out, or nil.
local function lobby(read, game, out)
    local context = read.u64(game + Sync.CONTEXT)
    local engine = context and read.u64(context + Sync.LOBBY)
    local pl = engine and read.u64(engine + Sync.PLAYFAB)
    if not pl then return nil end
    local low, high = read.halves(pl + Sync.PL_HANDLE)
    if not low or (low == 0 and high == 0) then return nil end
    if low ~= out.low or high ~= out.high then
        out.low, out.high, out.handle = low, high, ffi.cast(U64, high) * HIGH + low -- uint64 arithmetic: exact
        out.since = nil
    end
    local id_at = read.u64(pl + Sync.PL_USER)
    out.id = id_at and read.text(id_at) or nil
    out.joined = read.u32(pl + Sync.PL_STATE) == Sync.JOINED
    return out
end

-- A sync session. deps: {memory, game, natives (Sync.natives or a test's), note}. poll(frame, text, include_local)
-- posts text (nil: sharing off) when due and returns the members' values {{peer_low, peer_high, text (or nil), local},
-- ...} (a list the next poll reuses), or nil outside a joined lobby and while sharing is off. include_local: the
-- local member too (the test build's loopback).
function Sync.session(deps)
    local read = reader(deps.memory)
    local api, why_not
    local current, list, records = {}, {}, {}
    local self = {posted_low = nil, posted_high = nil, posted_text = nil, pending = nil, changed_at = 0, next_post = 0,
                  posts = 0, failures = 0}

    local function natives()
        if api == nil and why_not == nil then
            api, why_not = deps.natives()
            if not api then deps.note('Sync: ' .. tostring(why_not) .. '.') end
        end
        return api
    end

    local function posted_here(l) return l.low == self.posted_low and l.high == self.posted_high end

    -- Posts the value when it differs from what this lobby has and it has not changed for POST_DELAY_FRAMES, once
    -- the lobby has stayed joined for STEADY_FRAMES and its member list holds the local member (l.own: PlayFab's own
    -- key of it, from this poll's member list).
    local function maybe_post(frame, l, text)
        if text ~= self.pending then self.pending, self.changed_at = text, frame end
        local due = text ~= self.posted_text or not posted_here(l)
        if not due or frame < self.next_post or frame - self.changed_at < Sync.POST_DELAY_FRAMES then return end
        if text == nil and not posted_here(l) then -- nothing of ours in this lobby to remove
            self.posted_low, self.posted_high, self.posted_text = l.low, l.high, nil
            return
        end
        if not l.own or frame - l.since < Sync.STEADY_FRAMES then return end
        local options = text and Sync.decode(text)
        local result = api.post(l.handle, l.own, text, options and Sync.legacy(options) or nil)
        self.next_post = frame + Sync.POST_DELAY_FRAMES
        if result == 0 then
            self.posted_low, self.posted_high, self.posted_text = l.low, l.high, text
            self.posts = self.posts + 1
            deps.note(text and ('Sync: shared ' .. text .. '.') or 'Sync: sharing removed.')
        else
            self.failures, self.next_post = self.failures + 1, frame + Sync.RETRY_FRAMES
            deps.note(string.format('Sync: post failed (0x%08X); retrying later.', result % HIGH))
        end
    end

    -- One member's value into the next record of list: KEY2's, else (no KEY2: an older copy) KEY's.
    local function add_member(l, key_at, low, high, own)
        local value_at, result = api.property(l.handle, key_at, false)
        if not value_at and result == 0 then value_at, result = api.property(l.handle, key_at, true) end
        local n = #list + 1
        local r = records[n] or {}
        records[n] = r
        r.peer_low, r.peer_high, r['local'] = low, high, own
        r.text = value_at and read.text(value_at) or nil
        r.failed = result ~= nil and result ~= 0 -- a failed read, not a missing value (src/remote.lua update)
        list[n] = r
    end

    -- The members' values (the local member's only with include_local) into list (reused); l.own: PlayFab's own key
    -- of the local member when its id and type read as text, else nil.
    local function members(l, include_local)
        for i = #list, 1, -1 do list[i] = nil end
        l.own = nil
        local count, array = api.members(l.handle)
        if not count then return list end
        for i = 0, math.min(count, Sync.MAX_MEMBERS) - 1 do
            local key_at = array + 16 * i
            local id = read.text(read.u64(key_at))
            local low, high = Sync.peer_of(id)
            local own = id ~= nil and id == l.id
            if own and read.text(read.u64(key_at + 8)) then l.own = key_at end
            if low and (include_local or not own) then add_member(l, key_at, low, high, own) end
        end
        return list
    end

    function self.poll(frame, text, include_local)
        local l = lobby(read, deps.game, current)
        -- Without the local entity id the local member cannot be told apart: nothing is read then.
        if not l or not l.joined or not l.id or not natives() then
            if l then l.since = nil end
            return nil
        end
        l.since = l.since or frame
        local found = members(l, include_local)
        maybe_post(frame, l, text)
        if text == nil then return nil end -- only players who share read the others' values
        return found
    end
    return self
end

-- Runs on the sync poll and at startup, never per frame: interpreted (no traces in the LuaJIT code cache every mod
-- shares).
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({flags_of, options_of, Sync.encode, Sync.legacy, fields_of, Sync.decode, Sync.peer_of, declare,
                         Sync.natives, reader, lobby, Sync.session}) do
        jit.off(fn, true)
    end
end

return Sync
end)()
local Remote = (function()
-- Match Your Colors: other mod users' Helldivers (Sync With Mod Users). From each sync poll (src/sync.lua), every
-- other player who shares valid settings gets an entry: their player record and kits (src/avatar.lua), a watch of
-- their 120 bytes of unit refs, and a controller of their own that binds pooled textures to their units
-- (src/recolor.lua). Their jobs run in the addon's single job slot, after the local avatar and UI preview. An entry
-- is restored and dropped when its player leaves, stops sharing or shares something unreadable.
-- Recolor Squadmates (v1.5, user request 2026-10-14: "a toggle for 'Apply to entire team'"): with it, players who share
-- nothing take this player's settings (mine), or every player does (everyone); a player who shares keeps their own
-- otherwise. An entry whose player has no Helldiver here (dead, not spawned yet) is kept, its textures with it, and
-- bound again when the Helldiver is back (v1.3 dropped it and ran a new job on every respawn).
--
-- The addon calls step on 1 frame in WATCH_FRAMES and check every CHECK_FRAMES frames, only while an entry exists
-- (or textures retire): step checks one entry's units (one 120-byte read, round robin) and hands textures of dropped
-- entries back to the pool after their retire delay; check reads one entry's bindings. pending: an entry waits
-- for a job.
local Remote = {}

Remote.FAILURE_LIMIT, Remote.WATCH_FRAMES = 3, 4
local EMPTY = {}

-- m: {Avatar, Recolor, Engine, Sync, memory, native, pool, game, read (Avatar.reader), note, records_same (the
-- addon's: whether a result was made of the kit records as they read now), Loadout and Weapons (optional: their
-- weapons, v1.5)}. src/lineup.lua sets session_text (the session's peers, for the note on a member that names no
-- player here).
-- Recolor Weapons (v1.5): a player whose settings carry it (cbmyc2 flag 16, or Recolor Squadmates' own settings) gets
-- their weapons recolored too, a src/loadout.lua of their own: on their watch turn (1 frame in WATCH_FRAMES, round
-- robin) their weapon in hand's LUT binding and inventory row are read (2 reads), so a reload of theirs shows their
-- weapon's own colors for up to WATCH_FRAMES frames per recolored player; on their binding check (check) and when
-- their row changed, the row is checked to be still theirs (2 reads: the game moves rows when an avatar is removed),
-- and a respawn finds their new avatar's row.
function Remote.new(m)
    local Avatar, Recolor, Sync = m.Avatar, m.Recolor, m.Sync
    local self = {entries = {}, order = {}, retiring = {}, cursor = 0, served = 0, jobs = 0, rebinds = 0,
                  pending = false, frame = 0}

    local function key_of(member) return string.format('%08x%08x', member.peer_high, member.peer_low) end

    local function same(a, b)
        return a.mode == b.mode and a.keep_sets == b.keep_sets and a.recolor_hoods == b.recolor_hoods
            and a.match_materials == b.match_materials and a.recolor_cape == b.recolor_cape and a.scheme == b.scheme
            and (a.recolor_weapons or false) == (b.recolor_weapons or false) and a.source_kit == b.source_kit
            and a.source_cape == b.source_cape
    end

    -- A job request for target with settings s on kits {helmet, armor, body, cape}, as every squadmate's job (and squad
    -- card's, src/lineup.lua) takes it: with Squadmates' Colors on Your Colors (s.source_kit or s.source_cape, src/addon.lua)
    -- this player's source item instead of the mode's own.
    local function request_of(target, key, s, kits)
        return {target = target, key = key, mode = s.mode, keep_sets = s.keep_sets, keep_hoods = not s.recolor_hoods,
                materials = s.match_materials, scheme = s.scheme, capes = s.recolor_cape, helmet = kits.helmet,
                armor = kits.armor, body = kits.body, cape = s.source_cape or kits.cape, source_kit = s.source_kit,
                source_cape = s.source_cape}
    end
    self.request_of = request_of

    local function add(key)
        local e = {key = key, failures = 0, controller = Recolor.controller({Engine = m.Engine, Avatar = Avatar,
            memory = m.memory, native = m.native, pool = m.pool})}
        self.entries[key] = e
        self.order[#self.order + 1] = key
