        end
        e.loadout = e.loadout or m.Loadout.new({Weapons = m.Weapons, Recolor = Recolor, Engine = m.Engine,
            Avatar = Avatar, memory = m.memory, native = m.native, pool = m.pool, game = m.game, read = m.read,
            note = m.note, follow = 'Sync: ' .. e.key})
