    local function drop(key, frame)
        local e = self.entries[key]
        e.controller.restore(frame)
        if e.controller.retired[1] then self.retiring[#self.retiring + 1] = e.controller end
        if e.loadout then
            weapons_summary(e)
            e.loadout.clear(frame)
